        // namespace. Enumerate it during an explicit full reset so older
        // unindexed mirrors/settings cannot survive and silently repopulate
        // the fresh profile. Keep only the short-lived recovery tombstone.
        const managerKeys = await _gmListKeys();
        await Promise.allSettled(managerKeys
          .filter(key => key !== _SE_SAFETY_RESET_KEY)
          .map(key => _gmDeleteAwait(key)));

