      primary: boot ? boot.primary : (['auto','pro','lite'].includes(settings.fiBridgePrimary) ? settings.fiBridgePrimary : 'auto'),
      syncItems: settings.fiBridgeSyncItems !== false,
      syncSettings: settings.fiBridgeSyncSettings === true,
