          reason: scan.reason,
          domNodes: scan.domNodes,
          imgs: scan.imgs,
          videos: scan.videos,
          canvases: scan.canvases,
          iframes: scan.iframes,
          webglCanvasCount: scan.webglCanvasCount,
          itemCards: scan.itemCards,
          animationEls: scan.animationEls,
          mediaVisible: scan.mediaVisible,
          mediaOffscreen: scan.mediaOffscreen,
          mediaPlayingVideos: scan.mediaPlayingVideos,
