      peakAllocatedMB: fiPerfHasRatio(peak?.totalMB) ? Number(peak.totalMB) : null,
      currentTs: latest.ts, currentMB, allocatedMB: totalMB, limitMB, heapSlackMB, liveRatio, limitPressure,
      settledMB: floor, settledAllocatedMB: settledTotalMB, recoveryMB, recoveryRatio,
      recoveryTs, timeToRecoveryMs: recoveryTs == null ? null : Math.max(0, recoveryTs - Number(peak?.ts || recoveryTs)),
      peakDurationMs, excessMBSeconds, troughCount: troughs.length, troughSpanMs, troughRiseMB, floorSlopeMBMin,
