    const cooldown = Math.max(1000, Number(settings.perfHeapResidencyGuardCooldownMs) || 60000);
    if (!fiPerfGuardStreakReady(state.heapResidencyGuardStreak, state.heapResidencyGuardEligibleSince, hold, Number(sample.ts) || Date.now()) || Date.now() - Number(state.heapResidencyGuardLastTs || 0) < cooldown) return result;
