    const limit = Math.min(2000, Math.max(20, Math.floor(Number(settings.perfSmartCleanupBurstReliefMaxNodes) || 240)));
    const margin = Math.min(5000, Math.max(0, Math.floor(Number(settings.perfSmartCleanupBurstReliefMarginPx) || 650)));
