      const icon = document.createElement('span');
      icon.style.cssText = `width:30px;height:30px;border-radius:9px;display:grid;place-items:center;background:${entry.color}22;color:${entry.color};font-size:15px;`;
      icon.innerHTML = '<i class="fas fa-bell"></i>';
      const body = document.createElement('div');
      const title = document.createElement('b');
      title.style.cssText = `display:block;color:${entry.color};font-size:11.5px;`;
