    const message = `${series.shortLabel || series.label} reached the ${fiPerfNotificationNumber(marker?.value)} ${series.unit || ''} limit in the last ${seconds}s. Current ${fiPerfNotificationNumber(details.current)}; range ${fiPerfNotificationNumber(details.minimum)}–${fiPerfNotificationNumber(details.maximum)} ${series.unit || ''}.`;
