    add('media', 'Media decode/layout pressure', Math.min(26, media / 24 + mediaGrowth * 1.8), `${media.toLocaleString()} media element(s) are retained${mediaGrowth ? `, up ${mediaGrowth} since the previous sample` : ''}. Decoding and compositing can raise browser CPU/GPU work without matching JS-heap growth.`, 'Switch Items Media Loading to Click or Off for the next comparison and watch Lag, media, and Chrome-pressure indexes together.', `${media.toLocaleString()} media · +${mediaGrowth}`);
    const xhrMs = Math.max(0, Number(sample.xhrMs) || 0);
    const dbMs = Math.max(0, Number(sample.dbMs) || 0);
    add('io', 'Request/storage callbacks', Math.min(20, xhrMs / 180 + dbMs / 45), `Recent overlapping windows contain ${Math.round(xhrMs)} ms of request time and ${Math.round(dbMs)} ms of IndexedDB callbacks.`, 'Wait for the orange/blue activity to settle before judging a watcher change; inspect slow endpoints if it repeats.', `${Math.round(xhrMs)} ms XHR · ${Math.round(dbMs)} ms DB`);
    const surge = Math.max(0, Number(sample.surgeScore) || 0);
    const debt = Math.max(0, Number(sample.scrollDebt) || 0);
    add('scroll', 'Scroll batch pressure', Math.min(24, surge * 10 + debt * 3), `Surge is ${surge.toFixed(2)} and scroll debt is ${debt.toFixed(2)}; sudden insert/decode batches often make CPU feel high before long-window averages react.`, 'Stop scrolling briefly, let the settle guard run, then compare whether blocked time and DOMΔ return toward zero.', `surge ${surge.toFixed(2)} · debt ${debt.toFixed(2)}`);
