        (latestNative.nativeReasons || []).slice(0, 3).forEach(reason => notes.push(`Native FI Unit reason: ${reason.title}. ${reason.evidence}`));
        (latestNative.nativeRecommendations || []).slice(0, 2).forEach(item => notes.push(`Native FI Unit recommendation (${item.priority || 'advisory'}): ${item.title}. ${item.action}`));
