  function fiPerfBuildPlaybook(models = [], hits = [], sample = FI_PERF_MONITOR_STATE.samples.at(-1) || null, samplesOverride = null) {
    const sourceSamples = Array.isArray(samplesOverride) && samplesOverride.length ? samplesOverride : (FI_PERF_MONITOR_STATE.samples || []);
    const byKey = key => models.find(model => model.key === key);
    const watcherSummary = fiPerfActiveWatcherSummary();
    const actualHits = fiPerfRecentBreakpointHits(6, 0, Number(sourceSamples.at(-1)?.ts));
    const inflation = fiPerfScrollInflationSummary(sourceSamples);
    const heap = byKey('heap');
    const dom = byKey('dom');
    const media = byKey('media');
    const lag = byKey('longtask');
    const db = byKey('db');
    const xhr = byKey('xhr');
    const anim = byKey('anim');
    const watchers = byKey('watchers');
    const debt = byKey('scrollDebt');
    const budget = byKey('domBudget');
    const items = [];
    const add = (group, priority, title, why, action, metric, path, color = '#22d3ee', source = '') => {
      items.push({ group, priority, title, why, action, metric, path, color, source });
    };
    add('Baseline', 'P0', 'Mark a clean comparison window', 'A/B comparisons are only useful when each setting change has a stable before and after window.', 'Set Base, A, and B markers before changing watchers, media loading, animations, or graph settings.', 'A/B and A+/B+ point spans', 'Performance Monitor > Graph > A/B markers', '#22d3ee');
    add('Baseline', 'P0', 'Change one pressure source at a time', 'Changing multiple watchers or media settings at once makes prediction residuals and hit-rate math harder to interpret.', 'Toggle one Pro watcher group, wait one prediction horizon, then compare heap, DOM, lag, XHR, and DB deltas.', `${Math.round(Number(settings.perfMonitorPredictionHorizonSec) || 90)}s horizon`, 'Settings > Performance > Pro Watchers', '#a5b4fc');
    if (sample?.unitConnected) {
      const browserCpu = Number(sample.unitBrowserCpuPct || 0);
      const systemCpu = Number(sample.unitSystemCpuPct || 0);
      if (browserCpu >= 45 || systemCpu >= 75) {
        add('Native evidence', browserCpu >= 80 || systemCpu >= 92 ? 'P0' : 'P1', 'Correlate native CPU with page evidence', `FI Performance Unit reports browser-process CPU ${browserCpu.toFixed(1)}% and system CPU ${systemCpu.toFixed(1)}% with ${sample.unitCorrelationLevel || 'low'} correlation. Process aggregates can include other tabs and workers.`, 'Mark A now, pause optional watchers or media previews for one window, then compare native CPU, long tasks, DOM bursts, and XHR together. Do not terminate or suspend renderer processes automatically.', `browser RAM ${Number(sample.unitBrowserMemoryMB || 0).toFixed(0)} MB`, 'Performance Monitor > Native filters / FI Performance Unit', '#10b981');
      }
    } else if (settings.perfUnitEnabled) {
      add('Native evidence', 'P2', 'Restore the FI Performance Unit connection', 'The localhost companion is enabled but its snapshot is stale or unavailable, so native guard conditions are intentionally ignored.', 'Use Test connection in Appearance > Performance Monitor > FI Performance Unit. Verify the loopback URL and bearer token.', fiPerfUnitState().lastError || 'no fresh snapshot', 'Appearance > Performance Monitor Floating Window > FI Performance Unit', '#10b981');
    }
    if (sample?.xhrBurstActive) {
      add('Network', 'P1', 'Separate the request burst from render cost', `${Number(sample.xhrBurstCount || 0)} requests consumed ${Math.round(Number(sample.xhrBurstMs || 0))} ms inside the current burst window.`, 'Compare XHR, long tasks, DOMΔ, and native/browser CPU over the same A/B interval before changing graph sampling.', `${Math.round(Number(sample.xhrBurstWindowMs || 0) / 1000)}s burst window`, 'Performance Monitor > XHR line / Analyze', '#fdba74');
    }
    {
      const t = fiPerfSurgeThresholds();
      const surgeScore = Number(sample?.surgeScore || 0);
      if (surgeScore >= 0.75) {
        add('Scroll', surgeScore >= 1.75 ? 'P0' : 'P1', 'Absorb the sudden scroll surge first', `The latest sample jumped with surge score ${surgeScore.toFixed(2)}: DOM +${Math.round(Number(sample?.surgeDomDelta || 0)).toLocaleString()}, media +${Math.round(Number(sample?.surgeMediaDelta || 0))}, heap +${Number(sample?.surgeHeapDelta || 0).toFixed(1)} MB. This pattern can accompany a tab-memory jump before long-window pressure lines fully react.`, surgeScore >= 1.75 ? 'Let Surge guard run belt-soft-burst or switch mode to Smart if the page keeps holding far-offscreen media. Then compare Surge x100, Relief x5, DOM/100, and Browser pressure /2.' : 'Keep Surge guard armed and use Click/Off media for the next long scroll so one inserted batch does not eagerly decode all previews.', `limits DOM +${t.dom.toLocaleString()}, media +${t.media}, heap +${t.heap} MB, burst +${t.burst.toLocaleString()}`, 'Appearance > Performance Monitor Floating Window > Surge guard', '#fb7185');
      }
      const coolIds = Array.from(new Set(FI_PERF_MONITOR_STATE.surgeCooloffWatcherIds || []));
      const cfg = fiPerfSurgeCooloffConfig();
      if (coolIds.length) {
        add('Watchers', 'P1', 'Let surge watcher cool-off finish before judging the graph', `The hard surge temporarily paused ${coolIds.length} watcher(s): ${coolIds.map(id => fiProWatcherDef(id)?.title || id).join(', ')}. This reduces MutationObserver and injected-UI pressure while Tensor finishes inserting the new card batch.`, 'Wait for the restore event, then compare the Watch x20 line and long-task line over the next A/B window.', `restores in ${Math.max(0, Math.ceil((Number(FI_PERF_MONITOR_STATE.surgeCooloffUntil || 0) - Date.now()) / 1000))}s`, 'Performance Monitor > Guard', '#fb7185');
      } else if (cfg.enabled && surgeScore >= cfg.minScore * 0.7) {
        add('Watchers', 'P2', 'Keep surge watcher cool-off armed for the next scroll batch', `The current surge score is near the watcher cool-off trigger (${surgeScore.toFixed(2)} / ${cfg.minScore.toFixed(2)}). If the next scroll inserts another large batch, high-cost watchers can be paused automatically for ${Math.round(cfg.durationMs / 1000)}s.`, 'Use high/medium scope while tuning; switch to high-only if you want less automatic intervention.', `scope ${cfg.costs}, max ${cfg.max}`, 'Appearance > Performance Monitor Floating Window > Surge watcher cool-off', '#fb7185');
      }
    }
    if (heap?.direction === 'rising' || (sample?.usedMB || 0) > (Number(settings.perfMemAlertThresholdMB) || 500)) {
      add('Heap', 'P0', 'Reduce retained media and rendered cards', 'A rising heap line usually means decoded media, retained item cards, or cached payloads are not being released quickly enough.', 'Switch Items Media Loading to Click or Off, enable Drop Images, then clear cache after exporting needed data.', `${heap ? `${heap.rate >= 0 ? '+' : ''}${heap.rate.toFixed(3)}/s, ${Math.round(heap.confidence * 100)}% confidence` : `${Math.round(sample?.usedMB || 0)} MB`}`, 'Settings > Performance > Media Loading', '#fbbf24');
    }
    {
      const t = fiPerfScrollDebtThresholds();
      const score = Number(sample?.scrollDebt ?? FI_PERF_MONITOR_STATE.scrollDebtScore ?? 0);
      if (score >= t.trigger || debt?.direction === 'rising') {
        add('Scroll', score >= t.relief ? 'P0' : 'P1', 'Pay down scroll debt before the next big jump', 'Scroll debt rises before hard limits when scroll distance, DOM insertions, media growth, heap growth, and the browser-pressure proxy are accumulating together.', score >= t.relief ? 'Let the governor run viewport belt plus soft/burst relief, or run Viewport memory belt now and switch Items Media Loading to Click/Off for the next long scroll.' : 'Keep the viewport belt armed and watch whether Debt x90 falls after scrolling stops. If it keeps rising, lower the debt trigger or enable Soft scroll relief.', `score ${score.toFixed(2)} / ${t.trigger.toFixed(2)}, relief ${t.relief.toFixed(2)}`, 'Appearance > Performance Monitor Floating Window > Scroll debt governor', '#f97316');
      }
    }
    {
      const info = sample ? fiPerfDomBudgetScore(sample) : null;
      if (info && (info.score >= 1 || budget?.direction === 'rising' || FI_PERF_MONITOR_STATE.domBudgetSweepLastAction)) {
        add('DOM', info.score >= info.thresholds.escalate ? 'P0' : 'P1',
          'Bring the page back under DOM budget',
          `Budget score ${info.score.toFixed(2)} from ${info.reason}. This catches the long-scroll state after the page has accumulated too many live nodes/media even when no single new burst is happening.`,
          info.score >= info.thresholds.escalate
            ? 'Run DOM budget sweep now or keep it in belt-soft-burst mode; if score stays high, enable DOM hibernation and compare Budget x100 with Relief x5.'
            : 'Keep budget sweep armed in belt-soft mode and watch Budget x100 fall below the trigger after the viewport belt runs.',
          `DOM ${info.dom.toLocaleString()}/${info.thresholds.dom.toLocaleString()}, media ${info.media}/${info.thresholds.media}, heap ${info.heap.toFixed(1)}/${info.thresholds.heap} MB`,
          'Appearance > Performance Monitor Floating Window > DOM budget sweep',
          '#38bdf8');
      }
    }
    if (inflation?.likely) {
      add('Scroll', 'P0', 'Treat the page as scroll-inflated', `Over ${inflation.seconds.toFixed(0)}s the page grew by DOM ${inflation.domDelta >= 0 ? '+' : ''}${Math.round(inflation.domDelta).toLocaleString()}, media ${inflation.mediaDelta >= 0 ? '+' : ''}${Math.round(inflation.mediaDelta)}, heap ${inflation.heapDelta >= 0 ? '+' : ''}${inflation.heapDelta.toFixed(1)} MB. Chrome tab memory can rise more than JS heap because decoded media and DOM backing objects live outside the measured JS heap.`, 'Run Soft relief now, keep DOM burst relief enabled, and switch FI Items media to Click if the next window keeps rising. If heap and media keep climbing, run Smart cleanup to drop far-offscreen sources.', `scroll score ${inflation.score.toFixed(1)}, browser-pressure proxy ${Number(inflation.browserPressureScore ?? inflation.estimatedChromeMB ?? 0).toFixed(0)}`, 'Performance Monitor > Notes / Settings > Performance > Smart cleanup', '#f9a8d4', 'Browser memory includes decoded media and DOM outside JS heap');
      if (settings.perfPressureLadderEnabled) {
        const ladder = fiPerfPressureLadderPlan(inflation, sample, settings.perfScrollInflationGuardMode || 'soft-burst');
        add('Scroll', ladder?.action === 'smart' ? 'P0' : 'P1', 'Let the pressure ladder pick the lightest relief rung', 'The ladder compares scroll score, DOM/media/heap deltas, and hard cleanup limits so small scroll jumps use soft relief while severe jumps escalate to burst or smart cleanup.', `Current plan: rung ${ladder?.rung ?? 0} ${ladder?.action || 'waiting'}${ladder?.canHibernate ? ' plus hibernation recommendation' : ''}. Use Pressure ladder now from the graph menu to test it immediately.`, `burst ${Number(settings.perfPressureLadderBurstScore || 1.8).toFixed(2)} / hibernate ${Number(settings.perfPressureLadderHibernationScore || 4.6).toFixed(2)}`, 'Appearance > Performance Monitor Floating Window > Pressure ladder', '#fb923c');
      }
    }
    if (settings.perfViewportBeltEnabled) {
      const cfg = fiPerfViewportBeltConfig();
      const belt = FI_PERF_MONITOR_STATE.viewportBeltLastResult;
      add('Scroll', 'P1', 'Use the viewport memory belt during long scrolls', 'The belt treats distance from the viewport as pressure: warm offscreen nodes get containment and lazy media, cold offscreen media can release sources, and far frozen zones can optionally hibernate DOM.', 'Run Viewport memory belt now, then watch the teal Relief line, media count, and ChromeΔ estimate for the next 20-30 seconds.', belt ? `${belt.contained} contained / ${belt.dropped} dropped / ${belt.hibernated} hibernated last pass` : `warm ${Math.round(cfg.warm)}px · cold ${Math.round(cfg.cold)}px`, 'Appearance > Performance Monitor Floating Window > Viewport memory belt', '#e879f9', 'content-visibility / lazy media / optional tombstones');
    } else if (inflation?.likely || (sample?.mediaEls || 0) > 120 || (sample?.domNodes || 0) > 9000) {
      add('Scroll', 'P2', 'Arm the viewport memory belt for scroll-heavy pages', 'Soft relief waits for threshold crossings; the belt can work earlier by reducing offscreen layout, decoding, and media source pressure based on distance bands.', 'Enable Viewport memory belt in Performance settings, keep mode Conservative first, then compare A/B after a long scroll.', 'belt disabled', 'Appearance > Performance Monitor Floating Window > Viewport memory belt', '#e879f9');
    }
    {
      const chromePressure = fiPerfChromePressureEstimateAt(sourceSamples, -1);
      const chromeGuard = fiPerfChromePressureThresholds();
      if (settings.perfChromePressureGuardEnabled && chromePressure >= chromeGuard.limit * 0.85) {
        add('Browser memory', chromePressure >= chromeGuard.relief ? 'P0' : 'P1', 'Let browser-pressure guard reduce page pressure', `The dimensionless browser-pressure proxy is ${chromePressure.toFixed(0)} against a ${chromeGuard.limit} guard line and ${chromeGuard.relief} relief line. It ranks normalized media, DOM, storage, request, and heap evidence; it is not Chrome tab memory in MB.`, chromePressure >= chromeGuard.relief ? 'Keep the guard in belt-soft-burst mode or run Pressure ladder now; it can combine viewport belt, soft relief, and burst relief.' : 'Keep the guard armed in belt-soft mode, then compare Browser pressure /2 and teal Relief markers after the next long scroll.', `mode ${chromeGuard.mode}, cooldown ${Math.round(chromeGuard.cooldown / 1000)}s`, 'Appearance > Performance Monitor Floating Window > Browser-pressure guard', '#e879f9');
      }
      if (chromePressure > 180) {
        add('Browser memory', chromePressure > 450 ? 'P0' : 'P1', 'Treat Chrome task memory separately from JS heap', `Browser pressure /2 is a ${chromePressure.toFixed(0)}-point mixed-evidence score. It can flag a useful experiment but cannot estimate the tab-hover footprint or the non-JS remainder.`, 'Switch media loading to Click/Off, run Pressure ladder now, then compare the purple browser-pressure line and teal Relief line after 20-30 seconds.', `browser-pressure score ${chromePressure.toFixed(0)}`, 'Performance Monitor > Graph > Browser pressure / Pressure ladder', '#e879f9');
      }
    }
    if ((sample?.mediaEls || 0) > 90 || media?.direction === 'rising') {
      add('Media', 'P1', 'Stop eager media decoding in item lists', 'Images and video previews can cause memory pressure and main-thread decode work even when the script logic is fast.', 'Use Click-to-load media and hide preview strips while profiling watcher changes.', `${Number(sample?.mediaEls || 0).toLocaleString()} media elements`, 'Settings > Performance > Items Media Loading', '#fbbf24');
    }
    {
      const throttle = fiPerfAdaptiveMediaThrottleStatus();
      if (throttle.active || settings.perfAdaptiveMediaThrottleEnabled) {
        add('Media', throttle.active ? 'P0' : 'P2', throttle.active ? 'Let adaptive media throttle finish' : 'Keep adaptive media throttle armed', throttle.active ? `New FI item previews are temporarily using ${throttle.mode} mode because ${throttle.reason}.` : 'This prevents long scroll sessions from attaching more preview sources once the graph already shows media, heap, or DOM burst pressure.', throttle.active ? 'Wait for the cooldown before judging the next A/B sample, or manually switch Items Media Loading to Off for a stronger control run.' : 'Leave it enabled for normal browsing; use Screenshot preset only when you need raw unthrottled evidence.', throttle.active ? `${Math.ceil(throttle.secondsLeft)}s remaining` : `${settings.perfAdaptiveMediaThrottleMode || 'click'} when pressured`, 'Settings > Performance > Items Media Loading > Adaptive media throttle', '#2dd4bf');
      }
    }
    if ((sample?.domNodes || 0) > 9000 || dom?.rate > 0.18) {
      add('DOM', 'P0', 'Disable optional DOM injectors on large pages', 'Large DOM trees make every MutationObserver callback and query pass more expensive.', 'Disable community home injectors, dropdown enhancers, prompt buttons, and preview watchers that you are not using.', `${Number(sample?.domNodes || 0).toLocaleString()} DOM nodes`, 'Settings > Performance > Pro Watchers', '#f472b6');
      add('DOM', 'P1', 'Prefer skipped off-screen rendering where safe', 'Browsers can skip layout and painting for off-screen sections when content visibility is enabled, reducing render pressure on long pages.', 'Use containment/content-visibility only for FI-owned panels or virtualized list wrappers where layout size is predictable.', 'Off-screen render work', 'Settings > Performance > DOM Watchers', '#67e8f9', 'MDN content-visibility / CSS containment');
      add('DOM', 'P1', 'Hibernate far-offscreen card DOM when scrolling gets extreme', 'Content visibility reduces layout and paint, but the DOM nodes still exist. Hibernation removes safe far-offscreen card nodes from the live document and keeps a restoreable tombstone.', 'Use the monitor menu action first. If it helps, enable DOM Hibernation and keep Auto Restore on so cards return before they reach the viewport.', `${fiPerfDomHibernationStatus().active} hibernated card(s) now`, 'Appearance > Performance Monitor Floating Window > DOM Hibernation', '#2dd4bf', 'Tombstone restore strategy');
    }
    if ((sample?.domBurstAdded || 0) > 0 || settings.perfSmartCleanupBurstReliefEnabled) {
      add('DOM', 'P1', 'Contain newly inserted scroll batches', 'Infinite-scroll pages can add large card batches after every scroll. Queuing only the inserted roots avoids a full-page scan while still reducing offscreen layout and paint work.', 'Keep DOM burst relief enabled, then watch the pink DOMΔ line and teal cleanup markers after each long scroll.', `${Number(sample?.domBurstAdded || 0).toLocaleString()} inserted nodes in latest sample`, 'Settings > Performance > DOM burst relief', '#f9a8d4', 'MDN IntersectionObserver / content-visibility');
    }
    if ((sample?.longTaskMs || 0) > 180 || lag?.current > 18) {
      add('Main thread', 'P0', 'Cut animation and observer work first', 'Long tasks mean the page is blocked; memory optimizations will feel weak until the main thread settles.', 'Disable panel animations, lower graph sampling frequency, and pause heavy floating windows during page navigation.', `${Math.round(sample?.longTaskMs || 0)} ms recent long tasks`, 'Settings > Performance > Animations / Monitor Sample Rate', '#fb7185');
    }
    if ((sample?.animationEls || 0) > (Number(settings.perfMonitorAnimationThreshold) || 80) || anim?.direction === 'rising') {
      add('Animations', 'P1', 'Disable decorative animation while profiling', 'Animated UI elements can increase style and paint work, especially when the monitor graph is open.', 'Turn off nonessential FI panel animation and keep graph glow disabled on low-end devices.', `${Number(sample?.animationEls || 0).toLocaleString()} animated nodes`, 'Settings > Appearance > Animations / Performance Monitor Floating Window', '#34d399');
    }
    if ((sample?.dbMs || 0) > (Number(settings.perfMonitorDbThresholdMs) || 60) * 2 || db?.current > 6) {
      add('IndexedDB', 'P1', 'Wait for hydration before judging watcher cost', 'IndexedDB flush and hydration callbacks can briefly compete with rendering and make a good watcher setting look slow.', 'Let the blue DB line settle, then compare the same A/B window again.', `${sample?.dbOps || 0} ops / ${Math.round(sample?.dbMs || 0)} ms`, 'Performance Monitor > Model > Actual hit ledger', '#60a5fa');
    }
    if ((sample?.xhrMs || 0) > (Number(settings.perfMonitorXhrThresholdMs) || 900) || xhr?.direction === 'rising') {
      add('Network', 'P1', 'Separate API latency from script overhead', 'Slow Tensor/API calls can dominate perceived loading time and hide local DOM improvements.', 'Use the XHR line, tooltip endpoint names, and slow request notes before changing DOM settings again.', `${sample?.xhrOps || 0} XHR / ${Math.round(sample?.xhrMs || 0)} ms`, 'Performance Monitor > XHR filter / Tooltip', '#fdba74');
    }
    if (watcherSummary.enabled > 12 || watchers?.current > 220) {
      add('Watchers', 'P0', 'Move optional watchers into disabled profile', 'Too many active watchers on a large page increases callback pressure and query churn.', 'Disable high-cost watchers first, then save the profile as a fast mode preset.', `${watcherSummary.enabled}/${watcherSummary.total} watchers enabled`, 'Settings > Performance > Pro Watchers', '#a5b4fc');
    }
    if (settings.perfAutoDisableWatchersEnabled) {
      add('Guard', 'P1', 'Tune auto-disable recovery gap', 'A recovery line too close to the disable line can cause repeated disable/restore cycles.', 'Keep restore ratio below the disable limit enough to avoid flapping, then watch Guard events.', `restore ${(Number(settings.perfAutoDisableRecoverRatio) || 0.82) * 100}%`, 'Settings > Performance > Auto Disable Watchers', '#fb7185');
    } else {
      add('Guard', 'P2', 'Arm auto-disable for stress pages', 'When heap, DOM, or long-task limits are crossed in the background, automatic watcher disabling can protect the page.', 'Enable Auto Disable Watchers and set the metric to the pressure line that fails most often.', 'Guard disabled', 'Settings > Performance > Auto Disable Watchers', '#fbbf24');
    }
    if (hits.length) {
      add('Breakpoints', 'P1', 'Verify predicted hit against actual hit trace', 'A predicted dot is useful only if the real line later crosses near the same place.', 'Leave actual hit dots enabled and compare the predicted ETA with the hit ledger.', `${hits.length} predicted hit(s)`, 'Performance Monitor > Model > Predicted breakpoint hits', '#c084fc');
    }
    if (actualHits.length) {
      add('Breakpoints', 'P1', 'Use hit cadence to find recurring pressure', 'Repeated actual hits show recurring spikes even when the final heap number looks stable.', 'Sort the point tree around the breakpoint and compare A/B spans around repeated hit times.', `${actualHits.length} recent hit(s)`, 'Performance Monitor > Model > Actual hit ledger', '#c084fc');
    }
    const experiments = fiPerfExperimentList();
    if (FI_PERF_MONITOR_STATE.activeExperiment) {
      add('Runs', 'P1', 'Finish the active recording after the change settles', 'A recording is active, so the monitor can create a reusable before/after run once the graph stabilizes.', 'Stop the run after one prediction horizon, then record a second run with the next watcher/media profile.', `${((Date.now() - Number(FI_PERF_MONITOR_STATE.activeExperiment.startTs || Date.now())) / 1000).toFixed(1)}s active`, 'Performance Monitor > Runs', '#60a5fa');
    } else if (experiments.length < 2) {
      add('Runs', 'P1', 'Record two controlled profiling runs', 'Saved runs make performance changes reproducible and easier to compare than live-only notes.', 'Start a timed run, change one setting, let it auto-stop, then repeat for the next profile.', `${experiments.length}/2 runs · ${Math.round(Number(settings.perfMonitorRunDurationSec) || 90)}s duration`, 'Performance Monitor > Runs > Start timed run', '#60a5fa');
    } else {
      const cmp = fiPerfExperimentComparison(sourceSamples);
      if (cmp) add('Runs', 'P1', 'Use saved run deltas as the final decision', 'The latest two runs can show whether a watcher/media profile actually saved heap or reduced hit cadence.', 'Prefer the profile with lower heap delta, lower hit rate, and lower long-task end value.', `${cmp.heapDeltaDiff >= 0 ? '+' : ''}${cmp.heapDeltaDiff.toFixed(1)} MB heap-delta diff`, 'Performance Monitor > Runs', '#60a5fa');
    }
    add('Browser trick', 'P2', 'Use idle work for non-critical sampling', 'Idle callbacks reduce the chance that monitoring itself adds frame pressure during busy periods.', 'Keep Idle-time background sampling enabled unless you need deterministic interval samples for debugging.', settings.perfMonitorIdleSampling === false ? 'disabled' : 'enabled', 'Appearance > Performance Monitor Floating Window', '#60a5fa', 'requestIdleCallback guidance');
    add('Browser trick', 'P2', 'Pause monitor work when hidden', 'A hidden browser tab cannot show live graph updates, so sampling and redraws are usually wasted unless a timed run is recording.', 'Keep Pause while tab hidden enabled for normal browsing; disable it only for background-tab experiments.', settings.perfMonitorPauseWhenPageHidden === false ? 'hidden-tab sampling on' : 'hidden-tab pause on', 'Appearance > Performance Monitor Floating Window > Pause while tab hidden', '#60a5fa', 'Page Visibility API');
    add('Browser trick', 'P2', 'Use CSS containment only on owned surfaces', 'Containment can isolate layout and paint work, but applying it to unknown site nodes can change layout or sticky behavior.', 'Apply containment-style ideas only to FI floating panels, graph containers, and controlled list wrappers.', 'layout/paint isolation', 'Appearance > Performance Monitor Floating Window', '#67e8f9', 'MDN CSS containment');
    add('Monitor overhead', 'P2', 'Cap the monitor canvas pixel cost', 'High-DPI canvas redraws can become expensive when the floating monitor is large or fullscreen.', 'Lower Canvas DPR cap to 1x or 1.5x during performance profiling, then raise it for screenshots.', `${Number(settings.perfMonitorCanvasDprLimit || 2).toFixed(1)}x DPR cap`, 'Appearance > Performance Monitor Floating Window > Canvas DPR cap', '#38bdf8');
    add('Monitor overhead', 'P2', 'Coalesce rapid monitor redraws', 'Dragging markers and resizing can trigger many render requests; throttling prevents the monitor from becoming the measured bottleneck.', 'Use 80-180 ms render throttle while tuning watchers; use 0 ms only when debugging graph interaction precision.', `${Math.round(Number(settings.perfMonitorRenderThrottleMs) || 0)} ms throttle`, 'Appearance > Performance Monitor Floating Window > Render throttle', '#38bdf8');
    add('Monitor overhead', 'P2', 'Use a monitor preset before profiling', 'A preset changes several graph/UI/render controls together so the monitor does not become the bottleneck.', 'Use Low overhead while measuring, Analysis while investigating causes, and Screenshot only when capturing evidence.', settings.perfMonitorPreset || 'custom', 'Appearance > Performance Monitor Floating Window > Monitor preset', '#38bdf8');
    add('Monitor overhead', 'P2', 'Slow graph-only mode when minimized', 'A minimized graph should still be useful without sampling as aggressively as the full monitor.', 'Raise Minimized sample slowdown on low-end devices, or set it to 1x when you need every sample while minimized.', `${Math.round(Number(settings.perfMonitorMinimizedSampleMultiplier) || 1)}x minimized slowdown`, 'Appearance > Performance Monitor Floating Window > Minimized sample slowdown', '#38bdf8');
    add('Graph', 'P2', 'Lower visual overhead while profiling', 'Graph glow, dense grids, and rich tooltips are useful, but they add work while profiling a slow page.', 'Use Compact Header, disable Chart Glow, switch Tooltip Detail to Compact, and hide series that are not being compared.', `zoom ${Number(settings.perfMonitorGraphZoom || 1).toFixed(1)}x`, 'Appearance > Performance Monitor Floating Window', '#22d3ee');
    add('Storage', 'P0', 'Keep storage on IndexedDB path only', 'Using browser localStorage directly would add synchronous IO and break the IndexedDB-only invariant.', 'Use StorageEngine-backed settings/export/import paths only; do not add direct localStorage writes for monitor state.', 'IndexedDB-only invariant', 'StorageEngine / Data Control', '#4ade80');
    if (settings.perfMonitorPlaybookMode === 'full') {
      add('Full audit', 'P2', 'Use a two-pass observer audit', 'Observers that look cheap alone can overlap and become costly when the page adds thousands of nodes.', 'Disable all optional watchers, enable them back in priority order, and record one breakpoint hit target for DOM and one for lag.', 'observer overlap', 'Settings > Performance > Pro Watchers', '#a5b4fc');
      add('Full audit', 'P2', 'Use a media-free control run', 'A control run without thumbnails separates media decode costs from script injection costs.', 'Set media loading Off, reload, wait for DB hydration, then compare the same category page with media Click mode.', 'media control', 'Settings > Performance > Items Media Loading', '#fbbf24');
      add('Full audit', 'P2', 'Track DB flush windows separately', 'Storage flushes can create short blue spikes that look like watcher lag if they overlap with DOM injection.', 'Mark A before import/export or cache clear, mark B after the blue DB line settles, then compare hit-rate before and after.', 'DB flush window', 'Performance Monitor > Calculate > hitRate', '#60a5fa');
      add('Full audit', 'P2', 'Shorten horizon during unstable phases', 'Long horizons amplify noise when R² is low or XHR timing is bursty.', 'Use 30-60 seconds while tuning watchers, then raise the horizon when the model confidence is stable.', `avg confidence ${models.length ? Math.round(models.reduce((sum, m) => sum + m.confidence, 0) / models.length * 100) : 0}%`, 'Appearance > Performance Monitor Floating Window > Prediction horizon', '#c084fc');
      add('Full audit', 'P2', 'Separate visual style from logic speed', 'Neon glow, web effects, backdrop blur, and graph bands can be useful but should not be active during final speed measurement.', 'Run final comparison once with full visuals and once with Minimal/Solid monitor style to estimate monitor overhead.', settings.perfMonitorWindowStyle || 'style', 'Appearance > Performance Monitor Floating Window', '#22d3ee');
      add('Full audit', 'P3', 'Keep exported evidence with settings', 'Performance improvements are easier to reproduce when the monitor export includes samples, events, markers, breakpoint hits, and settings.', 'Export monitor JSON after each successful watcher profile and keep the profile name in the breakpoint labels.', `${fiPerfVisibleBreakpointHitList().length} visible hit(s) stored`, 'Performance Monitor > Context menu > Export monitor JSON', '#4ade80');
    }
    return items.sort((a, b) => {
      const rank = { P0: 0, P1: 1, P2: 2, P3: 3 };
      return (rank[a.priority] ?? 9) - (rank[b.priority] ?? 9);
    });
  }

