        if (operation && definition?.datatype !== 'boolean' && ['toggle','enable','disable'].includes(operation.value)) operation.value = 'set';
        Array.from(operation?.options || []).forEach(option => { option.disabled = ['toggle','enable','disable'].includes(option.value) && definition?.datatype !== 'boolean'; });
