          let confirmed = false;
          if (action === 'relief') confirmed = window.confirm('Run guided memory relief? FI will trim its monitor histories, contain offscreen cards, lazy-mark media, and lower preload work. It does not force garbage collection.');
          else if (action === 'protect') confirmed = window.confirm('Run Strong protect? This may release far-offscreen media sources and hibernate eligible offscreen DOM. Those resources are restorable, but the page may briefly reload content when you scroll back.');
          if ((action === 'relief' || action === 'protect') && !confirmed) return;
          button.disabled = true;
