          win.dataset.fiContain = settings.perfMonitorUseContentVisibility === false ? '0' : '1';
          fiPerfDrawCanvas(canvas, true, { zoom: settings.perfMonitorGraphZoom, hoverTs });
          if (commit) saveSettingsNow(`performance-monitor:${key}`);
