          let next = section.nextElementSibling;
          let any = false;
          while (next && !next.hasAttribute('data-perf-menu-section')) {
            if (next.hasAttribute('data-perf-menu-row') && next.style.display !== 'none') { any = true; break; }
            next = next.nextElementSibling;
          }
          const sectionText = `${section.getAttribute('data-perf-menu-label') || ''} ${section.textContent || ''}`.toLowerCase();
          const sectionHit = q && sectionText.includes(q) && (!activeCategory || String(section.getAttribute('data-perf-menu-label') || '').toLowerCase() === activeCategory);
          section.style.display = any || sectionHit || (!q && (!activeCategory || String(section.getAttribute('data-perf-menu-label') || '').toLowerCase() === activeCategory)) ? '' : 'none';
