        const rows = Array.from(menu.querySelectorAll('[data-perf-menu-row]')).filter(row => row.style.display !== 'none');
        if (!rows.length) return;
        const idx = rows.indexOf(document.activeElement);
        const next = rows[Math.max(0, Math.min(rows.length - 1, idx + dir))] || rows[dir > 0 ? 0 : rows.length - 1];
        try { next.focus({ preventScroll: true }); } catch { next.focus(); }
