      try { showToast(`DOM hibernation: ${result.hibernated} card(s), ~${Number(result.removedNodes || 0).toLocaleString()} nodes removed from live DOM.`, result.hibernated ? 'success' : 'info', 3200); } catch {}
      render(true, true);
