  function _settingsWouldDropProtectedData(current, next) {
    const protectedRe = /(token|webhook|chatid|customtheme|customprimarycolor|customfontcolor|position|fullscreen|fab|floating|accountswitch|telegram|discord|layout|profile|window|shortcut)/i;
    return Object.keys(defaultSettings).some(k => {
      if (!protectedRe.test(k)) return false;
      if (!Object.prototype.hasOwnProperty.call(current || {}, k)) return false;
      const currentHasValue = !_settingsValueEquals(current[k], defaultSettings[k]);
      if (!currentHasValue) return false;
      const nextMissingOrDefault = !Object.prototype.hasOwnProperty.call(next || {}, k) ||
        _settingsValueEquals(next[k], defaultSettings[k]);
      return nextMissingOrDefault;
    });
  }

  function _settingsSourcePriority(label) {
    const s = String(label || '').toLowerCase();
    if (s.includes('idb/freebypasssettings')) return 120;
    if (s.includes('gm/freebypasssettings')) return 80;
    if (s.includes('memory/current')) return 70;
    if (s.includes('shared-notifications')) return 65;
    if (s.includes('rolling-backup')) return 55;
    if (s.includes('backup')) return 50;
    if (s.includes('shared-mirror')) return 25;
    if (s.includes('legacy')) return 15;
    return 0;
  }

  function _makeSettingsCandidate(label, raw) {
    const data = _parseSettingsObject(raw);
    if (!data) return null;
    return { label, data, priority: _settingsSourcePriority(label), ..._scoreSettingsObject(data) };
  }

  function _makeNotificationSettingsCandidate(label, raw) {
    if (!raw) return null;
    try {
      const obj = typeof raw === 'string' ? JSON.parse(raw) : raw;
      if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return null;
      const data = {};
      ['telegramEnabled','telegramToken','telegramChatId','discordEnabled','discordWebhook'].forEach(k => {
        if (Object.prototype.hasOwnProperty.call(obj, k)) data[k] = obj[k];
      });
      return Object.keys(data).length ? { label, data, priority: _settingsSourcePriority(label), ..._scoreSettingsObject(data) } : null;
    } catch {
      return null;
    }
  }

  function _readGmValueSync(key, fallback = null) {
    try {
      if (typeof GM_getValue === 'function') return FIManagerStore.get(key, fallback);
    } catch {}
    return fallback;
  }

  function _deleteGmSettingsMirror() { /* Retain legacy settings for explicit recovery. */ }

  function _collectSettingsRehydrateCandidates() {
    const candidates = [];
    const push = (candidate) => { if (candidate) candidates.push(candidate); };
    push(_makeSettingsCandidate('memory/current', settings));
    try { push(_makeSettingsCandidate('idb/freeBypassSettings', StorageEngine.getItem('freeBypassSettings'))); } catch {}
    try { push(_makeSettingsCandidate('idb/backup', StorageEngine.getItem(SETTINGS_BACKUP_KEY))); } catch {}
    try { push(_makeSettingsCandidate('idb/rolling-backup', StorageEngine.getItem(SETTINGS_ROLLING_BACKUP_KEY))); } catch {}
    push(_makeNotificationSettingsCandidate('gm/shared-notifications', _readGmValueSync(SHARED_NOTIFICATIONS_STORE_KEY, null)));
    return candidates;
  }

  function _mergeSettingsCandidates(candidates) {
    const merged = { ...defaultSettings, ...settings };
    const ranked = (candidates || []).slice().sort((a, b) =>
      (a.score - b.score) || (a.important - b.important) || (a.nonDefaultKeys - b.nonDefaultKeys) || (a.keys - b.keys) || (a.priority - b.priority)
    );
    ranked.forEach(src => {
      Object.keys(src.data || {}).forEach(k => {
        if (!Object.prototype.hasOwnProperty.call(defaultSettings, k)) return;
        const next = src.data[k];
        const current = merged[k];
        const nextIsDefault = _settingsValueEquals(next, defaultSettings[k]);
        const currentIsDefault = _settingsValueEquals(current, defaultSettings[k]);
        if (!nextIsDefault || currentIsDefault || typeof current === 'undefined') {
          merged[k] = next;
        }
      });
    });
    const idbPrimary = (candidates || []).find(c => c?.label === 'idb/freeBypassSettings' && c.data);
    if (idbPrimary) {
      Object.keys(idbPrimary.data || {}).forEach(k => {
        if (Object.prototype.hasOwnProperty.call(defaultSettings, k)) merged[k] = idbPrimary.data[k];
      });
    }
    applyToolModePreference(merged, 'rehydrate-merge');
    merged.headers = { ...defaultSettings.headers, ...(merged.headers || {}) };
    merged.position = { ...defaultSettings.position, ...(merged.position || {}) };
    merged.telegramIncludeData = { ...defaultSettings.telegramIncludeData, ...(merged.telegramIncludeData || {}) };
    merged.detailedInfoFields = { ...defaultSettings.detailedInfoFields, ...(merged.detailedInfoFields || {}) };
    merged.ciColors = { ...defaultSettings.ciColors, ...(merged.ciColors || {}) };
    merged.ciUiColors = { ...defaultSettings.ciUiColors, ...(merged.ciUiColors || {}) };
    try {
      if (merged.customThemeProfiles && typeof merged.customThemeProfiles === 'object' && !Array.isArray(merged.customThemeProfiles)) {
        Object.keys(merged.customThemeProfiles).forEach(name => {
          merged.customThemeProfiles[name] = normalizeAppearanceProfile(merged.customThemeProfiles[name]);
        });
      }
    } catch {}
    return fiNormalizeUpgradedPerformanceSettings(merged);
  }

  function _applyRehydratedSettings(nextSettings) {
    let changed = false;
    const changedKeys = [];
    const normalizedSettings = fiNormalizeUpgradedPerformanceSettings({ ...settings, ...(nextSettings || {}) });
    fiApplyForegroundLagTuning(normalizedSettings, nextSettings || {});
    Object.keys(defaultSettings).forEach(k => {
      if (!Object.prototype.hasOwnProperty.call(normalizedSettings || {}, k)) return;
      if (!_settingsValueEquals(settings[k], normalizedSettings[k])) {
        changedKeys.push(k);
        settings[k] = normalizedSettings[k];
        changed = true;
      }
    });
    try {
      const protectionPreferences = StorageEngine.getProtectionPreferences();
      settings.storageProtectionAutoRepair = protectionPreferences.autoRepair;
      settings.storageProtectionIgnoreWarnings = protectionPreferences.ignoreWarnings;
    } catch {}
    return { changed, changedKeys };
  }

  function _persistFiBootMarkerPreference(value = settings?.showFiBootMarker) {
    const enabled = value !== false;
    try { localStorage.setItem(FI_BOOT_MARKER_PREF_KEY, enabled ? 'true' : 'false'); } catch {}
    try { if (typeof GM_setValue === 'function') FIManagerStore.set(FI_BOOT_MARKER_PREF_KEY, enabled); } catch {}
    try {
      if (typeof GM !== 'undefined' && typeof GM.setValue === 'function') {
        Promise.resolve(FIManagerStore.set(FI_BOOT_MARKER_PREF_KEY, enabled)).catch(() => {});
      }
    } catch {}
  }

  function releaseFiStartupUiHold(reason = 'settings-applied') {
    try { document.documentElement?.removeAttribute('data-fi-settings-hydrating'); } catch {}
    try {
      window.dispatchEvent(new CustomEvent(FI_SETTINGS_APPLIED_EVENT, {
        detail: { reason, ts: Date.now() }
      }));
    } catch {}
  }

  function _syncDurableSettingsSnapshot(reason = 'rehydrate') {
    let str = '';
    try { str = JSON.stringify(settings); } catch { return; }
    try { StorageEngine.setItem('freeBypassSettings', str); } catch {}
    try { persistToolModePreference(settings.toolMode, 'sync-' + reason); } catch {}
    try { _deleteGmSettingsMirror(); } catch {}
    try { _persistFiBootMarkerPreference(settings.showFiBootMarker); } catch {}
    try { _settingsSaveSnapshot = JSON.parse(str); } catch {}
    try { _lastSavedSettingsStr = str; } catch {}
    try { if (typeof persistSharedNotificationSettings === 'function') persistSharedNotificationSettings(); } catch {}
    try { console.debug('[FI SETTINGS] Durable snapshot synced:', reason, str.length + ' bytes'); } catch {}
  }

  //  IDB readiness gate ────────────────────────────────────────────────────
  // In IndexedDB mode, _mem starts empty so the sync load above reads null.
  // Once _loadAllFromDB() has populated _mem, re-hydrate all caches so the
  // XHR/fetch interceptors see the full data and don't trigger unnecessary
  // batch fetches or DOM-patch cross-contamination.
  StorageEngine.onReady(() => {
    const _hydrateDownloadUrlCacheAfterSettings = () => {
      if (!StorageEngine.isIndexedDB()) return;
      const run = () => {
        downloadUrlCacheLoadedFromStorage = false;   // allow re-load
        loadDownloadUrlCacheFromStorage();
        console.log('[IDB] Re-hydrated download URL cache after IndexedDB ready (' + downloadUrlCache.size + ' entries)');
      };
      const delayMs = isLiteModeRuntime() && settings.liteDeferIndexedDbHydration !== false
        ? Math.max(0, Math.floor(Number(settings.liteHydrationDelayMs) || 0))
        : 0;
      if (!delayMs) {
        run();
        return;
      }
      const schedule = () => fiScheduleIdleWork(run, {
        delayMs,
        timeoutMs: Math.max(2500, delayMs + 2500),
        deferHidden: false
      });
      if (document.readyState === 'complete') schedule();
      else window.addEventListener('load', schedule, { once: true });
    };
    // Re-load settings only after IDB is ready. Never let a boot-time default object
    // overwrite real saved settings; merge the richest durable sources instead.
    try {
      const _IDB1 = 'font-size:11px;font-weight:900;color:#fff;background:#7c3aed;padding:2px 10px;border-radius:100px;';
      const _IDB2 = 'color:#c4b5fd;font-size:10.5px;font-weight:600;';
      const candidates = _collectSettingsRehydrateCandidates();
      const merged = _mergeSettingsCandidates(candidates);
      const { changed, changedKeys } = _applyRehydratedSettings(merged);
      _settingsHydratedFromDurableStorage = true;
      fiLockDeviceBootProfile();
      _syncDurableSettingsSnapshot('idb-ready-merged');
      try {
        const summary = candidates
          .map(c => `${c.label}:score=${c.score},nonDefault=${c.nonDefaultKeys},important=${c.important}`)
          .join(' | ');
        console.groupCollapsed('%c[FI SETTINGS REHYDRATE]%c IDB ready   %d setting(s) updated', _IDB1, _IDB2, changedKeys.length);
        console.log('Sources:', summary || '(none)');
        if (changedKeys.length) console.log('Changed keys:', changedKeys);
        console.groupEnd();
      } catch {}
      if (changed) {
        try { injectStyles(); } catch {}
        try { fiApplyOwnedMotionStyle(); fiApplyForcedAnimationPreference(); } catch {}
        try { if (typeof updateUI === 'function') updateUI(); } catch {}
      }
      try { if (typeof applyFloatingButtonSettings === 'function') applyFloatingButtonSettings('idb-ready'); } catch {}
      try { _hydrateDownloadUrlCacheAfterSettings(); } catch {}
      try {
        if (IS_TENSOR_DOMAIN && !isLiteModeRuntime() && shouldShowUiOnCurrentDomain()) {
          injectCollapseButtonEarly();
        }
      } catch {}
      try { releaseFiStartupUiHold('idb-ready'); } catch {}
    } catch(e) {
      _settingsHydratedFromDurableStorage = true;
      fiLockDeviceBootProfile();
      console.warn('[FreeBypass] IDB settings re-apply error:', e);
      try { _hydrateDownloadUrlCacheAfterSettings(); } catch {}
      try { releaseFiStartupUiHold('idb-ready-error'); } catch {}
    }
  });

  // Ensure we don't lose newly resolved video URLs on fast refresh/navigation.
  window.addEventListener('pagehide', () => {
    try {
      if (_settingsSaveDebounceTimer) saveSettingsNow('pagehide-pending-settings');
    } catch {}
    try {
      if (settings.cachingEnabled) persistDownloadUrlCacheNow();
    } catch {
      // ignore
    }
    try { StorageEngine.flush(); } catch {}
    try { fiPcInfoAbortCollection(); } catch {}
    try { fiPerfTeardownPerformanceRuntime({ reason: 'pagehide', restoreMedia: false }); } catch {}
  });
  window.addEventListener('pageshow', event => {
    if (!event.persisted) return;
    try {
      fiPerfRestoreDroppedMedia(document);
      fiPerfResetDroppedMediaObservers(document, true);
      if (settings.perfMonitorBackgroundSampling !== false || settings.perfAutoDisableWatchersEnabled === true || FI_PERF_MONITOR_STATE.activeExperiment || fiPerfNotificationBackgroundOwnerActive()) fiPerfStartSampler('bfcache-restore');
      else if (document.getElementById('fi-perf-floating-monitor')) {
        fiPerfStartLongTaskObserver();
        fiPerfStartDomBurstObserver();
        fiPerfStartSmartReliefObserver();
      }
    } catch {}
  });
  document.addEventListener('visibilitychange', () => {
    try {
      if (document.visibilityState === 'hidden' && settings.cachingEnabled) persistDownloadUrlCacheNow();
    } catch {
      // ignore
    }
    try {
      if (document.visibilityState === 'hidden' && _settingsSaveDebounceTimer) saveSettingsNow('visibility-hidden-pending-settings');
      if (document.visibilityState === 'hidden') StorageEngine.flush();
    } catch {}
  });

  // Developer systems storage
  const DEV_INJECT_TASKS_KEY = 'freeBypassDevInjectTasks';
  const DEV_LOGS_KEY = 'freeBypassDeveloperLogs';

  function setDevelopersSubTab(tabId) {
    developersSubTab = tabId;
    localStorage.setItem('freeBypassDevelopersSubTab', developersSubTab);
  }

  function loadDeveloperLogs() {
    try {
      const raw = localStorage.getItem(DEV_LOGS_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed;
      if (parsed && Array.isArray(parsed.items)) return parsed.items;
      return [];
    } catch {
      return [];
    }
  }

  function saveDeveloperLogs(items) {
    try {
      localStorage.setItem(DEV_LOGS_KEY, JSON.stringify(items || []));
    } catch (err) {
      // If storage is full, try to truncate aggressively.
      try {
        const trimmed = Array.isArray(items) ? items.slice(-Math.max(50, Math.min(settings.developerMaxLogs || 500, 200))) : [];
        localStorage.setItem(DEV_LOGS_KEY, JSON.stringify(trimmed));
      } catch {
        // no-op
      }
      if (domInjectDebug) console.warn('[DeveloperLogs] Failed to save logs:', err);
    }
  }

  function addDeveloperLog(entry) {
    const max = Math.max(50, Math.min(5000, Number(settings.developerMaxLogs) || 500));
    const logs = loadDeveloperLogs();
    const safe = {
      id: `${Date.now()}-${Math.random().toString(16).slice(2)}`,
      ts: new Date().toISOString(),
      level: entry?.level || 'info',
      tag: entry?.tag || 'developer',
      source: entry?.source || 'unknown',
      message: entry?.message || '',
      details: entry?.details || null,
      url: location.href
    };
    logs.push(safe);
    if (logs.length > max) {
      logs.splice(0, logs.length - max);
    }
    saveDeveloperLogs(logs);
    return safe;
  }

  function devLog(source, message, details = null, level = 'info', tag = 'developer') {
    return addDeveloperLog({ source, message, details, level, tag });
  }

  const TENSOR_INTERCEPT_LOGS_KEY = 'freeBypassTensorInterceptLogsV1';

  function loadTensorInterceptLogs() {
    try {
      const raw = localStorage.getItem(TENSOR_INTERCEPT_LOGS_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  function saveTensorInterceptLogs(logs) {
    try {
      localStorage.setItem(TENSOR_INTERCEPT_LOGS_KEY, JSON.stringify(Array.isArray(logs) ? logs : []));
    } catch {
      // ignore
    }
  }

  function clearTensorInterceptLogs() {
    saveTensorInterceptLogs([]);
  }

  function freeInternetConsoleLog(scope, level, message, details = null) {
    const normalizedLevel = String(level || 'info').toLowerCase();
    const palette = normalizedLevel === 'error'
      ? { badge: '#ef4444', text: '#fee2e2', border: 'rgba(239,68,68,0.45)' }
      : normalizedLevel === 'warn' || normalizedLevel === 'warning'
        ? { badge: '#f59e0b', text: '#fef3c7', border: 'rgba(245,158,11,0.45)' }
        : normalizedLevel === 'success'
          ? { badge: '#22c55e', text: '#dcfce7', border: 'rgba(34,197,94,0.45)' }
          : { badge: '#38bdf8', text: '#e0f2fe', border: 'rgba(56,189,248,0.45)' };
    const method = normalizedLevel === 'error'
      ? 'error'
      : (normalizedLevel === 'warn' || normalizedLevel === 'warning' ? 'warn' : 'log');
    const safeScope = String(scope || 'UI').trim() || 'UI';
    const badgeStyle = `background:${palette.badge};color:#020617;padding:2px 8px;border-radius:999px;font-weight:900;border:1px solid ${palette.border};`;
    const textStyle = `color:${palette.text};font-weight:700;`;
    if (details != null) {
      console[method](`%cFREEInternet ${safeScope}%c ${String(message || '')}`, badgeStyle, textStyle, details);
      return;
    }
    console[method](`%cFREEInternet ${safeScope}%c ${String(message || '')}`, badgeStyle, textStyle);
  }

  function tensorInterceptConsoleLog(level, message, details = null) {
    if (!IS_TENSOR_DOMAIN) return;
    freeInternetConsoleLog('Tensor', level, message, details);
  }

  function addTensorInterceptUiLog(level, message, details = null) {
    tensorInterceptConsoleLog(level, message, details);
    if (!settings.tensorInterceptEnableUiLogs) return;
    const max = Math.max(50, Math.min(5000, Number(settings.tensorInterceptMaxLogs) || 600));
    const logs = loadTensorInterceptLogs();
    logs.push({
      id: `${Date.now()}-${Math.random().toString(16).slice(2)}`,
      ts: new Date().toISOString(),
      level: String(level || 'info').toLowerCase(),
      message: String(message || ''),
      details: details || null
    });
    if (logs.length > max) logs.splice(0, logs.length - max);
    saveTensorInterceptLogs(logs);
    refreshLiveLogPanel('tensorIntercept');
  }

  function tensorInterceptLog(level, message, details = null) {
    addTensorInterceptUiLog(level, message, details);
  }

  // ─── XHR Trace Logger ──────────────────────────────────────────────────────
  // Color-coded, per-item console trace for XHR intercept events.
  // Activated only when settings.xhrInterceptTraceLog === true.
  // Colors:
  //   🟢 #22c55e   bypass URL successfully applied to XHR response
  //   🔴 #f87171   item was blocked (forbidden.jpg) but NO cached bypass URL yet
  //   🟡 #fbbf24   item resolved by async batch fetch (post-flight)
  //   🔵 #38bdf8   XHR intercepted (no forbidden items in this response)
  //   ⚫ #94a3b8   trace detail (sub-item of another entry)

  function _xhrTraceEnabled() { return !!settings?.xhrInterceptTraceLog; }

  const _XHR_TRACE_COLORS = {
    hit:     { badge: '#22c55e', text: '#dcfce7', label: 'BYPASS HIT' },
    miss:    { badge: '#f87171', text: '#fee2e2', label: 'BYPASS MISS' },
    async:   { badge: '#fbbf24', text: '#fef3c7', label: 'ASYNC RESOLVE' },
    ok:      { badge: '#38bdf8', text: '#e0f2fe', label: 'XHR OK' },
    patch:   { badge: '#a78bfa', text: '#ede9fe', label: 'DOM PATCH' },
    fail:    { badge: '#ef4444', text: '#fee2e2', label: 'ERROR' },
    warn:    { badge: '#f59e0b', text: '#fef3c7', label: 'WARN' },
  };

  function _xhrTraceLog(colorKey, event, details = null) {
    if (!_xhrTraceEnabled()) return;
    const c = _XHR_TRACE_COLORS[colorKey] || _XHR_TRACE_COLORS.ok;
    const badge  = `background:${c.badge};color:#020617;padding:2px 7px;border-radius:999px;font-weight:900;font-size:11px;`;
    const eStyle = `color:${c.text};font-weight:700;font-size:12px;`;
    const dStyle = `color:#94a3b8;font-size:11px;font-weight:500;`;
    if (details) {
      console.groupCollapsed(`%c${c.label}%c ${event}`, badge, eStyle);
      if (typeof details === 'object' && details !== null) {
        Object.entries(details).forEach(([k, v]) => {
          console.log(`%c  ${k}: %c${typeof v === 'string' ? v : JSON.stringify(v)}`, dStyle + 'font-weight:700;', dStyle);
        });
      } else {
        console.log(`%c  ${String(details)}`, dStyle);
      }
      console.groupEnd();
    } else {
      console.log(`%c${c.label}%c ${event}`, badge, eStyle);
    }
  }

  // Called from flushDownloadUrlBatch after each batch API response.
  function _xhrTraceBatchResult(entries, urlMap, batchIds) {
    if (!_xhrTraceEnabled()) return;
    const resolved = urlMap.size;
    const missed = batchIds.length - resolved;
    const headerColor = missed === 0 ? 'hit' : (resolved === 0 ? 'miss' : 'warn');
    if (settings.logBypassHit !== false) {
      _xhrTraceLog(headerColor, `[Batch] ${resolved}/${batchIds.length} resolved`, {
        total: batchIds.length, resolved, missed
      });
    }
    for (const [imageId, entry] of entries) {
      const url = urlMap.get(String(imageId));
      if (url) {
        if (settings.logAsyncResolve !== false) {
          _xhrTraceLog('async', `  ✅ ${imageId}`, {
            kind: entry.forceKind || entry.mimeTypeHint || 'unknown',
            url: url.slice(0, 90) + (url.length > 90 ? '…' : '')
          });
        }
      } else {
        _xhrTraceLog('miss', `  ❌ ${imageId}`, {
          kind: entry.forceKind || entry.mimeTypeHint || 'unknown',
          reason: 'not returned by batch API'
        });
      }
    }
  }

  // Called from patchTensorTasksQueryResponseBody stats to trace sync-path per-item result.
  function _xhrTraceTasksQueryStats(stats, source = 'xhr') {
    if (!_xhrTraceEnabled()) return;
    if (!stats) return;
    const { tasksSeen = 0, finishedTasks = 0, invalidItemsSeen = 0, patchedItems = 0, cacheMisses = 0, cacheHitIds = [], cacheMissIds = [] } = stats;
    const label = `[TasksQuery:${source}] tasks=${tasksSeen} finished=${finishedTasks} invalid=${invalidItemsSeen} patched=${patchedItems} hits=${cacheHitIds.length} misses=${cacheMisses}`;
    if (cacheMisses > 0) {
      _xhrTraceLog('miss', label, {
        missIds: cacheMissIds.slice(0, 10).join(', ') + (cacheMissIds.length > 10 ? '…' : ''),
        hitIds: cacheHitIds.slice(0, 5).join(', ') + (cacheHitIds.length > 5 ? '…' : ''),
      });
    } else if (patchedItems > 0) {
      _xhrTraceLog('hit', label, { hitIds: cacheHitIds.slice(0, 10).join(', ') });
    } else {
      _xhrTraceLog('ok', label);
    }
  }

  function exportTensorInterceptLogsToJson() {
    const logs = loadTensorInterceptLogs();
    const payload = {
      kind: 'bypass-tensor-intercept-logs-export',
      version: 1,
      exportedAt: new Date().toISOString(),
      count: logs.length,
      source: {
        domain: window.location.hostname,
        href: window.location.href
      },
      items: logs
    };
    downloadJsonFile(`bypass_tensor_intercept_logs_${buildExportTimestamp()}.json`, payload);
    showToast(`Exported ${logs.length} Tensor intercept log entr${logs.length === 1 ? 'y' : 'ies'}`, 'success');
  }

  async function copyTensorInterceptLogsToClipboard() {
    const logs = loadTensorInterceptLogs();
    const text = JSON.stringify({
      kind: 'bypass-tensor-intercept-logs-copy',
      exportedAt: new Date().toISOString(),
      count: logs.length,
      items: logs
    }, null, 2);

    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      showToast('Tensor intercept logs copied to clipboard', 'success');
      return;
    }

    downloadTextFile(`bypass_tensor_intercept_logs_${buildExportTimestamp()}.txt`, text, 'text/plain');
    showToast('Clipboard unavailable, downloaded Tensor intercept logs as text', 'warning');
  }

  class DigenIndexedStore {
    static dbName = 'digenS';
    static dbVersion = 1;
    static dbp = null;
    static storesToCreate = new Set();

    constructor({ storeName }) {
      if (!storeName) throw new Error('storeName is required');
      this.storeName = storeName;
      DigenIndexedStore.storesToCreate.add(storeName);
    }

    async init() {
      if (DigenIndexedStore.dbp) return DigenIndexedStore.dbp;
      DigenIndexedStore.dbp = new Promise((resolve, reject) => {
        const request = indexedDB.open(DigenIndexedStore.dbName, DigenIndexedStore.dbVersion);
        request.onupgradeneeded = (e) => {
          const db = e.target.result;
          for (const storeName of DigenIndexedStore.storesToCreate) {
            if (!db.objectStoreNames.contains(storeName)) {
              db.createObjectStore(storeName, { keyPath: 'id' });
            }
          }
        };
        request.onsuccess = (e) => resolve(e.target.result);
        request.onerror = (e) => reject(e.target.error);
      });
      return DigenIndexedStore.dbp;
    }

    async get(id) {
      const db = await this.init();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(this.storeName, 'readonly');
        const req = tx.objectStore(this.storeName).get(id);
        req.onsuccess = (e) => resolve(e.target.result);
        req.onerror = (e) => reject(e.target.error);
      });
    }

    async getAll(filterFn, sortField = 'created_at', desc = true) {
      const db = await this.init();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(this.storeName, 'readonly');
        const req = tx.objectStore(this.storeName).getAll();
        req.onsuccess = (e) => {
          let result = e.target.result || [];
          if (typeof filterFn === 'function') result = result.filter(filterFn);
          result.sort((a, b) => {
            const aValue = a?.[sortField] ?? a?.createdAtTimestamp ?? a?.createdAt;
            const bValue = b?.[sortField] ?? b?.createdAtTimestamp ?? b?.createdAt;
            if (!aValue || !bValue) return 0;
            const aDate = new Date(aValue);
            const bDate = new Date(bValue);
            return desc ? bDate - aDate : aDate - bDate;
          });
          resolve(result);
        };
        req.onerror = (e) => reject(e.target.error);
      });
    }

    async put(record) {
      if (!record || !record.id) throw new Error('Record must have an id');
      const db = await this.init();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(this.storeName, 'readwrite');
        const req = tx.objectStore(this.storeName).put(record);
        req.onsuccess = () => resolve(record);
        req.onerror = (e) => reject(e.target.error);
      });
    }

    async clear() {
      const db = await this.init();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(this.storeName, 'readwrite');
        const req = tx.objectStore(this.storeName).clear();
        req.onsuccess = () => resolve(true);
        req.onerror = (e) => reject(e.target.error);
      });
    }
  }

