  function normalizeHiggsfieldImportItems(raw, kind = 'items') {
    const items = Array.isArray(raw) ? raw : (Array.isArray(raw?.items) ? raw.items : null);
    if (!Array.isArray(items)) {
      throw new Error(`Invalid Higgsfield ${kind} JSON. Expected an array or an export object with an items array.`);
    }
    const filtered = items.filter((item) => item && item.id != null);
    if (!filtered.length) {
      throw new Error(`No valid Higgsfield ${kind} entries found in the selected file.`);
    }
    return filtered;
  }

  function importHiggsfieldItemsFromFile(kind = 'jobs') {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json,application/json';
    input.style.display = 'none';
    document.body.appendChild(input);

    input.addEventListener('change', () => {
      const file = input.files?.[0];
      if (!file) {
        input.remove();
        return;
      }
      const reader = new FileReader();
      reader.onload = async () => {
        try {
          const parsed = JSON.parse(String(reader.result || 'null'));
          const items = normalizeHiggsfieldImportItems(parsed, kind);
          const noun = kind === 'jobs' ? 'job' : 'soul';
          if (!window.confirm(`Import ${items.length} Higgsfield ${noun}${items.length === 1 ? '' : 's'} from ${file.name}? Existing entries with matching ids will be updated.`)) {
            return;
          }
          if (kind === 'jobs') {
            await Promise.all(items.map((item) => upsertHiggsfieldJob(item, 'import:file')));
          } else {
            await Promise.all(items.map((item) => upsertHiggsfieldSoul(item, 'import:file')));
          }
          showToast(`Imported ${items.length} Higgsfield ${noun}${items.length === 1 ? '' : 's'}`, 'success');
          updateUI();
        } catch (err) {
          showToast(String(err?.message || err || 'Failed to import Higgsfield JSON'), 'error');
        } finally {
          input.value = '';
          input.remove();
        }
      };
      reader.onerror = () => {
        showToast('Failed to read selected JSON file', 'error');
        input.remove();
      };
      reader.readAsText(file);
    }, { once: true });

    input.click();
  }

  function showHiggsfieldPreviewDialog({ title = 'Higgsfield Preview', mediaUrl = '', thumbnailUrl = '', mediaType = 'image', subtitle = '', copyText = '', copyLabel = 'Copy', metaLines = [] } = {}) {
    const colors = getFiDialogTheme();
    const overlay = document.createElement('div');
    overlay.className = 'fi-theme-overlay';
    overlay.style.cssText = `position:fixed; inset:0; z-index:10000003; background:${colors.overlay}; backdrop-filter:blur(8px); display:flex; align-items:center; justify-content:center; padding:18px;`;
    const dialog = document.createElement('div');
    dialog.className = 'fi-theme-dialog';
    dialog.style.cssText = `width:min(860px, 96vw); max-height:92vh; display:flex; flex-direction:column; background:${colors.bg}; border:1px solid ${colors.border}; border-radius:16px; padding:16px; color:${colors.text}; box-shadow:0 25px 80px rgba(0,0,0,0.7);`;
    const previewMarkup = mediaUrl
      ? (mediaType === 'video'
        ? `<video controls autoplay muted playsinline poster="${escapeHtml(thumbnailUrl || '')}" style="width:100%; max-height:60vh; border-radius:12px; background:#000; object-fit:contain;" src="${escapeHtml(mediaUrl)}"></video>`
        : `<img src="${escapeHtml(mediaUrl)}" style="width:100%; max-height:60vh; border-radius:12px; background:#000; object-fit:contain;" />`)
      : '<div style="height:260px; display:flex; align-items:center; justify-content:center; border-radius:12px; background:#020617; color:#64748b;"><i class="fas fa-image"></i></div>';
    dialog.innerHTML = `
      <div style="display:flex; align-items:flex-start; justify-content:space-between; gap:12px; margin-bottom:12px;">
        <div>
          <div style="font-weight:800; font-size:15px;">${escapeHtml(title)}</div>
          ${subtitle ? `<div style="font-size:12px; color:${colors.textSecondary}; margin-top:4px;">${escapeHtml(subtitle)}</div>` : ''}
        </div>
        <button class="bypass-btn bypass-btn-secondary" style="width:auto; padding:6px 10px;" data-close><i class="fas fa-times"></i></button>
      </div>
      <div style="display:flex; flex-direction:column; gap:12px; overflow:auto;">
        ${previewMarkup}
        ${metaLines.length ? `<div style="display:grid; gap:6px; font-size:12px; color:${colors.textSecondary};">${metaLines.map((line) => `<div>${line}</div>`).join('')}</div>` : ''}
      </div>
      <div style="display:flex; gap:10px; justify-content:flex-end; flex-wrap:wrap; margin-top:14px;">
        ${mediaUrl ? '<button class="bypass-btn bypass-btn-secondary" style="width:auto; padding:8px 12px;" data-open><i class="fas fa-up-right-from-square"></i> Open</button>' : ''}
        ${copyText ? `<button class="bypass-btn bypass-btn-primary" style="width:auto; padding:8px 12px;" data-copy>${escapeHtml(copyLabel)}</button>` : ''}
        <button class="bypass-btn bypass-btn-secondary" style="width:auto; padding:8px 12px;" data-done>Close</button>
      </div>
    `;

    const close = () => overlay.remove();
    dialog.querySelector('[data-close]').onclick = close;
    dialog.querySelector('[data-done]').onclick = close;
    const openBtn = dialog.querySelector('[data-open]');
    if (openBtn) openBtn.onclick = () => { if (mediaUrl) window.open(mediaUrl, '_blank'); };
    const copyBtn = dialog.querySelector('[data-copy]');
    if (copyBtn) {
      copyBtn.onclick = async () => {
        if (!copyText) return;
        if (navigator.clipboard?.writeText) {
          await navigator.clipboard.writeText(copyText);
          showToast(`${copyLabel} copied`, 'success');
        }
      };
    }
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
    overlay.appendChild(dialog);
    document.body.appendChild(overlay);
  }

  // Deletion rules storage key
  const DELETION_RULES_KEY = 'freeBypassDeletionRulesV1';
  const DELETION_RULES_TRUST_VERSION = 2;
  const DELETION_AUDIT_LOG_KEY = 'freeBypassDeletionAuditLogV1';
  const AUTO_DELETE_PROTECTED_KEYS = new Set([
    'freeBypassUserAccounts',
    'freeBypassAccountMeta',
    'freeBypassUserProfileCache',
    'freeBypassUserAccountTasks',
    'freeBypassCommunityToken',
    'freeBypassCommunityAccountId',
    'freeBypassCommunityUsername',
    'freeBypassCommunityAvatar',
    'freeBypassCommunityBio',
    'freeBypassFiUsername',
    'freeBypassMyTypes',
    'freeBypassPrivacySettings',
    'freeBypassCommunityRole',
    'freeBypassSettings',
    'freeBypassSettingsProfiles',
    'freeBypassCurrentProfile',
    'freeBypassPromptsSaved',
    'freeBypassPromptsRecent',
    'freeBypassGenPreviews',
    'freeBypassRepeatedGenerationsV1',
    'freeBypassToolParamProfilesV1',
    'freeBypassTaskProfiles',
    'freeBypassTaskActions',
    'freeBypassTaskActionProfilesV1',
    'freeBypassTemplatePresetsV1',
    'freeBypassUploadedMedia',
    'freeBypassLibraryLinks',
    'freeBypassScriptExtensionsV1'
  ]);

  // ============================================================================
  // ANALYTICS ENGINE  Secure telemetry & error tracking (IndexedDB only)
  // ============================================================================
  const ANALYTICS_STORAGE_KEY = 'freeBypassAnalyticsV1';
  const ANALYTICS_VERSION = 1;
  const ANALYTICS_MAX_EVENTS = 1200;
  const ANALYTICS_MAX_ERRORS = 400;

  // In-memory analytics state (flushed to storage periodically)
  let _analyticsState = null;
  let _analyticsFlushTimer = null;
  let _analyticsSessionId = `s_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  let _analyticsBrowserInfo = (() => {
    try {
      const ua = navigator.userAgent || '';
      const match = ua.match(/(Chrome|Firefox|Safari|Edge|OPR|Opera)\/(\d+)/i);
      return {
        browser: match ? match[1].replace('OPR', 'Opera') : 'Unknown',
        version: match ? match[2] : '0',
        platform: navigator.platform || 'Unknown',
        language: navigator.language || 'en',
        userAgent: ua.slice(0, 200)
      };
    } catch { return { browser: 'Unknown', version: '0', platform: 'Unknown', language: 'en', userAgent: '' }; }
  })();

  function _analyticsDefaultState() {
    return {
      version: ANALYTICS_VERSION,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      // Per-account metrics keyed by userId
      accounts: {},
      // Global counters
      global: {
        totalLogins: 0,
        totalTasksStored: 0,
        totalUrlRefreshes: 0,
        totalCacheDeletes: 0,
        totalBypassSuccess: 0,
        totalBypassFails: 0,
        totalDownloads: 0,
        totalTelegramSends: 0,
        totalDiscordSends: 0,
        totalApiCalls: 0,
        totalDomInjectSuccess: 0,
        totalDomInjectFails: 0,
        totalXhrInterceptSuccess: 0,
        totalXhrInterceptFails: 0,
        totalDeletedRegainable: 0,
        totalDeletedNonRegainable: 0,
        totalHidden: 0
      },
      // Error log (newest first, capped at ANALYTICS_MAX_ERRORS)
      errors: [],
      // Event timeline (newest first, capped at ANALYTICS_MAX_EVENTS)
      events: []
    };
  }

  function _analyticsAccountBucket(userId) {
    if (!_analyticsState) _analyticsLoadState();
    if (!userId) return null;
    const key = String(userId);
    if (!_analyticsState.accounts[key]) {
      _analyticsState.accounts[key] = {
        userId: key,
        nickname: '',
        firstSeen: Date.now(),
        lastSeen: Date.now(),
        tasksStored: 0,
        urlRefreshes: 0,
        cacheDeletes: 0,
        bypassSuccess: 0,
        bypassFails: 0,
        downloads: 0,
        telegramSends: 0,
        discordSends: 0,
        apiCalls: 0,
        domInjectSuccess: 0,
        domInjectFails: 0,
        xhrInterceptSuccess: 0,
        xhrInterceptFails: 0,
        errors: 0,
        lastToken: ''
      };
    }
    return _analyticsState.accounts[key];
  }

  function _analyticsLoadState() {
    if (_analyticsState) return;
    try {
      const raw = localStorage.getItem(ANALYTICS_STORAGE_KEY);
      if (raw) {
        _analyticsState = JSON.parse(raw);
        if (_analyticsState.version !== ANALYTICS_VERSION) _analyticsState = _analyticsDefaultState();
      } else {
        _analyticsState = _analyticsDefaultState();
      }
    } catch {
      _analyticsState = _analyticsDefaultState();
    }
  }

  function _analyticsFlush() {
    if (!_analyticsState) return;
    _analyticsState.updatedAt = Date.now();
    // Cap arrays
    if (_analyticsState.errors.length > ANALYTICS_MAX_ERRORS) _analyticsState.errors = _analyticsState.errors.slice(0, ANALYTICS_MAX_ERRORS);
    if (_analyticsState.events.length > ANALYTICS_MAX_EVENTS) _analyticsState.events = _analyticsState.events.slice(0, ANALYTICS_MAX_EVENTS);

    // Auto-delete check: if analytics data exceeds configured max MB, clear old data
    if (settings?.analyticsAutoDeleteEnabled) {
      const maxBytes = (settings.analyticsAutoDeleteMaxMB || 2) * 1024 * 1024;
      const serialized = JSON.stringify(_analyticsState);
      if (serialized.length > maxBytes) {
        // Trim events and errors to half, then recheck
        _analyticsState.events = _analyticsState.events.slice(0, Math.floor(_analyticsState.events.length / 4));
        _analyticsState.errors = _analyticsState.errors.slice(0, Math.floor(_analyticsState.errors.length / 4));
        const trimmed = JSON.stringify(_analyticsState);
        if (trimmed.length > maxBytes) {
          // Still over limit  reset to fresh state but keep global counters
          const savedGlobal = { ..._analyticsState.global };
          const savedAccounts = { ..._analyticsState.accounts };
          _analyticsState = _analyticsDefaultState();
          _analyticsState.global = savedGlobal;
          _analyticsState.accounts = savedAccounts;
          _analyticsState.events = [];
          _analyticsState.errors = [];
        }
        console.log('[FI Analytics] Auto-trimmed analytics data (exceeded ' + (settings.analyticsAutoDeleteMaxMB || 2) + 'MB limit)');
      }
    }

    try {
      localStorage.setItem(ANALYTICS_STORAGE_KEY, JSON.stringify(_analyticsState));
    } catch {
      // Storage full  try trimming
      _analyticsState.errors = _analyticsState.errors.slice(0, 200);
      _analyticsState.events = _analyticsState.events.slice(0, 500);
      try { localStorage.setItem(ANALYTICS_STORAGE_KEY, JSON.stringify(_analyticsState)); } catch {}
    }
  }

  function _analyticsScheduleFlush() {
    if (_analyticsFlushTimer) return;
    const scheduleFlush = () => {
      if (document.visibilityState === 'visible' && fiDomWatcherBusyRemaining() > 0) {
        _analyticsFlushTimer = setTimeout(scheduleFlush, Math.max(500, fiDomWatcherBusyRemaining() + 80));
        return;
      }
      if (typeof requestIdleCallback === 'function') {
        const idleId = requestIdleCallback(() => {
          if (document.visibilityState === 'visible' && fiDomWatcherBusyRemaining() > 0) {
            _analyticsFlushTimer = setTimeout(scheduleFlush, Math.max(500, fiDomWatcherBusyRemaining() + 80));
          } else {
            _analyticsFlushTimer = null;
            _analyticsFlush();
          }
        }, { timeout: 10000 });
        _analyticsFlushTimer = { idle: true, id: idleId };
        return;
      }
      _analyticsFlushTimer = null;
      _analyticsFlush();
    };
    // localStorage serialization is synchronous. Batch it and prefer an idle
    // slice so a busy feed cannot turn analytics persistence into a 3 s pulse.
    _analyticsFlushTimer = setTimeout(scheduleFlush, 12000);
  }

  /**
   * Record an analytics event.
   * @param {string} category - e.g. 'download', 'bypass', 'login', 'cache', 'api', 'ui', 'error'
   * @param {string} action - e.g. 'success', 'fail', 'click', 'refresh'
   * @param {object} data - extra data
   * @param {string} [userId] - associated account userId
   */
  function analyticsTrack(category, action, data = {}, userId = null) {
    try {
      if (!settings?.analyticsEnabled) return;
      _analyticsLoadState();

      const event = {
        id: `ev_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
        ts: Date.now(),
        session: _analyticsSessionId,
        category,
        action,
        userId: userId || data.userId || null,
        browser: _analyticsBrowserInfo.browser,
        data: typeof data === 'object' ? { ...data } : { value: data }
      };

      // Remove sensitive fields
      if (event.data.token) event.data.token = String(event.data.token).slice(0, 20) + '...';
      if (event.data.password) delete event.data.password;

      _analyticsState.events.unshift(event);
      if (_analyticsState.events.length > ANALYTICS_MAX_EVENTS) {
        _analyticsState.events.length = ANALYTICS_MAX_EVENTS;
      }

      // Update global counters
      const g = _analyticsState.global;
      if (category === 'download' && action === 'success') g.totalDownloads++;
      if (category === 'bypass' && action === 'success') g.totalBypassSuccess++;
      if (category === 'bypass' && action === 'fail') g.totalBypassFails++;
      if (category === 'login') g.totalLogins++;
      if (category === 'cache' && action === 'store') g.totalTasksStored++;
      if (category === 'cache' && action === 'refresh') g.totalUrlRefreshes++;
      if (category === 'cache' && action === 'delete') g.totalCacheDeletes++;
      if (category === 'telegram' && action === 'success') g.totalTelegramSends++;
      if (category === 'discord' && action === 'success') g.totalDiscordSends++;
      if (category === 'api') g.totalApiCalls++;
      if (category === 'dom-inject' && action === 'success') g.totalDomInjectSuccess++;
      if (category === 'dom-inject' && action === 'fail') g.totalDomInjectFails++;
      if (category === 'xhr-intercept' && action === 'success') g.totalXhrInterceptSuccess++;
      if (category === 'xhr-intercept' && action === 'fail') g.totalXhrInterceptFails++;
      if (category === 'deletion' && action === 'regainable') g.totalDeletedRegainable++;
      if (category === 'deletion' && action === 'non-regainable') g.totalDeletedNonRegainable++;
      if (category === 'deletion' && action === 'hidden') g.totalHidden++;

      // Update per-account bucket
      if (event.userId) {
        const bucket = _analyticsAccountBucket(event.userId);
        if (bucket) {
          bucket.lastSeen = Date.now();
          if (category === 'download' && action === 'success') bucket.downloads++;
          if (category === 'bypass' && action === 'success') bucket.bypassSuccess++;
          if (category === 'bypass' && action === 'fail') bucket.bypassFails++;
          if (category === 'cache' && action === 'store') bucket.tasksStored++;
          if (category === 'cache' && action === 'refresh') bucket.urlRefreshes++;
          if (category === 'cache' && action === 'delete') bucket.cacheDeletes++;
          if (category === 'telegram' && action === 'success') bucket.telegramSends++;
          if (category === 'discord' && action === 'success') bucket.discordSends++;
          if (category === 'api') bucket.apiCalls++;
          if (category === 'dom-inject' && action === 'success') bucket.domInjectSuccess++;
          if (category === 'dom-inject' && action === 'fail') bucket.domInjectFails++;
          if (category === 'xhr-intercept' && action === 'success') bucket.xhrInterceptSuccess++;
          if (category === 'xhr-intercept' && action === 'fail') bucket.xhrInterceptFails++;
          if (category === 'error') bucket.errors++;
        }
      }

      _analyticsScheduleFlush();
    } catch {
      // Never crash from analytics
    }
  }

  /**
   * Record an error event tied to a specific function.
   * @param {string} funcId - unique function identifier (e.g. 'saveUserProfile', 'flushDownloadUrlBatch')
   * @param {Error|string} error - the error
   * @param {object} context - extra context
   * @param {string} [userId] - associated userId
   */
  function analyticsTrackError(funcId, error, context = {}, userId = null) {
    try {
      if (!settings?.analyticsEnabled) return;
      _analyticsLoadState();

      const errEntry = {
        id: `err_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
        ts: Date.now(),
        session: _analyticsSessionId,
        funcId,
        message: error instanceof Error ? error.message : String(error),
        stack: error instanceof Error ? (error.stack || '').slice(0, 500) : '',
        userId: userId || context.userId || null,
        browser: _analyticsBrowserInfo.browser,
        platform: _analyticsBrowserInfo.platform,
        context: typeof context === 'object' ? { ...context } : { value: context }
      };

      // Sanitize
      if (errEntry.context.token) errEntry.context.token = String(errEntry.context.token).slice(0, 20) + '...';

      _analyticsState.errors.unshift(errEntry);
      if (_analyticsState.errors.length > ANALYTICS_MAX_ERRORS) {
        _analyticsState.errors.length = ANALYTICS_MAX_ERRORS;
      }
      _analyticsState.global.totalBypassFails++;

      if (errEntry.userId) {
        const bucket = _analyticsAccountBucket(errEntry.userId);
        if (bucket) {
          bucket.errors++;
          bucket.lastSeen = Date.now();
        }
      }

      _analyticsScheduleFlush();
    } catch {
      // Never crash
    }
  }

  /** Get analytics state (read-only copy) */
  function analyticsGetState() {
    _analyticsLoadState();
    return JSON.parse(JSON.stringify(_analyticsState));
  }

  /** Clear all analytics data */
  function analyticsClear() {
    _analyticsState = _analyticsDefaultState();
    _analyticsFlush();
  }

  /** Export analytics as JSON string */
  function analyticsExportJson() {
    const state = analyticsGetState();
    state._exportedAt = new Date().toISOString();
    state._browser = _analyticsBrowserInfo;
    return JSON.stringify(state, null, 2);
  }

  /** Export analytics as CSV string */
  function analyticsExportCsv() {
    const state = analyticsGetState();
    const rows = [['timestamp', 'session', 'category', 'action', 'userId', 'browser', 'data'].join(',')];
    state.events.forEach(ev => {
      rows.push([
        new Date(ev.ts).toISOString(),
        ev.session || '',
        ev.category || '',
        ev.action || '',
        ev.userId || '',
        ev.browser || '',
        JSON.stringify(ev.data || {}).replace(/,/g, ';')
      ].join(','));
    });
    return rows.join('\n');
  }

  /** Export analytics as styled HTML report */
  function analyticsExportHtml() {
    const state = analyticsGetState();
    const g = state.global;
    const accounts = Object.values(state.accounts);
    const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>FreeInternet Analytics Report</title>
<style>body{font-family:system-ui,-apple-system,sans-serif;background:#0f172a;color:#e2e8f0;padding:30px;max-width:1200px;margin:0 auto}
h1{color:#38bdf8;border-bottom:2px solid #38bdf8;padding-bottom:10px}h2{color:#a5b4fc;margin-top:30px}
table{width:100%;border-collapse:collapse;margin:15px 0}th,td{padding:8px 12px;text-align:left;border:1px solid #334155}
th{background:#1e293b;color:#38bdf8;font-weight:700}tr:nth-child(even){background:rgba(30,41,59,0.5)}
.card{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:20px;margin:10px 0}
.stat{display:inline-block;background:#0f172a;border:1px solid #475569;border-radius:8px;padding:12px 18px;margin:5px;text-align:center}
.stat-value{font-size:24px;font-weight:800;color:#38bdf8}.stat-label{font-size:11px;color:#94a3b8;text-transform:uppercase}
.error-row{background:rgba(239,68,68,0.08)!important}</style></head><body>
<h1>FreeInternet Analytics Report</h1>
<p>Generated: ${new Date().toLocaleString()} | Session: ${_analyticsSessionId}</p>
<div class="card"><h2>Global Statistics</h2>
<div class="stat"><div class="stat-value">${g.totalLogins}</div><div class="stat-label">Logins</div></div>
<div class="stat"><div class="stat-value">${g.totalTasksStored}</div><div class="stat-label">Tasks Stored</div></div>
<div class="stat"><div class="stat-value">${g.totalUrlRefreshes}</div><div class="stat-label">URL Refreshes</div></div>
<div class="stat"><div class="stat-value">${g.totalDownloads}</div><div class="stat-label">Downloads</div></div>
<div class="stat"><div class="stat-value">${g.totalBypassSuccess}</div><div class="stat-label">Bypass OK</div></div>
<div class="stat"><div class="stat-value">${g.totalBypassFails}</div><div class="stat-label">Bypass Fail</div></div>
<div class="stat"><div class="stat-value">${g.totalTelegramSends}</div><div class="stat-label">Telegram</div></div>
<div class="stat"><div class="stat-value">${g.totalDiscordSends}</div><div class="stat-label">Discord</div></div>
<div class="stat"><div class="stat-value">${g.totalApiCalls}</div><div class="stat-label">API Calls</div></div>
<div class="stat"><div class="stat-value">${g.totalDeletedRegainable || 0}</div><div class="stat-label">Del Regain</div></div>
<div class="stat"><div class="stat-value">${g.totalDeletedNonRegainable || 0}</div><div class="stat-label">Del NoRegain</div></div>
<div class="stat"><div class="stat-value">${g.totalHidden || 0}</div><div class="stat-label">Hidden</div></div></div>
${accounts.length ? `<div class="card"><h2>Per-Account Breakdown (${accounts.length} accounts)</h2>
<table><tr><th>User ID</th><th>Nickname</th><th>First Seen</th><th>Last Seen</th><th>Tasks</th><th>Downloads</th><th>Bypass OK</th><th>Errors</th></tr>
${accounts.map(a => `<tr><td>${a.userId}</td><td>${a.nickname || '-'}</td><td>${new Date(a.firstSeen).toLocaleDateString()}</td><td>${new Date(a.lastSeen).toLocaleDateString()}</td><td>${a.tasksStored}</td><td>${a.downloads}</td><td>${a.bypassSuccess}</td><td>${a.errors}</td></tr>`).join('')}</table></div>` : ''}
${state.errors.length ? `<div class="card"><h2>Recent Errors (${state.errors.length})</h2>
<table><tr><th>Time</th><th>Function</th><th>Message</th><th>User</th><th>Browser</th></tr>
${state.errors.slice(0, 100).map(e => `<tr class="error-row"><td>${new Date(e.ts).toLocaleString()}</td><td>${e.funcId}</td><td>${(e.message || '').slice(0, 100)}</td><td>${e.userId || '-'}</td><td>${e.browser || '-'}</td></tr>`).join('')}</table></div>` : ''}
</body></html>`;
    return html;
  }

  // User account & cache system
  const USER_ACCOUNTS_KEY = 'freeBypassUserAccounts';
  const USER_PROFILE_CACHE_KEY = 'freeBypassUserProfiles';
  const USER_ACCOUNT_TASKS_KEY = 'freeBypassAccountTasks';
  const USER_PROFILE_CAPTURE_KEY = 'freeBypassSeenTensorProfiles';
  const USER_ACCOUNT_DETECT_STATE_KEY = 'freeBypassTensorAccountDetectState';
  const ACCOUNT_META_KEY = 'freeBypassAccountMeta';

  // Account metadata: { [userId]: { alias, color, notes, pinned, order } }
  let _accountMetaCache = (() => {
    try { return JSON.parse(localStorage.getItem(ACCOUNT_META_KEY) || '{}'); } catch { return {}; }
  })();

  function getAccountMeta(userId) {
    if (!userId) return null;
    return _accountMetaCache[userId] || null;
  }

  function setAccountMeta(userId, data) {
    if (!userId) return;
    const existing = _accountMetaCache[userId] || {};
    _accountMetaCache[userId] = { ...existing, ...data };
    safeLocalStorageSet(ACCOUNT_META_KEY, JSON.stringify(_accountMetaCache));
  }

  function getAllAccountMeta() {
    return _accountMetaCache;
  }

  function deleteAccountMeta(userId) {
    if (!userId) return;
    delete _accountMetaCache[userId];
    safeLocalStorageSet(ACCOUNT_META_KEY, JSON.stringify(_accountMetaCache));
  }

  let currentUserProfile = null;
  let currentUserVipInfo = null;
  let currentPreviewUserToken = null;
  let selectedAccountsForCompile = new Set();
  let cachedUserAccounts = JSON.parse(localStorage.getItem(USER_ACCOUNTS_KEY) || '{}');
  let cachedUserProfiles = JSON.parse(localStorage.getItem(USER_PROFILE_CACHE_KEY) || '{}');
  let accountTasksCache = JSON.parse(localStorage.getItem(USER_ACCOUNT_TASKS_KEY) || '{}');
  // Per-userId credits balance cache: { [userId]: { promotionAmount, dailyAmount, restrictedAmount, fetchedAt, token } }
  const CREDITS_BALANCE_KEY = 'freeBypassAccountCreditsBalance';
  let accountCreditsCache = (() => { try { return JSON.parse(localStorage.getItem(CREDITS_BALANCE_KEY) || '{}'); } catch { return {}; } })();

  //  One-time precision correction on startup ──
  // TensorArt userIds are 18-digit integers > Number.MAX_SAFE_INTEGER.
  // Old code used JSON.parse(jwtPayload) which truncated them. Fix stored userIds now.
  {
    let _fixedAny = false;
    for (const [tok, info] of Object.entries(cachedUserAccounts)) {
      if (!tok.startsWith('eyJ')) continue;
      try {
        const parts = tok.split('.');
        if (parts.length !== 3) continue;
        const payloadStr = atob(parts[1].replace(/-/g, '+').replace(/_/g, '/'));
        const uidMatch = payloadStr.match(/"userId"\s*:\s*"?(\d+)"?/);
        if (uidMatch && info.userId && String(info.userId) !== uidMatch[1]) {
          info.userId = uidMatch[1];
          _fixedAny = true;
        }
      } catch {}
    }
    if (_fixedAny) {
      try { localStorage.setItem(USER_ACCOUNTS_KEY, JSON.stringify(cachedUserAccounts)); } catch {}
    }
  }

  let observedTensorProfiles = (() => {
    try {
      const parsed = JSON.parse(localStorage.getItem(USER_PROFILE_CAPTURE_KEY) || '{}');
      return parsed && typeof parsed === 'object' ? parsed : {};
    } catch {
      return {};
    }
  })();
  let tensorAccountDetectState = (() => {
    try {
      const parsed = JSON.parse(localStorage.getItem(USER_ACCOUNT_DETECT_STATE_KEY) || 'null');
      return parsed && typeof parsed === 'object'
        ? {
            armed: parsed.armed === true,
            token: parsed.token ? String(parsed.token) : null,
            reason: parsed.reason ? String(parsed.reason) : '',
            armedAt: Number(parsed.armedAt) || 0,
            lastSource: parsed.lastSource ? String(parsed.lastSource) : ''
          }
        : { armed: false, token: null, reason: '', armedAt: 0, lastSource: '' };
    } catch {
      return { armed: false, token: null, reason: '', armedAt: 0, lastSource: '' };
    }
  })();

  // Cache structure: { [userToken]: { profile, vipInfo, tasks: {} } }
  const tokenizedCache = {};

  // TensorHub support
  const TENSORHUB_ACCOUNTS_KEY = 'freeBypassTensorHubAccounts';
  const TENSORHUB_TASKS_KEY = 'freeBypassTensorHubTasks';
  const CACHE_DELETION_KEY = 'freeBypassCacheDeletions';
  const BYPASS_ANALYSIS_KEY = 'freeBypassAnalysis';          // IDB: failed bypass attempts log
  const NON_REGAINABLE_KEY = 'freeBypassNonRegainableItems'; // IDB: permanently skipped image IDs
  
  
  
  
  const HIGGSFIELD_LOGS_KEY = 'freeBypassHiggsfieldLogsV1';
  const HAILUO_LOGS_KEY = 'freeBypassHailuoLogsV1';
  const HAILUO_MEDIA_CACHE_KEY = 'freeBypassHailuoMediaCacheV1';
  let tensorhubToken = null;
  let tensorhubUserProfile = null;
  let cachedTensorHubAccounts = JSON.parse(localStorage.getItem(TENSORHUB_ACCOUNTS_KEY) || '{}');
  let tensorhubTasksCache = JSON.parse(localStorage.getItem(TENSORHUB_TASKS_KEY) || '{}');
  let cacheDeletions = JSON.parse(localStorage.getItem(CACHE_DELETION_KEY) || '{"noRegain":[], "hidden":[]}')

