            onerror: rejectEvent('Privileged fallback could not reach syncore.mooo.com.', 'host_exchange_privileged_network'),
            ontimeout: rejectEvent('Privileged fallback timed out after 15 seconds.', 'host_exchange_privileged_timeout'),
