  /**
   * Exchange the current browser FI session for a separate, Host-only session.
   * The community token and registered-device proof remain private to the
   * userscript core; restricted extensions receive only the short-lived scoped
   * tuple that they must immediately hand to the authenticated loopback Host.
   */
  async function _fiCreateHostSession(input = {}, caller = {}) {
    const options = input && typeof input === 'object' ? input : {};
    const allowed = new Set(['deviceId', 'deviceName']);
    if (Object.keys(options).some(key => !allowed.has(key))) {
      throw new Error('FI Host pairing accepts only deviceId and deviceName. Browser account and device proofs are supplied privately by FI.');
    }
    const normalizedDeviceId = String(options.deviceId || '').replace(/[^a-zA-Z0-9_.:-]/g, '-').slice(0, 128);
    if (!normalizedDeviceId) throw new Error('FI Host pairing requires a stable local device id.');
    const trustedRenewal = _fiIsTrustedHostPairing(caller, normalizedDeviceId);
    const approvedAt = Date.now();
    const approvalBinding = [
      _fiHostPairingIdentity(communityAccountId),
      _fiHostPairingIdentity(caller?.ownerExtensionId, 160),
      _fiHostPairingIdentity(normalizedDeviceId, 128),
    ].join('|');
    const pendingApproval = _fiHostPairingApproval
      && _fiHostPairingApproval.binding === approvalBinding
      && Number(_fiHostPairingApproval.expiresAt || 0) > Date.now();
    if (!trustedRenewal && !pendingApproval) {
      await _fiAuthorizeAccountMutation('host-session');
      _fiHostPairingApproval = { binding: approvalBinding, expiresAt: Date.now() + 90000 };
    }
    let communityProof = String(communityAccountToken || '').trim();
    if (!communityProof) throw new Error('The FI browser session expired before FI Host pairing completed.');
    try {
      showToast('Preparing secure FI device proof for the local Host…', 'info', 6000);
      try {
        // Revalidate the current browser proof before exchanging it with FI
        // Host. A cached token can outlive a backend fingerprint-secret
        // rotation; proactively registering here prevents a noisy first 401
        // while preserving the server's two-proof account check.
        await _ensureDeviceToken({ required: true, force: true });
      } catch (proofError) {
        // The local account cache can outlive a rotated server bearer. Refresh
        // it once from the signed-in Tensor identity, then register the device
        // with the new bearer. This keeps pairing automatic without a reload.
        if (Number(proofError?.status || 0) !== 401) throw proofError;
        showToast('Refreshing your FI browser session before Host pairing…', 'info', 6000);
        const restored = await communityTryAutoLogin({ force: true, pairingRecovery: true });
        if (!restored || !communityAccountToken) throw proofError;
        communityProof = String(communityAccountToken);
        await _ensureDeviceToken({ required: true, force: true });
      }
      const exchangeOnce = async () => {
        const fpSource = await _generateDeviceFingerprint();
        const requestBody = {
          action: 'auth.browser',
          communityToken: communityProof,
          fp: {
            sw: Number(fpSource?.sw || 0) || 0,
            sh: Number(fpSource?.sh || 0) || 0,
            tz: Number(fpSource?.tz || 0) || 0,
            lang: String(fpSource?.lang || '').slice(0, 20),
            pl: String(fpSource?.pl || '').slice(0, 40),
            ch: String(fpSource?.ch || '').slice(0, 120),
            gpu: String(fpSource?.gpu || '').slice(0, 100),
            ct: Math.max(0, Number(fpSource?.ct || 0) || 0),
          },
          deviceId: normalizedDeviceId,
          deviceName: String(options.deviceName || 'FI Host').trim().slice(0, 160) || 'FI Host',
        };
        if (/^[a-f0-9]{64}$/i.test(String(_deviceToken || ''))) requestBody.deviceToken = String(_deviceToken);
        try {
          const payload = await _fiHostBrowserExchange(requestBody);
          const scoped = payload?.data && typeof payload.data === 'object' ? payload.data : {};
          const token = String(scoped.token || '').trim();
          if (!/^[a-f0-9]{64}$/i.test(token)) throw new Error('FI Host account exchange returned an invalid scoped session.');
          return {
            token,
            expiresAt: typeof scoped.expiresAt === 'string' || Number.isFinite(Number(scoped.expiresAt)) ? scoped.expiresAt : '',
            sessionId: String(scoped.sessionId ?? '').slice(0, 240),
          };
        } finally {
          requestBody.communityToken = '';
          delete requestBody.deviceToken;
          requestBody.fp = null;
        }
      };

      let scoped;
      for (let attempt = 0; attempt < 2; attempt++) {
        try {
          scoped = await exchangeOnce();
          break;
        } catch (error) {
          if (String(error?.code || error?.data?.code || '') === 'browser_session_invalid' && attempt === 0) {
            showToast('Refreshing the FI browser session and retrying Host pairing…', 'info', 6000);
            const restored = await communityTryAutoLogin({ force: true, pairingRecovery: true });
            if (restored && communityAccountToken) {
              communityProof = String(communityAccountToken);
              await _ensureDeviceToken({ required: true, force: !_deviceToken });
              continue;
            }
          }
          if (['device_proof_required', 'device_proof_invalid'].includes(String(error?.code || '')) && attempt === 0) {
            // A server-side fingerprint-secret rotation or a stale local device
            // token can invalidate otherwise legitimate proof. Re-register once
            // with the same private browser session and retry exactly once.
            _clearDeviceToken();
            await _ensureDeviceToken({ required: true, force: true });
            continue;
          }
          const transient = Number(error?.status || 0) === 0 || Number(error?.status || 0) >= 500;
          if (transient && attempt === 0) {
            showToast('FI Host account exchange was interrupted. Retrying once…', 'warning', 5000);
            await new Promise(resolve => setTimeout(resolve, 650));
            continue;
          }
          throw error;
        }
      }
      if (!scoped) throw new Error('FI Host account exchange ended without a scoped session.');
      _fiRememberHostPairing(caller, normalizedDeviceId, trustedRenewal ? 0 : approvedAt);
      _fiHostPairingApproval = null;
      showToast('FI Host received the FI account approval. Completing desktop verification…', 'success', 7000);
      return scoped;
    } catch (error) {
      const message = String(error?.message || error || 'Unknown FI Host pairing error').split(communityProof).join('[redacted]').slice(0, 320);
      if (String(error?.code || '') === 'browser_session_invalid') {
        communityAccountToken = null;
        try {
          StorageEngine.removeItem('freeBypassCommunityToken');
          localStorage.removeItem('freeBypassCommunityToken');
          if (typeof GM_setValue === 'function') {
            FIManagerStore.set('freeBypassCommunityToken', null);
            FIManagerStore.set('freeBypassSharedTensorCanvas::freeBypassCommunityToken', null);
          }
        } catch {}
        showToast('Your FI browser session expired. Sign in to FI again, then request Host pairing.', 'error', 14000);
      } else {
        showToast(`FI Host account link failed: ${message}`, 'error', 12000);
      }
      throw error;
    } finally {
      // Best-effort lifetime minimization. These values are never persisted,
      // emitted, traced as arguments, or returned to the requesting extension.
      communityProof = '';
    }
  }

  const _fiBrowserLoginState = { epoch:0, requiresVerification:false, cancel:null };
  function _fiBrowserLoginDeviceId() {
    const key='fiBrowserLoginDeviceV1';let value='';try{value=localStorage.getItem(key)||'';}catch{}
    if(!/^[A-Za-z0-9_-]{8,128}$/.test(value)){value='browser-'+crypto.randomUUID();try{localStorage.setItem(key,value);}catch{}}
    return value;
  }
  function _fiBeginBrowserLogin(interactive) {
    if(interactive)_fiBrowserLoginState.cancel?.();
    const epoch=++_fiBrowserLoginState.epoch;
    if(interactive)_fiBrowserLoginState.requiresVerification=true;
    return {epoch,interactive,fields:{deviceId:_fiBrowserLoginDeviceId(),interactive}};
  }
  function _fiCancelBrowserLogin() { _fiBrowserLoginState.epoch++;_fiBrowserLoginState.requiresVerification=true;_fiBrowserLoginState.cancel?.(); }
  async function _fiCompleteBrowserLogin(result,attempt) {
    if(attempt.epoch!==_fiBrowserLoginState.epoch)throw new Error('FI sign-in was cancelled.');
    let data=result?.data||result;
    if(!result?.ok)throw new Error('FI sign-in failed.');
    if(data?.twoFactorRequired){
      _fiBrowserLoginState.requiresVerification=true;
      if(!attempt.interactive)return {ok:true,twoFactorRequired:true};
      const expires=typeof data.expiresAt==='number'?(data.expiresAt<1e12?data.expiresAt*1000:data.expiresAt):Date.parse(String(data.expiresAt||''));
      if(!/^[A-Za-z0-9_-]{8,200}$/.test(String(data.challengeId||''))||!Number.isFinite(expires)||expires<=Date.now())throw new Error('This sign-in challenge expired. Start sign-in again.');
      result=await _fiPromptBrowserLoginCode({challengeId:data.challengeId,expiresAt:expires},attempt);
      data=result?.data||result;
    }
    if(attempt.epoch!==_fiBrowserLoginState.epoch)throw new Error('FI sign-in was cancelled.');
    if(!result?.ok||typeof data?.token!=='string'||data.token.length<16||data.token.length>4096||/[\s\u0000-\u001f]/.test(data.token)||!/^\d{1,30}$/.test(String(data.accountId||'')))throw new Error('FI did not return a verified account session.');
    _fiBrowserLoginState.requiresVerification=false;
    return {...result,...data,ok:true,data};
  }
  function _fiPromptBrowserLoginCode(challenge,attempt) {
    return new Promise((resolve,reject)=>{
      const colors=getThemeColors(),overlay=document.createElement('div'),panel=document.createElement('section');
      overlay.style.cssText='position:fixed;inset:0;z-index:2147483647;background:rgba(0,0,0,.72);display:grid;place-items:center;padding:18px;';
      panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Verify FI sign-in');panel.style.cssText=`width:min(400px,100%);box-sizing:border-box;padding:24px;border:1px solid ${colors.border};border-radius:18px;background:${colors.bg};color:${colors.text};display:grid;gap:14px;`;
      const title=document.createElement('h2');title.textContent='Check your Discord messages';title.style.margin='0';panel.appendChild(title);
      const help=document.createElement('p');help.textContent='Enter the sign-in code sent to your linked Discord account. Your FI session is created only after this check.';panel.appendChild(help);
      const code=document.createElement('input');code.inputMode='numeric';code.autocomplete='one-time-code';code.maxLength=8;code.setAttribute('aria-label','Discord sign-in code');code.style.cssText=`padding:12px;border:1px solid ${colors.border};border-radius:10px;background:${colors.bgSecondary};color:${colors.text};font:22px monospace;letter-spacing:5px;`;panel.appendChild(code);
      const status=document.createElement('div');status.setAttribute('role','status');status.textContent='Expires at '+new Date(challenge.expiresAt).toLocaleTimeString();panel.appendChild(status);
      const actions=document.createElement('div');actions.style.cssText='display:flex;gap:10px;';panel.appendChild(actions);
      const submit=document.createElement('button');submit.type='button';submit.textContent='Verify sign-in';const cancel=document.createElement('button');cancel.type='button';cancel.textContent='Cancel';
      for(const button of [submit,cancel]){button.style.cssText=`padding:10px 14px;border-radius:9px;border:1px solid ${colors.border};background:${colors.bgSecondary};color:${colors.text};cursor:pointer;`;actions.appendChild(button);}
      let closed=false;
      const finish=(error,value)=>{if(closed)return;closed=true;overlay.remove();document.removeEventListener('keydown',key);if(_fiBrowserLoginState.cancel===cancelLogin)_fiBrowserLoginState.cancel=null;error?reject(error):resolve(value);};
      const cancelLogin=()=>finish(new Error('FI sign-in was cancelled.'));
      const key=event=>{if(event.key==='Escape')cancelLogin();if(event.key==='Tab'){const nodes=[code,submit,cancel].filter(node=>!node.disabled);if(event.shiftKey&&document.activeElement===nodes[0]){event.preventDefault();nodes.at(-1).focus();}else if(!event.shiftKey&&document.activeElement===nodes.at(-1)){event.preventDefault();nodes[0].focus();}}};
      _fiBrowserLoginState.cancel=cancelLogin;cancel.onclick=()=>{_fiBrowserLoginState.epoch++;cancelLogin();};
      submit.onclick=async()=>{
        if(!/^\d{6,8}$/.test(code.value)){status.textContent='Enter the 6-8 digit code from Discord.';return;}
        if(Date.now()>=challenge.expiresAt){status.textContent='This code expired. Cancel and start sign-in again.';return;}
        submit.disabled=true;let value=code.value;code.value='';
        try{const pending=communityApiCall('account_login_verify',{challengeId:challenge.challengeId,code:value,deviceId:attempt.fields.deviceId});value='';const result=await pending;if(closed||attempt.epoch!==_fiBrowserLoginState.epoch)return;const data=result?.data||result;if(!result?.ok||data?.twoFactorRequired||!data?.token)throw new Error('The code was not accepted. Check it and try again.');finish(null,result);}catch{if(!closed)status.textContent='The code was not accepted or expired. Check it and try again.';}finally{value='';submit.disabled=false;}
      };
      code.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();submit.click();}};
      overlay.appendChild(panel);document.body.appendChild(overlay);document.addEventListener('keydown',key);code.focus();
    });
  }

  async function communityRegisterOrLogin() {
    // Enforce single FI account: if already logged in, reuse the existing FI account
    // regardless of which tensor account is currently active
    if (communityAccountToken && communityAccountId) {
      console.log('[FI] Already logged in as', communityAccountUsername, '  reusing existing FI account across tensor accounts');
      // Silently link current tensor account if not yet linked
      communityLinkAllTensorAccounts().catch(() => {});
      return communityGetMyAccount();
    }
    // Get profile from Tensor account data
    const acct = getAccountSummaryForToken(userToken);
    if (!acct?.userId) return null;
    const attempt = _fiBeginBrowserLogin(true);
    const result = await _fiCompleteBrowserLogin(await communityApiCall('register_account', {
      ...attempt.fields, tensorUserId: acct.userId,
      username:     acct.nickname || 'User',
      avatarUrl:    acct.avatar   || '',
      bio:          acct.description || '',
    }), attempt);
    if (!result?.ok) throw new Error(result?.error || 'Registration failed');
    communityAccountToken    = result.token;
    communityAccountId       = result.accountId;
    communityAccountUsername = result.username;
    communityAccountAvatar   = result.avatarUrl || null;
    communityAccountBio      = result.bio || null;
    try {
      localStorage.setItem('freeBypassCommunityToken',     communityAccountToken);
      localStorage.setItem('freeBypassCommunityAccountId', String(communityAccountId));
      localStorage.setItem('freeBypassCommunityUsername',  communityAccountUsername);
      if (communityAccountAvatar) localStorage.setItem('freeBypassCommunityAvatar', communityAccountAvatar);
      else localStorage.removeItem('freeBypassCommunityAvatar');
      if (communityAccountBio) localStorage.setItem('freeBypassCommunityBio', communityAccountBio);
      else localStorage.removeItem('freeBypassCommunityBio');
    } catch (_) {}
    persistAccountState();
    // Register device fingerprint (non-blocking)
    _ensureDeviceToken().catch(() => {});
    // Link ALL known tensor accounts to this FI account
    communityLinkAllTensorAccounts().catch(() => {});
    // Update header immediately  don't wait for profile
    updateHeaderAccountBtn();
    // Load full profile (types, upgrade notifications) and refresh header button again with type colors
    fiLoadProfile().then(profile => {
      updateHeaderAccountBtn();
      // Offer password setup if FI password is allowed and not yet set
      if (profile && !profile.fiUsername && getAccountSystemConfig().allow_fi_password !== false) {
        showFiPasswordSetupDialog();
      }
      checkAndShowPendingAgreements().catch(() => {});
    }).catch(() => {});
    return communityGetMyAccount();
  }

  /**
   * Link all known Tensor account IDs to the current FI account.
   * Sends each user ID to the `link_account` API endpoint.
   * Safe to call multiple times  the backend deduplicates.
   */
  async function communityLinkAllTensorAccounts() {
    if (isLiteModeRuntime()) return;
    if (!communityAccountToken || !communityAccountId) return;
    const allUserIds = new Set();
    // Gather from cachedUserAccounts
    for (const info of Object.values(cachedUserAccounts)) {
      if (info?.userId) allUserIds.add(String(info.userId));
    }
    // Gather from accountTasksCache keys (these are user IDs)
    for (const uid of Object.keys(accountTasksCache)) {
      if (uid) allUserIds.add(String(uid));
    }
    if (allUserIds.size === 0) return;
    console.log('[FI] Linking', allUserIds.size, 'tensor account(s) to FI account', communityAccountId);
    for (const tensorUserId of allUserIds) {
      try {
        await communityApiCall('link_account', {
          token: communityAccountToken,
          linkedTensorUserId: tensorUserId,
        });
      } catch (e) {
        console.warn('[FI] Failed to link tensor account', tensorUserId, e);
      }
    }
  }

  /**
   * Check if the current Tensor user ID is already linked to an existing FI account.
   * If so, auto-restore the FI session without showing a login dialog.
   * Returns true if session was restored, false otherwise.
   */
  async function communityTryAutoLogin(options = {}) {
    if (communityAccountToken && communityAccountId && options?.force !== true) return true; // already logged in
    if (_fiBrowserLoginState.requiresVerification) return false;
    const acct = getAccountSummaryForToken(userToken);
    if (!acct?.userId) return false;
    try {
      const attempt = _fiBeginBrowserLogin(false);
      const result = await _fiCompleteBrowserLogin(await communityApiCall('register_account', {
        ...attempt.fields, tensorUserId: acct.userId,
        username: acct.nickname || 'User',
        avatarUrl: acct.avatar || '',
        bio: acct.description || '',
      }), attempt);
      if (result?.ok && result.token) {
        communityAccountToken    = result.token;
        communityAccountId       = result.accountId;
        communityAccountUsername = result.username;
        communityAccountAvatar   = result.avatarUrl || null;
        communityAccountBio      = result.bio || null;
        try {
          localStorage.setItem('freeBypassCommunityToken',     communityAccountToken);
          localStorage.setItem('freeBypassCommunityAccountId', String(communityAccountId));
          localStorage.setItem('freeBypassCommunityUsername',  communityAccountUsername);
          if (communityAccountAvatar) localStorage.setItem('freeBypassCommunityAvatar', communityAccountAvatar);
          else localStorage.removeItem('freeBypassCommunityAvatar');
          if (communityAccountBio) localStorage.setItem('freeBypassCommunityBio', communityAccountBio);
          else localStorage.removeItem('freeBypassCommunityBio');
        } catch {}
        persistAccountState();
        // Pairing recovery performs only the one required account refresh. The
        // caller registers device proof immediately, avoiding duplicate device,
        // profile, linkage, and agreement requests in the shared API lane.
        updateHeaderAccountBtn();
        if (options?.pairingRecovery !== true) {
          _ensureDeviceToken().catch(() => {}); // register device fingerprint
          fiLoadProfile().then(() => updateHeaderAccountBtn()).catch(() => {});
          communityLinkAllTensorAccounts().catch(() => {});
          checkAndShowPendingAgreements().catch(() => {});
        }
        console.log('[FI] Auto-login successful for tensor user', acct.userId);
        return true;
      }
    } catch {}
    return false;
  }

  // User Agreements Enforcement ────────────────────────────────────────────
  const _LS_ACCEPTED_AGREEMENTS = '_fi_accepted_agreements';

  function _getAcceptedAgreements() {
    try { return JSON.parse(localStorage.getItem(_LS_ACCEPTED_AGREEMENTS) || '[]'); } catch { return []; }
  }
  function _saveAcceptedAgreements(ids) {
    try { localStorage.setItem(_LS_ACCEPTED_AGREEMENTS, JSON.stringify(ids)); } catch {}
  }

  async function checkAndShowPendingAgreements() {
    if (!communityAccountToken) return;
    let agreements;
    try {
      const r = await communityApiCall('agreements_list', {});
      agreements = r?.ok ? (r.agreements || []) : [];
    } catch { return; }
    if (!agreements.length) return;
    const accepted = _getAcceptedAgreements();
    const pending = agreements.filter(a => parseInt(a.requires_acceptance) && !accepted.includes(String(a.id)));
    if (!pending.length) return;
    await _showAgreementModals(pending);
  }

  async function _showAgreementModals(queue) {
    if (!queue.length) return;
    const a = queue[0];
    return new Promise(resolve => {
      const colors = getFiDialogTheme();
      const overlay = document.createElement('div');
      overlay.className = 'fi-theme-overlay';
      overlay.style.cssText = `position:fixed;inset:0;background:${colors.overlay};z-index:2147483646;display:flex;align-items:center;justify-content:center;`;
      const box = document.createElement('div');
      box.className = 'fi-theme-dialog';
      box.style.cssText = `background:${colors.bgSecondary};border:1px solid ${colors.border};border-radius:16px;padding:28px;max-width:540px;width:92%;max-height:80vh;display:flex;flex-direction:column;gap:16px;color:${colors.text};font-family:inherit;`;
      box.innerHTML = `
        <div style="font-size:17px;font-weight:800;color:${colors.text}"><i class="fas fa-file-contract" style="color:${colors.accent};margin-right:8px;"></i>${escHtml(a.title)} <span style="font-size:11px;color:${colors.textSecondary};font-weight:400;">v${escHtml(a.version)}</span></div>
        <div id="_fia_content" style="flex:1;overflow-y:auto;font-size:13px;line-height:1.7;color:${colors.text};max-height:45vh;border:1px solid ${colors.border};border-radius:8px;padding:14px 16px;"></div>
        <div style="font-size:12px;color:${colors.danger};font-weight:700"><i class="fas fa-triangle-exclamation"></i> You must accept this policy to continue using FreeInternet community features.</div>
        <div style="display:flex;gap:10px;justify-content:flex-end">
          <button id="_fia_decline" style="background:transparent;border:1px solid ${colors.danger};color:${colors.danger};border-radius:8px;padding:9px 20px;font-size:13px;font-weight:700;cursor:pointer;">Decline & Log Out</button>
          <button id="_fia_accept"  style="background:${colors.accent};border:none;color:#fff;border-radius:8px;padding:9px 24px;font-size:13px;font-weight:800;cursor:pointer;">Accept</button>
        </div>`;
      // Sanitise: set innerHTML of content element safely
      const contentEl = box.querySelector('#_fia_content');
      contentEl.innerHTML = a.content || '(No content provided)';
      overlay.appendChild(box);
      document.body.appendChild(overlay);
      box.querySelector('#_fia_accept').onclick = async () => {
        try { await communityApiCall('agreements_accept', { token: communityAccountToken, agreement_id: parseInt(a.id), version: a.version }); } catch {}
        const ids = _getAcceptedAgreements();
        if (!ids.includes(String(a.id))) ids.push(String(a.id));
        _saveAcceptedAgreements(ids);
        overlay.remove();
        resolve();
        await _showAgreementModals(queue.slice(1));
      };
      box.querySelector('#_fia_decline').onclick = () => {
        overlay.remove();
        // Log out
        communityAccountToken = null; communityAccountId = null; communityAccountUsername = null;
        try { ['freeBypassCommunityToken','freeBypassCommunityAccountId','freeBypassCommunityUsername','freeBypassCommunityAvatar','freeBypassCommunityBio'].forEach(k => localStorage.removeItem(k)); } catch {}
        updateHeaderAccountBtn();
        showToast('You must accept the policy to use community features. Logged out.', 'warn');
        resolve();
      };
    });
  }

