  function fiHeaderCloseSurface(surface) {
    if (!surface) return;
    if (typeof surface._fiCleanup === 'function') surface._fiCleanup();
    surface.remove();
  }

  function fiHeaderDismissQuickSurfaces(exceptId = '') {
    [...FI_HEADER_QUICK_SURFACE_IDS, 'fiProfileDropdown'].forEach(id => {
      if (id === exceptId) return;
      const node = document.getElementById(id);
      if (node) fiHeaderCloseSurface(node);
    });
    fiHeaderHideTooltip();
  }

  function fiHeaderMountSurface(surface, options = {}) {
    const anchor = options.anchor || null;
    const mount = options.mount || document.body;
    const desiredWidth = Math.max(220, Number(options.width || 430));
    fiHeaderDismissQuickSurfaces(surface.id);
    fiHeaderQuickEnsureStyles();
    mount.appendChild(surface);
    const place = () => {
      if (!surface.isConnected) return;
      const viewportGap = 8;
      const width = Math.min(desiredWidth, window.innerWidth - viewportGap * 2);
      surface.style.width = `${width}px`;
      const measured = surface.getBoundingClientRect();
      if (Number.isFinite(options.clientX) && Number.isFinite(options.clientY)) {
        surface.style.left = `${Math.max(viewportGap, Math.min(options.clientX, window.innerWidth - measured.width - viewportGap))}px`;
        surface.style.top = `${Math.max(viewportGap, Math.min(options.clientY, window.innerHeight - measured.height - viewportGap))}px`;
        return;
      }
      const rect = anchor?.getBoundingClientRect?.() || { left: viewportGap, right: viewportGap + width, top: viewportGap, bottom: viewportGap };
      const left = Math.max(viewportGap, Math.min(rect.right - measured.width, window.innerWidth - measured.width - viewportGap));
      const below = window.innerHeight - rect.bottom - viewportGap;
      const above = rect.top - viewportGap;
      const openUp = below < Math.min(measured.height, 430) && above > below;
      const top = openUp ? Math.max(viewportGap, rect.top - measured.height - 7) : Math.min(window.innerHeight - measured.height - viewportGap, rect.bottom + 7);
      surface.style.left = `${left}px`;
      surface.style.top = `${Math.max(viewportGap, top)}px`;
      surface.dataset.openDirection = openUp ? 'up' : 'down';
    };
    let closed = false;
    const dismiss = event => {
      if (surface.contains(event.target) || anchor?.contains?.(event.target)) return;
      close();
    };
    const keydown = event => { if (event.key === 'Escape') close(); };
    const close = () => {
      if (closed) return;
      closed = true;
      document.removeEventListener('pointerdown', dismiss, true);
      document.removeEventListener('keydown', keydown, true);
      window.removeEventListener('resize', place);
      window.removeEventListener('scroll', close);
      fiHeaderHideTooltip();
      surface.remove();
    };
    surface._fiCleanup = () => {
      document.removeEventListener('pointerdown', dismiss, true);
      document.removeEventListener('keydown', keydown, true);
      window.removeEventListener('resize', place);
      window.removeEventListener('scroll', close);
    };
    surface._fiClose = close;
    place();
    requestAnimationFrame(place);
    setTimeout(() => document.addEventListener('pointerdown', dismiss, true), 0);
    document.addEventListener('keydown', keydown, true);
    window.addEventListener('resize', place);
    window.addEventListener('scroll', close, { passive: true });
    return close;
  }

  function fiHeaderTooltipMarkup(title, intro, facts = [], footer = '') {
    return `<div class="fi-tip-head"><strong>${escapeHtml(title)}</strong>${intro ? `<p>${escapeHtml(intro)}</p>` : ''}</div>${facts.length ? `<div class="fi-tip-facts">${facts.map(fact => `<div class="fi-tip-fact"><i class="fas ${escapeHtml(fact.icon || 'fa-circle-info')}"></i><b>${escapeHtml(fact.label || '')}</b><span>${escapeHtml(fact.value || '')}</span></div>`).join('')}</div>` : ''}${footer ? `<div class="fi-tip-foot">${escapeHtml(footer)}</div>` : ''}`;
  }

  function fiHeaderHideTooltip() {
    clearTimeout(fiHeaderTooltipTimer);
    fiHeaderTooltipTimer = 0;
    document.getElementById('fiHeaderRichTooltip')?.remove();
  }

  function fiHeaderShowTooltip(anchor, html) {
    if (!anchor?.isConnected || settings.headerChipTooltipsEnabled === false || window.innerWidth <= 520) return;
    fiHeaderQuickEnsureStyles();
    document.getElementById('fiHeaderRichTooltip')?.remove();
    const tooltip = document.createElement('div');
    tooltip.id = 'fiHeaderRichTooltip';
    tooltip.className = 'fi-rich-tooltip';
    tooltip.setAttribute('role', 'tooltip');
    tooltip.innerHTML = html;
    document.body.appendChild(tooltip);
    const rect = anchor.getBoundingClientRect();
    const tipRect = tooltip.getBoundingClientRect();
    const gap = 11;
    const canRight = rect.right + gap + tipRect.width <= window.innerWidth - 8;
    const side = canRight ? 'right' : 'left';
    tooltip.dataset.side = side;
    const left = side === 'right' ? rect.right + gap : rect.left - tipRect.width - gap;
    const top = Math.max(8, Math.min(rect.top + rect.height / 2 - Math.min(tipRect.height, 380) / 2, window.innerHeight - tipRect.height - 8));
    tooltip.style.left = `${Math.max(8, Math.min(left, window.innerWidth - tipRect.width - 8))}px`;
    tooltip.style.top = `${top}px`;
  }

  function fiHeaderBindTooltip(element, content, options = {}) {
    if (!element) return;
    const insight = options.insight === true;
    const show = () => {
      if (settings.headerChipTooltipsEnabled === false || (insight && settings.headerQuickMenuInsightsEnabled === false)) return;
      clearTimeout(fiHeaderTooltipTimer);
      fiHeaderTooltipTimer = setTimeout(() => {
        const html = typeof content === 'function' ? content() : content;
        if (html) fiHeaderShowTooltip(element, html);
      }, Number(options.delay || 330));
    };
    element.addEventListener('pointerenter', show);
    element.addEventListener('pointerleave', fiHeaderHideTooltip);
    element.addEventListener('focus', show);
    element.addEventListener('blur', fiHeaderHideTooltip);
  }

  function fiCreditRewardTooltipMarkup(rule) {
    const description = rule?.description || {};
    const progress = rule?.progress || {};
    const threshold = Math.max(1, Number(rule?.thresholdCount || 1));
    const count = Math.max(0, Number(progress.count || 0));
    const requirements = Array.isArray(description.requirements) ? description.requirements : [];
    const steps = Array.isArray(description.steps) ? description.steps : [];
    const summary = fiCreditCleanChallengeText(description.long || description.summary || `Complete this verified Discord challenge to earn ${Number(rule?.amount || 0).toLocaleString()} FI Credits.`);
    const facts = [
      { icon: 'fa-coins', label: 'Reward', value: fiCreditExactLabel(rule?.amount || 0) },
      { icon: 'fa-chart-line', label: 'Progress', value: rule?.mode === 'window_threshold' ? `${Math.min(count, threshold)} of ${threshold} verified` : 'Paid on each verified event' },
      { icon: 'fa-rotate', label: 'Availability', value: Number(rule?.cooldownSeconds || 0) ? `Every ${Number(rule.cooldownSeconds)} seconds` : (rule?.dailyRotation ? 'Rotates daily' : 'Always available while enabled') },
    ];
    if (requirements.length) facts.push({ icon: 'fa-list-check', label: 'Requirements', value: requirements.join(' · ') });
    if (steps.length) facts.push({ icon: 'fa-route', label: 'Steps', value: steps.join(' → ') });
    return fiHeaderTooltipMarkup(rule?.name || rule?.key || 'Discord reward', summary, facts, 'Open the full FI Credits wallet for the complete challenge view.');
  }

  async function fiCreditShowQuickMenu(anchor, initialTab = 'rewards') {
    if (!communityAccountToken) { showFiLoginDialog(); return; }
    const existing = document.getElementById('fiCreditQuickMenu');
    if (existing) { fiHeaderCloseSurface(existing); return; }
    if (settings.headerQuickMenusEnabled === false) { fiCreditOpenWallet(initialTab === 'rewards' ? 'earn' : initialTab); return; }
    const menu = document.createElement('section');
    menu.id = 'fiCreditQuickMenu';
    menu.className = 'fi-header-surface';
    menu.setAttribute('role', 'dialog');
    menu.setAttribute('aria-label', 'Quick FI Credits wallet');
    menu.innerHTML = `<header class="fi-q-head"><div class="fi-q-logo"><i class="fas fa-coins"></i></div><div class="fi-q-head-copy"><div class="fi-q-eyebrow">FI Credits</div><div class="fi-q-title">Your quick wallet</div><div class="fi-q-subtitle">Rewards, activity, and purchases without leaving your work</div></div><div class="fi-q-balance" title="${escapeHtml(fiCreditExactLabel(fiCreditWalletValue()))}"><strong data-q-balance>${escapeHtml(fiCreditPlatformSnapshot ? fiCreditFormatCompact(fiCreditWalletValue()) : '…')}</strong><small>Available</small></div><button type="button" class="fi-q-head-btn" data-q-refresh aria-label="Refresh wallet"><i class="fas fa-rotate"></i></button></header><nav class="fi-q-tabs" aria-label="Quick wallet sections"><button type="button" class="fi-q-tab" data-q-tab="rewards"><i class="fab fa-discord"></i>Rewards</button><button type="button" class="fi-q-tab" data-q-tab="activity"><i class="fas fa-clock-rotate-left"></i>Activity</button><button type="button" class="fi-q-tab" data-q-tab="purchases"><i class="fas fa-bag-shopping"></i>Purchases</button></nav><div class="fi-q-body" data-q-body><div class="fi-q-loading"><div><i class="fas fa-circle-notch fa-spin"></i>Loading your wallet…</div></div></div><footer class="fi-q-footer"><button type="button" data-q-full><i class="fas fa-up-right-from-square"></i> Show full FI Credits wallet</button><span>Right-click the credit chip for actions</span></footer>`;
    const close = fiHeaderMountSurface(menu, { anchor, width: 430 });
    let active = ['rewards', 'activity', 'purchases'].includes(initialTab) ? initialTab : 'rewards';
    let data = fiCreditPlatformSnapshot || {};
    let sequence = 0;
    const body = menu.querySelector('[data-q-body]');
    const setTabs = () => menu.querySelectorAll('[data-q-tab]').forEach(button => button.classList.toggle('is-active', button.dataset.qTab === active));
    const empty = (icon, title, copy, action = '') => `<div class="fi-q-empty"><div><i class="fas ${escapeHtml(icon)}"></i><strong>${escapeHtml(title)}</strong><p>${escapeHtml(copy)}</p>${action}</div></div>`;
    const renderRewards = () => {
      const discord = data?.discord || {};
      const rules = Array.isArray(discord.rewardRules) ? discord.rewardRules : [];
      const ready = rules.filter(rule => rule.progress?.claimable).length;
      if (!rules.length) {
        body.innerHTML = empty('fa-gift', discord.linked ? 'No rewards published yet' : 'Connect Discord to earn', discord.linked ? 'Enabled FI community challenges will appear here.' : 'Securely link Discord to load your personalized challenges.', '<button type="button" class="fi-q-icon-action primary" data-q-connect style="margin-top:10px"><i class="fab fa-discord"></i><span style="max-width:100px;opacity:1">Open rewards</span></button>');
        body.querySelector('[data-q-connect]')?.addEventListener('click', () => { close(); fiCreditOpenWallet('earn'); });
        return;
      }
      body.innerHTML = `<div class="fi-q-summary"><strong>${rules.length} active challenge${rules.length === 1 ? '' : 's'}</strong><span>${ready} ready to claim</span></div><div class="fi-q-rewards">${rules.map((rule, index) => {
        const progress = rule.progress || {};
        const threshold = Math.max(1, Number(rule.thresholdCount || 1));
        const count = Math.max(0, Number(progress.count || 0));
        const percent = rule.mode === 'window_threshold' ? Math.min(100, Math.round(count / threshold * 100)) : 0;
        const description = rule.description || {};
        const summary = fiCreditCleanChallengeText(description.summary) || (rule.mode === 'window_threshold' ? `${Math.min(count, threshold)} of ${threshold} verified actions` : 'Earn on every verified action');
        const badges = `${progress.claimable ? '<span class="fi-q-badge ready"><i class="fas fa-gift"></i>Ready</span>' : ''}${rule.targeted ? '<span class="fi-q-badge private"><i class="fas fa-lock"></i>For you</span>' : ''}${rule.dailyRotation || rule.dailyRandomAmount ? '<span class="fi-q-badge daily"><i class="fas fa-shuffle"></i>Daily</span>' : ''}`;
        const actionUrl = rule.actionUrl || discord.inviteUrl || '';
        const action = actionUrl ? `<a class="fi-q-icon-action" href="${escapeHtml(actionUrl)}" target="_blank" rel="noopener noreferrer" aria-label="${escapeHtml(rule.actionLabel || 'Open Discord')}"><i class="fas fa-arrow-up-right-from-square"></i><span>${escapeHtml(rule.actionLabel || 'Open')}</span></a>` : '';
        const claim = rule.mode === 'window_threshold' ? `<button type="button" class="fi-q-icon-action primary" data-q-claim="${index}" ${progress.claimable ? '' : 'disabled'}><i class="fas fa-gift"></i><span>${progress.claimable ? 'Claim' : `${Math.min(count, threshold)}/${threshold}`}</span></button>` : '';
        return `<article class="fi-q-reward" data-q-rule="${index}"><div class="fi-q-reward-icon"><i class="fas ${escapeHtml(rule.icon || 'fa-sparkles')}"></i></div><div class="fi-q-reward-copy"><div class="fi-q-reward-title"><strong>${escapeHtml(rule.name || rule.key || 'Discord reward')}</strong>${badges}</div><small>${escapeHtml(summary)}</small><div class="fi-q-reward-meta"><span>${rule.mode === 'window_threshold' ? `${Math.min(count, threshold)}/${threshold} complete` : 'Verified automatically'}</span><b class="fi-q-reward-amount">+${escapeHtml(fiCreditFormatCompact(rule.amount || 0))}</b></div>${rule.mode === 'window_threshold' ? `<div class="fi-q-mini-progress" title="${count} of ${threshold}"><i style="width:${percent}%"></i></div>` : ''}</div><div class="fi-q-actions">${action}${claim}<button type="button" class="fi-q-icon-action" data-q-info="${index}" aria-label="Full details"><i class="fas fa-circle-info"></i><span>Details</span></button></div></article>`;
      }).join('')}</div>`;
      body.querySelectorAll('[data-q-rule]').forEach(card => {
        const rule = rules[Number(card.dataset.qRule)];
        fiHeaderBindTooltip(card, () => fiCreditRewardTooltipMarkup(rule), { insight: true, delay: 280 });
      });
      body.querySelectorAll('[data-q-info]').forEach(button => button.onclick = event => { event.stopPropagation(); close(); fiCreditOpenWallet('earn'); });
      body.querySelectorAll('[data-q-claim]').forEach(button => button.onclick = async event => {
        event.stopPropagation();
        const rule = rules[Number(button.dataset.qClaim)];
        if (!rule?.progress?.claimable) return;
        try {
          button.disabled = true;
          button.innerHTML = '<i class="fas fa-spinner fa-spin"></i><span>Claiming</span>';
          const result = await fiCreditCoreCall('discord.reward.claim', { ruleKey: rule.key });
          fiCreditPublishWallet(result.data?.wallet);
          showToast(`+${fiCreditFormatCompact(result.data?.amount || 0)} FI Credits claimed`, 'success');
          data = await fiCreditRefresh(true);
          if (menu.isConnected) { menu.querySelector('[data-q-balance]').textContent = fiCreditFormatCompact(fiCreditWalletValue()); renderRewards(); }
        } catch (error) { showToast(error.message || 'Reward claim failed', 'error'); if (menu.isConnected) renderRewards(); }
      });
    };
    const render = async (force = false) => {
      const currentSequence = ++sequence;
      setTabs();
      body.innerHTML = '<div class="fi-q-loading"><div><i class="fas fa-circle-notch fa-spin"></i>Loading…</div></div>';
      try {
        data = await fiCreditRefresh(force);
        if (currentSequence !== sequence || !menu.isConnected) return;
        menu.querySelector('[data-q-balance]').textContent = fiCreditFormatCompact(fiCreditWalletValue());
        menu.querySelector('.fi-q-balance').title = fiCreditExactLabel(fiCreditWalletValue());
        if (active === 'rewards') { renderRewards(); return; }
        if (active === 'activity') {
          const activity = await fiCreditCachedRead('credits.activity', { limit: 12 }, force);
          if (currentSequence !== sequence || !menu.isConnected) return;
          if (activity.wallet) fiCreditPublishWallet(activity.wallet);
          const rows = Array.isArray(activity.data) ? activity.data.slice(0, 12) : [];
          body.innerHTML = rows.length ? `<div class="fi-q-summary"><strong>Recent wallet activity</strong><span>${rows.length} shown</span></div>${rows.map(row => {
            const amount = Number(row.amount || 0);
            const positive = amount > 0;
            return `<div class="fi-q-row"><div class="fi-q-row-icon" style="color:${positive ? '#86efac' : amount < 0 ? '#f9a8d4' : '#a5b4fc'};background:${positive ? 'rgba(16,185,129,.12)' : amount < 0 ? 'rgba(244,114,182,.11)' : 'rgba(99,102,241,.12)'}"><i class="fas ${positive ? 'fa-arrow-down-left' : amount < 0 ? 'fa-arrow-up-right' : 'fa-receipt'}"></i></div><div class="fi-q-row-copy"><strong>${escapeHtml(row.note || row.kind || 'Wallet update')}</strong><small>${escapeHtml(row.createdAt || '')} · ${escapeHtml(row.status || '')}</small></div><strong class="fi-q-row-value" style="color:${positive ? '#86efac' : amount < 0 ? '#f9a8d4' : '#c4b5fd'}">${positive ? '+' : ''}${escapeHtml(fiCreditFormatCompact(amount))}</strong></div>`;
          }).join('')}` : empty('fa-clock-rotate-left', 'No activity yet', 'Rewards, transfers, purchases, and feature charges will appear here.');
          return;
        }
        const entitlements = Array.isArray(data?.entitlements) ? data.entitlements : [];
        const products = (Array.isArray(data?.products) ? data.products : []).filter(product => ['entitlement', 'pass'].includes(product.type));
        body.innerHTML = `<div class="fi-q-summary"><strong>Your purchases</strong><span>${entitlements.length} owned</span></div>${entitlements.map(item => `<div class="fi-q-row"><div class="fi-q-row-icon" style="color:#86efac;background:rgba(16,185,129,.12)"><i class="fas fa-badge-check"></i></div><div class="fi-q-row-copy"><strong>${escapeHtml(item.name || item.productKey)}</strong><small>${escapeHtml(item.type || 'entitlement')} · ${item.expiresAt ? `expires ${escapeHtml(item.expiresAt)}` : 'permanent'}</small></div><span class="fi-q-badge ready">Owned</span></div>`).join('') || empty('fa-bag-shopping', 'Nothing purchased yet', `${products.length} FI Store product${products.length === 1 ? ' is' : 's are'} currently available.`)}`;
      } catch (error) {
        if (currentSequence !== sequence || !menu.isConnected) return;
        body.innerHTML = empty('fa-triangle-exclamation', 'Wallet unavailable', error.message || 'FI Credits could not be loaded.');
      }
    };
    menu.querySelectorAll('[data-q-tab]').forEach(button => button.onclick = () => { active = button.dataset.qTab; render(false); });
    menu.querySelector('[data-q-refresh]').onclick = async () => {
      const icon = menu.querySelector('[data-q-refresh] i');
      icon?.classList.add('fa-spin');
      await render(true);
      icon?.classList.remove('fa-spin');
    };
    menu.querySelector('[data-q-full]').onclick = () => { const target = active === 'rewards' ? 'earn' : active; close(); fiCreditOpenWallet(target); };
    await render(false);
  }

  function fiCreditShowContextMenu(event, anchor = null, mount = document.body) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    if (!communityAccountToken) { showFiLoginDialog(); return; }
    const menu = document.createElement('div');
    menu.id = 'fiCreditContextMenu';
    menu.className = 'fi-header-surface fi-q-context';
    menu.setAttribute('role', 'menu');
    menu.innerHTML = `<div class="fi-q-context-head"><i class="fas fa-coins"></i><div><strong>FI Credits</strong><small>${escapeHtml(fiCreditExactLabel(fiCreditWalletValue()))} available</small></div></div><button class="fi-q-context-item" data-q-context="refresh"><i class="fas fa-rotate"></i>Refresh wallet now</button><button class="fi-q-context-item" data-q-context="rewards"><i class="fab fa-discord"></i>Rewards and challenges</button><button class="fi-q-context-item" data-q-context="transfer"><i class="fas fa-arrow-right-arrow-left"></i>Transfer credits</button><div class="fi-q-context-sep"></div><button class="fi-q-context-item" data-q-context="activity"><i class="fas fa-clock-rotate-left"></i>Wallet activity</button><button class="fi-q-context-item" data-q-context="purchases"><i class="fas fa-bag-shopping"></i>Purchases</button><button class="fi-q-context-item" data-q-context="full"><i class="fas fa-up-right-from-square"></i>Open full wallet</button>`;
    const close = fiHeaderMountSurface(menu, { anchor, mount, width: 260, clientX: Number(event?.clientX), clientY: Number(event?.clientY) });
    menu.querySelectorAll('[data-q-context]').forEach(button => button.onclick = async () => {
      const action = button.dataset.qContext;
      close();
      if (action === 'refresh') {
        try { await fiCreditRefresh(true); updateHeaderAccountBtn(); showToast('FI Credits refreshed', 'success'); } catch (error) { showToast(error.message || 'Wallet refresh failed', 'error'); }
        return;
      }
      const views = { rewards: 'earn', transfer: 'transfer', activity: 'activity', purchases: 'purchases', full: 'overview' };
      fiCreditOpenWallet(views[action] || 'overview');
    });
  }

  function fiAccountQuickTooltipMarkup(account) {
    const meta = getAccountMeta(account?.userId) || {};
    const tokenInfo = account?.tokenInfo || analyzeTensorAccountToken(account?.token);
    const taskCount = getAccountTaskCount(account?.token);
    const credits = getAccountCreditBalance(account);
    let analytics = {};
    try { _analyticsLoadState(); analytics = _analyticsState?.accounts?.[String(account?.userId || '')] || {}; } catch {}
    const facts = [
      { icon: 'fa-list-check', label: 'Stored tasks', value: Number(taskCount).toLocaleString() },
      { icon: 'fa-coins', label: 'Cached credits', value: Number.isFinite(credits) ? Number(credits).toLocaleString() : 'Not cached yet' },
      { icon: 'fa-shield-halved', label: 'Session', value: tokenInfo.expired ? `Expired ${tokenInfo.remainingText}` : `${tokenInfo.statusLabel} · ${tokenInfo.remainingText}` },
      { icon: 'fa-wand-magic-sparkles', label: 'Bypass results', value: `${Number(analytics.bypassSuccess || 0).toLocaleString()} success · ${Number(analytics.bypassFails || 0).toLocaleString()} failed` },
    ];
    if (meta.lastUsedAt || account?.timestamp) facts.push({ icon: 'fa-clock', label: 'Last used', value: new Date(meta.lastUsedAt || account.timestamp).toLocaleString() });
    const profile = account?.profileData?.profile?.info || {};
    const intro = meta.notes || profile.description || account?.description || `Tensor account ${String(account?.userId || tokenInfo.userId || '').slice(-8)}`;
    return fiHeaderTooltipMarkup(meta.alias || account?.nickname || profile.nickname || 'Tensor account', intro, facts, 'Click Switch to make this the active Tensor account. Expired sessions must be added again.');
  }

  function fiShowTensorAccountQuickSwitcher(anchor, event) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    const existing = document.getElementById('fiTensorAccountQuickSwitcher');
    if (existing) { fiHeaderCloseSurface(existing); return; }
    let accounts = getAllCachedAccounts();
    if (userToken && !accounts.some(account => isCurrentAccount(account))) {
      const current = getAccountSummaryForToken(userToken);
      if (current) accounts.push({ ...current, profileData: cachedUserProfiles[userToken] || null, timestamp: Date.now() });
    }
    accounts = accounts.slice().sort((a, b) => compareAccountsForDisplay(a, b, { currentFirst: true }));
    const current = accounts.find(account => isCurrentAccount(account)) || null;
    const others = accounts.filter(account => !isCurrentAccount(account));
    const colors = getThemeColors();
    const safeColor = value => /^#[0-9a-f]{3,8}$/i.test(String(value || '')) ? String(value) : colors.primary;
    const renderAccount = (account, index, isCurrent) => {
      const meta = getAccountMeta(account.userId) || {};
      const tokenInfo = account.tokenInfo || analyzeTensorAccountToken(account.token);
      const color = safeColor(meta.color);
      const avatar = account.profileData?.profile?.info?.avatar || account.avatar || '';
      const vip = !!account.profileData?.vipInfo?.isVip;
      const tasks = getAccountTaskCount(account.token);
      const disabled = isCurrent || tokenInfo.expired || settings.accountSwitchEnabled === false;
      return `<article class="fi-q-account ${isCurrent ? 'is-current' : ''}" data-q-account="${index}" style="--fi-account-color:${color};--fi-account-border:${tokenInfo.statusBorder || colors.border}">${avatar ? `<img class="fi-q-avatar" src="${escapeHtml(avatar)}" alt="" onerror="this.style.display='none'">` : '<div class="fi-q-avatar"><i class="fas fa-user"></i></div>'}<div class="fi-q-account-copy"><div class="fi-q-account-name">${meta.pinned ? '<i class="fas fa-thumbtack" style="color:#fbbf24;font-size:7px"></i>' : ''}<strong>${escapeHtml(meta.alias || account.nickname || 'Unknown account')}</strong>${vip ? '<span class="fi-q-badge daily">VIP</span>' : ''}</div><div class="fi-q-account-sub">${escapeHtml(String(account.userId || tokenInfo.userId || '').slice(-10) || 'Unknown ID')} · ${tasks} task${tasks === 1 ? '' : 's'}</div><div class="fi-q-account-badges"><span class="fi-q-account-status" style="--status-color:${tokenInfo.statusTone};--status-bg:${tokenInfo.statusBg};--status-border:${tokenInfo.statusBorder}">${escapeHtml(tokenInfo.expired ? 'Expired' : tokenInfo.statusLabel)}</span>${isCurrent ? '<span class="fi-q-badge ready">Current</span>' : ''}</div></div><button type="button" class="fi-q-account-switch" data-q-switch="${index}" ${disabled ? 'disabled' : ''}>${isCurrent ? 'Active' : tokenInfo.expired ? 'Expired' : settings.accountSwitchEnabled === false ? 'Disabled' : 'Switch'}</button></article>`;
    };
    const indexedAccounts = [...(current ? [current] : []), ...others];
    const menu = document.createElement('section');
    menu.id = 'fiTensorAccountQuickSwitcher';
    menu.className = 'fi-header-surface';
    menu.setAttribute('role', 'dialog');
    menu.setAttribute('aria-label', 'Tensor account switcher');
    menu.innerHTML = `<header class="fi-q-head"><div class="fi-q-logo" style="background:linear-gradient(135deg,#f59e0b,#7c3aed)"><i class="fas fa-users-gear"></i></div><div class="fi-q-head-copy"><div class="fi-q-eyebrow">Tensor accounts</div><div class="fi-q-title">Fast account switcher</div><div class="fi-q-subtitle">Uses your saved order, pins, aliases, and account colors</div></div><button type="button" class="fi-q-head-btn" data-q-manage aria-label="Manage accounts"><i class="fas fa-sliders"></i></button></header><div class="fi-q-account-list">${current ? `<div class="fi-q-account-label">Current account <span>${escapeHtml(getAccountSortLabel())}</span></div>${renderAccount(current, 0, true)}` : '<div class="fi-q-account-label">Current account</div><div class="fi-q-empty" style="min-height:90px"><div><strong>No current Tensor account detected</strong></div></div>'}<div class="fi-q-account-label" style="margin-top:10px">Other accounts <span>${others.length} available</span></div>${others.map((account, offset) => renderAccount(account, offset + (current ? 1 : 0), false)).join('') || '<div class="fi-q-empty" style="min-height:100px"><div><i class="fas fa-user-plus"></i><strong>No other saved accounts</strong><p>Add accounts from the Accounts tab.</p></div></div>'}</div><footer class="fi-q-footer"><button type="button" data-q-manage-footer><i class="fas fa-users-gear"></i> Manage accounts and ordering</button><span>Hover an account for insights</span></footer>`;
    const close = fiHeaderMountSurface(menu, { anchor, width: 430 });
    menu.querySelectorAll('[data-q-account]').forEach(card => {
      const account = indexedAccounts[Number(card.dataset.qAccount)];
      fiHeaderBindTooltip(card, () => fiAccountQuickTooltipMarkup(account), { insight: true, delay: 300 });
    });
    menu.querySelectorAll('[data-q-switch]').forEach(button => button.onclick = click => {
      click.stopPropagation();
      const account = indexedAccounts[Number(button.dataset.qSwitch)];
      if (!account || button.disabled) return;
      close();
      switchTensorAccountByToken(account.token);
    });
    const manage = () => { close(); isExpanded = true; currentTab = 'accounts'; updateUI(); };
    menu.querySelector('[data-q-manage]').onclick = manage;
    menu.querySelector('[data-q-manage-footer]').onclick = manage;
  }

  function fiCreditOwnerIdentity(ext = {}) {
    const meta = ext.meta || {};
    return String(meta.fieStoreId || ext.storeId || ext.fieStoreId || ext.id || '').trim().slice(0, 160);
  }

  function fiCreditCreateOwnerApi(ext, blocked, deny, trace) {
    const ownerExtensionId = fiCreditOwnerIdentity(ext);
    const ownerProof = String(ext.meta?.fiCreditOwnerProof || ext.fiCreditOwnerProof || '').trim().slice(0, 4096);
    const ownerName = String(ext.name || ext.meta?.name || 'FI Extension').slice(0, 120);
    const call = async (action, payload = {}) => {
      if (!ownerExtensionId) throw new Error('This extension has no stable FI Store identity.');
      if (!ownerProof) throw new Error('Reinstall or update this extension from the FI Extension Store to authorize FI Credits securely.');
      const result = await fiCreditCoreCall(action, { ...payload, ownerExtensionId, ownerProof });
      if (result.data?.wallet) fiCreditPublishWallet(result.data.wallet);
      return result.data;
    };
    const readDenied = blocked.has('credits_read');
    const spendDenied = blocked.has('credits_spend');
    return Object.freeze({
      getWallet: readDenied ? deny('credits_read','api.credits.getWallet') : trace('api.credits.getWallet', async () => { await fiCreditRefresh(false); return fiCreditPublicWallet(); }, 'medium'),
      getProducts: readDenied ? deny('credits_read','api.credits.getProducts') : trace('api.credits.getProducts', async () => { const data=await fiCreditRefresh(false); return Object.freeze((data?.products||[]).filter(item=>String(item.extensionId||'')===ownerExtensionId).map(item=>Object.freeze({...item}))); }, 'medium'),
      getEntitlements: readDenied ? deny('credits_read','api.credits.getEntitlements') : trace('api.credits.getEntitlements', async () => { const data=await fiCreditRefresh(false); return Object.freeze((data?.entitlements||[]).filter(item=>String(item.extensionId||'')===ownerExtensionId).map(item=>Object.freeze({...item}))); }, 'medium'),
      quote: readDenied ? deny('credits_read','api.credits.quote') : trace('api.credits.quote', productKey => call('credits.quote',{productKey:String(productKey||'').slice(0,160)}), 'medium'),
      purchase: spendDenied ? deny('credits_spend','api.credits.purchase') : trace('api.credits.purchase', async productKey => { const key=String(productKey||'').slice(0,160); const quote=await call('credits.quote',{productKey:key}); if(quote.owned&&quote.type==='entitlement') return {ok:true,alreadyOwned:true,productKey:key,wallet:fiCreditPublicWallet()}; const terms=quote.periodDays?'Access lasts '+quote.periodDays+' days and renews manually.':'This is a one-time entitlement.'; const ok=await fiCreditConfirm('Confirm FI Credits purchase',ownerName+'\n'+quote.name+'\n\nCost: '+quote.cost+' FI credits\nRemaining: '+quote.remainingAfter+'\n'+terms,'Purchase'); if(!ok)return {ok:false,cancelled:true}; const result=await call('credits.purchase',{productKey:key,operationId:crypto.randomUUID?.()||('purchase_'+Date.now()+'_'+Math.random().toString(36).slice(2))}); await fiCreditRefresh(true); return result; }, 'critical'),
      consume: spendDenied ? deny('credits_spend','api.credits.consume') : trace('api.credits.consume', async (productKey,operationId) => { const key=String(productKey||'').slice(0,160); const op=String(operationId||'').slice(0,120); if(!op)throw new Error('A stable operationId is required.'); const quote=await call('credits.quote',{productKey:key}); const ok=await fiCreditConfirm('Confirm costly FI feature',ownerName+' wants to use '+quote.name+'.\n\nCost: '+quote.cost+' FI credits\nRemaining: '+quote.remainingAfter,'Use feature'); if(!ok)return {ok:false,cancelled:true}; const result=await call('credits.consume',{productKey:key,operationId:op}); await fiCreditRefresh(true); return result; }, 'critical'),
      claimReward: spendDenied ? deny('credits_spend','api.credits.claimReward') : trace('api.credits.claimReward', async receipt => { const result={data:await call('credits.reward.claim',{receipt:String(receipt||'').slice(0,12000)})}; await fiCreditRefresh(true); return result.data; }, 'critical'),
      openWallet: trace('api.credits.openWallet', view => { fiCreditOpenWallet(view); }, 'low'),
      onChanged: readDenied ? deny('credits_read','api.credits.onChanged') : trace('api.credits.onChanged', handler => { if(typeof handler!=='function')throw new Error('A wallet change handler is required.'); const entry={ownerExtensionId,handler}; fiCreditPlatformListeners.add(entry); return () => fiCreditPlatformListeners.delete(entry); }, 'medium'),
    });
  }

  /**
   * Re-render the profile/login button inside the bypass header.
   * Call after login, logout, or header rebuild.
   */
  function renderFiDockedAccountFooter(container, colors) {
    const previousFooter = container.querySelector('.fi-docked-account-footer');
    try { previousFooter?._fiSizeObserver?.disconnect(); } catch {}
    previousFooter?.remove();
    container.classList.remove('has-fi-docked-footer');
    container.style.removeProperty('--fi-docked-footer-height');
    if (!settings.dockedAccountFooterEnabled) return;
    const footer = document.createElement('div');
    footer.className = `fi-docked-account-footer${settings.dockedAccountFooterCollapsed ? ' is-collapsed' : ''}`;
    footer.dataset.align = settings.dockedAccountFooterAlignment || 'right';
    footer.setAttribute('data-fi-element', 'docked-account-footer');
    footer.style.setProperty('--fi-footer-border', colors.border || 'rgba(148,163,184,.18)');
    footer.style.setProperty('--fi-footer-bg', colors.panel || colors.bg || '#020617');
    footer.style.setProperty('--fi-footer-bg-2', colors.bgSecondary || colors.bg || '#0c111f');
    footer.style.setProperty('--fi-footer-text', colors.text || '#f8fafc');
    footer.style.setProperty('--fi-footer-muted', colors.textSecondary || '#94a3b8');
    footer.style.setProperty('--fi-footer-accent', colors.primary || '#22d3ee');
    footer.innerHTML = `<button type="button" class="fi-docked-account-toggle" title="${settings.dockedAccountFooterCollapsed ? 'Expand account dock' : 'Collapse account dock'}" aria-expanded="${settings.dockedAccountFooterCollapsed ? 'false' : 'true'}"><i class="fas fa-chevron-${settings.dockedAccountFooterCollapsed ? 'up' : 'down'}"></i></button><div id="fiFooterExtensionSlot" class="fi-footer-extension-slot" data-fi-footer-slot="extensions"></div><div id="fiDockedAccountSlot" class="fi-docked-account-slot" data-fi-slot="account-footer"></div>`;
    container.classList.add('has-fi-docked-footer');
    const resize = container.querySelector('.bypass-resize-handle');
    if (resize) container.insertBefore(footer, resize); else container.appendChild(footer);
    const syncFooterInset = () => {
      if (!footer.isConnected || !container.isConnected) return;
      const measured = Math.max(22, Math.ceil(footer.getBoundingClientRect().height || (settings.dockedAccountFooterCollapsed ? 22 : 52)));
      container.style.setProperty('--fi-docked-footer-height', `${measured}px`);
    };
    if (typeof ResizeObserver === 'function') {
      footer._fiSizeObserver = new ResizeObserver(syncFooterInset);
      footer._fiSizeObserver.observe(footer);
    }
    requestAnimationFrame(syncFooterInset);
    footer.querySelector('.fi-docked-account-toggle').onclick = event => {
      event.preventDefault();
      event.stopPropagation();
      settings.dockedAccountFooterCollapsed = !settings.dockedAccountFooterCollapsed;
      saveSettings();
      footer.classList.toggle('is-collapsed', settings.dockedAccountFooterCollapsed);
      const button = footer.querySelector('.fi-docked-account-toggle');
      button.title = settings.dockedAccountFooterCollapsed ? 'Expand account dock' : 'Collapse account dock';
      button.setAttribute('aria-expanded', settings.dockedAccountFooterCollapsed ? 'false' : 'true');
      button.innerHTML = `<i class="fas fa-chevron-${settings.dockedAccountFooterCollapsed ? 'up' : 'down'}"></i>`;
      if (!settings.dockedAccountFooterCollapsed) updateHeaderAccountBtn();
      requestAnimationFrame(syncFooterInset);
    };
    renderFiExtensionFooterActions(footer.querySelector('#fiFooterExtensionSlot'), colors);
    updateHeaderAccountBtn(container);
  }

  function updateHeaderAccountBtn(root = document) {
    const scope = root && typeof root.querySelector === 'function' ? root : document;
    const container = scope.querySelector('#fiDockedAccountSlot, #fiAccountHeaderBtn')
      || document.getElementById('fiDockedAccountSlot')
      || document.getElementById('fiAccountHeaderBtn');
    if (!container) return;
    const cfg = getAccountSystemConfig();
    if (!cfg.enabled || !cfg.show_profile_in_header) { container.style.display = 'none'; return; }
    container.style.display = 'flex';
    container.style.alignItems = 'center';
    container.style.gap = '5px';

    if (!communityAccountToken && new URLSearchParams(location.search).get('fiCreditClaim') && !fiCreditClaimLoginPrompted) {
      fiCreditClaimLoginPrompted = true;
      setTimeout(() => { showToast('Sign in to preview and claim these FI credits.', 'info'); showFiLoginDialog(); }, 100);
    }
    if (communityAccountToken) {
      if (!fiCreditPlatformSnapshot || Date.now() - fiCreditPlatformLoadedAt > 30000) fiCreditRefresh(false).catch(() => {});
      fiCreditMaybeHandleClaimLink().catch(() => {});
      fiCreditMaybeHandleDiscordLinkReturn().catch(() => {});
      const avatar = communityAccountAvatar;
      const displayName = communityAccountUsername || communityFiUsername || 'Account';
      const primaryType = communityMyTypes?.[0];
      const typeColor = primaryType?.color || '#6366f1';
      const discord = fiCreditPlatformSnapshot?.discord || {};
      const discordIdentity = discord.identity || {};
      const discordLinked = !!discord.linked;
      const discordReady = discordLinked && !!discordIdentity.guildMember;
      const balance = fiCreditWalletValue();
      const isDockedAccount = container.id === 'fiDockedAccountSlot';
      const balanceText = fiCreditPlatformSnapshot ? (isDockedAccount ? Math.max(0, Number(balance || 0)).toLocaleString() : fiCreditFormatCompact(balance)) : (fiCreditPlatformLoading ? '...' : 'offline');
      const profileMaxWidth = isDockedAccount ? '440px' : '150px';
      const nameMaxWidth = isDockedAccount ? '330px' : '76px';
      container.innerHTML = `
        <button id="fiProfileHeaderBtn" aria-label="FreeInternet Account: ${escapeHtml(displayName)}" data-fi-chip-guidance="account" style="display:flex;align-items:center;gap:6px;padding:3px 8px 3px 4px;border-radius:999px;border:2px solid ${typeColor}44;background:${typeColor}18;cursor:pointer;transition:all .2s;font-size:11px;color:${typeColor};font-weight:750;white-space:nowrap;overflow:hidden;max-width:${profileMaxWidth};height:30px;">
          ${avatar ? `<img src="${escapeHtml(avatar)}" style="width:20px;height:20px;border-radius:50%;object-fit:cover;flex-shrink:0;" onerror="this.style.display='none'">` : `<i class="${primaryType?.icon || 'fas fa-user'}" style="font-size:11px;width:20px;height:20px;display:flex;align-items:center;justify-content:center;border-radius:50%;background:${typeColor}33;"></i>`}
          <span style="max-width:${nameMaxWidth};overflow:hidden;text-overflow:ellipsis;">${escapeHtml(displayName)}</span>
          <i class="fas fa-chevron-down" style="font-size:7px;opacity:.72;"></i>
        </button>
        <button id="fiCreditHeaderBtn" data-fi-credit-header aria-label="${escapeHtml(fiCreditPlatformSnapshot ? fiCreditExactLabel(balance) : 'FI Credits unavailable')}" data-fi-chip-guidance="credits" style="display:inline-flex;align-items:center;gap:5px;height:30px;padding:3px 9px;border-radius:999px;border:1px solid rgba(34,211,238,.34);background:linear-gradient(135deg,rgba(8,145,178,.16),rgba(79,70,229,.12));color:#a5f3fc;font-size:10px;font-weight:950;cursor:pointer;white-space:nowrap;transition:.18s ease;">
          <i class="fas fa-coins" style="font-size:9px;"></i><span>${escapeHtml(balanceText)}</span><i class="fas fa-chevron-down" style="font-size:7px;opacity:.72;"></i>
        </button>
        <button id="fiDiscordHeaderBtn" data-fi-discord-header title="${discordLinked ? (discordReady ? 'Discord connected · rewards ready' : 'Discord connected · join the FI server') : 'Connect Discord to earn FI Credits'}" style="display:inline-flex;align-items:center;justify-content:center;gap:4px;width:30px;height:30px;padding:0;border-radius:999px;border:1px solid ${discordReady ? 'rgba(52,211,153,.42)' : discordLinked ? 'rgba(251,191,36,.4)' : 'rgba(129,140,248,.38)'};background:${discordReady ? 'rgba(16,185,129,.12)' : discordLinked ? 'rgba(245,158,11,.1)' : 'rgba(88,101,242,.14)'};color:${discordReady ? '#6ee7b7' : discordLinked ? '#fcd34d' : '#a5b4fc'};cursor:pointer;position:relative;transition:.18s ease;">
          <i class="fab fa-discord" style="font-size:12px;"></i><span style="position:absolute;right:1px;bottom:1px;width:6px;height:6px;border-radius:50%;background:${discordReady ? '#34d399' : discordLinked ? '#fbbf24' : '#64748b'};box-shadow:0 0 0 2px rgba(2,6,23,.9);"></span>
        </button>`;

      const profileButton = container.querySelector('#fiProfileHeaderBtn');
      profileButton.onmouseenter = () => { profileButton.style.background = `${typeColor}30`; profileButton.style.borderColor = `${typeColor}88`; };
      profileButton.onmouseleave = () => { profileButton.style.background = `${typeColor}18`; profileButton.style.borderColor = `${typeColor}44`; };
      profileButton.onclick = event => { event.stopPropagation(); fiHeaderDismissQuickSurfaces(); showFiProfileDropdown(profileButton); };
      profileButton.oncontextmenu = event => fiShowTensorAccountQuickSwitcher(profileButton, event);
      fiHeaderBindTooltip(profileButton, () => fiHeaderTooltipMarkup('FI account', 'Your signed-in FreeInternet identity and fast Tensor account controls.', [
        { icon: 'fa-arrow-pointer', label: 'Click', value: 'Open FI account details' },
        { icon: 'fa-computer-mouse', label: 'Right-click', value: 'Switch Tensor accounts' },
      ], 'Account order, pins, aliases, and colors come from the Accounts tab.'));
      const creditButton = container.querySelector('#fiCreditHeaderBtn');
      creditButton.onmouseenter = () => { creditButton.style.transform = 'translateY(-1px)'; creditButton.style.borderColor = 'rgba(34,211,238,.65)'; };
      creditButton.onmouseleave = () => { creditButton.style.transform = ''; creditButton.style.borderColor = 'rgba(34,211,238,.34)'; };
      creditButton.onclick = event => { event.stopPropagation(); fiCreditShowQuickMenu(creditButton, 'rewards'); };
      creditButton.oncontextmenu = event => fiCreditShowContextMenu(event, creditButton);
      fiHeaderBindTooltip(creditButton, () => fiHeaderTooltipMarkup('FI Credits', 'Fast access to rewards, recent activity, purchases, and the full wallet.', [
        { icon: 'fa-arrow-pointer', label: 'Click', value: 'Open the quick wallet' },
        { icon: 'fa-computer-mouse', label: 'Right-click', value: 'Refresh, transfer, or open a section' },
      ], 'Your exact balance remains available inside the menu and full wallet.'));
      const discordButton = container.querySelector('#fiDiscordHeaderBtn');
      discordButton.onmouseenter = () => { discordButton.style.transform = 'translateY(-1px) scale(1.03)'; };
      discordButton.onmouseleave = () => { discordButton.style.transform = ''; };
      discordButton.onclick = event => { event.stopPropagation(); fiCreditOpenWallet('earn'); };
    } else {
      container.innerHTML = `<button id="fiLoginHeaderBtn" title="Sign in to FreeInternet" style="display:flex;align-items:center;gap:5px;padding:4px 11px;border-radius:999px;border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.07);cursor:pointer;font-size:11px;color:rgba(255,255,255,.7);font-weight:600;transition:all .2s;height:30px;"><i class="fas fa-user-circle" style="font-size:12px;"></i> Sign In</button>`;
      const button = container.querySelector('#fiLoginHeaderBtn');
      button.onmouseenter = () => { button.style.background = 'rgba(255,255,255,.13)'; button.style.color = '#fff'; };
      button.onmouseleave = () => { button.style.background = 'rgba(255,255,255,.07)'; button.style.color = 'rgba(255,255,255,.7)'; };
      button.onclick = event => { event.stopPropagation(); showFiLoginDialog(); };
    }
  }
  function showFiProfileDropdown(anchorEl) {
    fiHeaderDismissQuickSurfaces();
    document.getElementById('fiProfileDropdown')?.remove();
    const rect = anchorEl.getBoundingClientRect();
    const colors = getThemeColors();
    const menuWidth = 244;
    const dropLeft = Math.max(8, Math.min(rect.left, window.innerWidth - menuWidth - 8));
    const shouldOpenUp = (window.innerHeight - rect.bottom < 330) && rect.top > 330;
    const drop = document.createElement('div');
    drop.id = 'fiProfileDropdown';
    drop.style.cssText = `position:fixed;${shouldOpenUp ? `bottom:${Math.max(8, window.innerHeight - rect.top + 6)}px` : `top:${rect.bottom + 6}px`};left:${dropLeft}px;z-index:2147483647;\n      background:${colors.bg};border:1px solid ${colors.border};border-radius:12px;padding:6px;\n      box-shadow:0 8px 32px rgba(0,0,0,0.4);width:${menuWidth}px;max-width:calc(100vw - 16px);max-height:min(520px,calc(100vh - 24px));overflow:auto;`;

    const primaryType = communityMyTypes?.[0];
    const typeColor = primaryType?.color || '#6366f1';

    const headerHtml = `
      <div style="padding:8px 10px 10px;border-bottom:1px solid ${colors.border};margin-bottom:5px;">
        <div style="font-size:12px;font-weight:800;color:${colors.text};display:flex;align-items:center;gap:6px;">
          ${communityAccountAvatar
            ? `<img src="${escapeHtml(communityAccountAvatar)}" style="width:28px;height:28px;border-radius:50%;object-fit:cover;">`
            : `<i class="${primaryType?.icon || 'fas fa-user'}" style="color:${typeColor};font-size:16px;"></i>`}
          <div>
            <div>${escapeHtml(communityAccountUsername || 'Account')}</div>
            ${communityFiUsername ? `<div style="font-size:9px;color:${colors.textSecondary};font-weight:500;">@${escapeHtml(communityFiUsername)}</div>` : ''}
          </div>
        </div>
        ${communityMyTypes?.length ? `<div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:6px;">
          ${communityMyTypes.map(t => `<span style="font-size:9px;padding:2px 7px;border-radius:999px;background:${t.color}22;color:${t.color};border:1px solid ${t.color}44;">
            <i class="${t.icon}" style="font-size:8px;"></i> ${escapeHtml(t.label)}</span>`).join('')}
        </div>` : ''}
        <button data-wallet-open="overview" style="display:flex;align-items:center;justify-content:space-between;width:100%;margin-top:8px;padding:8px 10px;border-radius:9px;border:1px solid rgba(34,211,238,.28);background:rgba(34,211,238,.08);color:#67e8f9;cursor:pointer;font-size:11px;font-weight:900;"><span><i class="fas fa-coins" style="margin-right:6px;"></i>FI Credits</span><span title="${escapeHtml(fiCreditPlatformSnapshot ? fiCreditExactLabel(fiCreditWalletValue()) : 'FI Credits loading')}">${fiCreditPlatformSnapshot ? fiCreditFormatCompact(fiCreditWalletValue()) : 'Loading…'}</span></button>
      </div>`;

    drop.innerHTML = headerHtml + `
      <button class="fi-drop-item" data-act="profile">
        <i class="fas fa-user" style="width:14px;text-align:center;"></i> View Profile
      </button>
      <button class="fi-drop-item" data-act="settings">
        <i class="fas fa-cog" style="width:14px;text-align:center;"></i> Account Settings
      </button>
      <button class="fi-drop-item" data-act="earn"><i class="fab fa-discord" style="width:14px;text-align:center;color:#818cf8;"></i> ${fiCreditPlatformSnapshot?.discord?.linked ? 'Discord rewards' : 'Connect Discord'}</button>
      <button class="fi-drop-item" data-act="transfer"><i class="fas fa-arrow-right-arrow-left" style="width:14px;text-align:center;"></i> Transfer credits</button>
      <button class="fi-drop-item" data-act="purchases"><i class="fas fa-bag-shopping" style="width:14px;text-align:center;"></i> Purchases</button>
      ${!communityFiUsername ? `<button class="fi-drop-item" data-act="setpassword">
        <i class="fas fa-key" style="width:14px;text-align:center;"></i> Set FI Password
      </button>` : ''}
      <div style="height:1px;background:${colors.border};margin:5px 0;"></div>
      <button class="fi-drop-item" data-act="logout" style="color:#f87171;">
        <i class="fas fa-sign-out-alt" style="width:14px;text-align:center;"></i> Sign Out
      </button>`;

    // Common item style
    drop.querySelectorAll('.fi-drop-item').forEach(btn => {
      btn.style.cssText = `display:flex;align-items:center;gap:8px;width:100%;padding:8px 10px;border-radius:8px;
        border:none;background:transparent;cursor:pointer;font-size:12px;color:${btn.dataset.act === 'logout' ? '#f87171' : colors.text};
        text-align:left;transition:background 0.12s;`;
      btn.onmouseenter = () => { btn.style.background = colors.bgSecondary; };
      btn.onmouseleave = () => { btn.style.background = 'transparent'; };
    });

    drop.querySelector('[data-act="profile"]').onclick = () => {
      drop.remove();
      // Open community tab → show account profile in prompts subtab
      isExpanded = true; currentTab = 'community'; updateUI();
    };
    drop.querySelector('[data-act="settings"]').onclick = () => {
      drop.remove();
      showFiAccountSettingsDialog();
    };
    drop.querySelector('[data-wallet-open]')?.addEventListener('click', () => { drop.remove(); fiCreditOpenWallet('overview'); });
    drop.querySelector('[data-act="earn"]')?.addEventListener('click', () => { drop.remove(); fiCreditOpenWallet('earn'); });
    drop.querySelector('[data-act="transfer"]')?.addEventListener('click', () => { drop.remove(); fiCreditOpenWallet('transfer'); });
    drop.querySelector('[data-act="purchases"]')?.addEventListener('click', () => { drop.remove(); fiCreditOpenWallet('purchases'); });
    drop.querySelector('[data-act="setpassword"]')?.addEventListener('click', () => {
      drop.remove();
      showFiPasswordSetupDialog();
    });
    drop.querySelector('[data-act="logout"]').onclick = () => {
      drop.remove();
      showConfirmDialog('Sign out of your FreeInternet account?', () => fiLogout());
    };

    document.body.appendChild(drop);
    const dismiss = (e) => { if (!drop.contains(e.target) && e.target !== anchorEl) { drop.remove(); document.removeEventListener('click', dismiss, true); } };
    setTimeout(() => document.addEventListener('click', dismiss, true), 50);
  }

  /**
   * Show the main login / register dialog.
   */
  function showFiLoginDialog() {
    // If already logged in to FI, skip the dialog entirely
    if (communityAccountToken && communityAccountId) {
      updateHeaderAccountBtn(); // ensure button shows logged-in state
      showToast('Already signed in as ' + (communityAccountUsername || 'Account'), 'info');
      return;
    }
    // Try auto-login via linked tensor accounts before showing dialog
    communityTryAutoLogin().then(restored => {
      if (restored) {
        showToast('Signed in as ' + (communityAccountUsername || 'Account'), 'success');
        return;
      }
      _showFiLoginDialogInner();
    }).catch(() => { _showFiLoginDialogInner(); });
  }

  function _showFiLoginDialogInner() {
    const cfg    = getAccountSystemConfig();
    const colors = getThemeColors();
    document.getElementById('fiLoginDialogOverlay')?.remove();

    const overlay = document.createElement('div');
    overlay.id = 'fiLoginDialogOverlay';
    overlay.style.cssText = `position:fixed;inset:0;background:rgba(0,0,0,0.65);z-index:2147483647;display:flex;align-items:center;justify-content:center;`;

    const box = document.createElement('div');
    box.style.cssText = `background:${colors.bg};border:1px solid ${colors.border};border-radius:18px;padding:26px 24px 20px;
      max-width:420px;width:93%;box-shadow:0 12px 60px rgba(0,0,0,0.5);position:relative;`;

    // Three views: 'tensor' | 'fi' | 'register'
    let view = cfg.allow_tensor_login !== false ? 'tensor' : 'fi';

    function renderView() {
      const tabs = [];
      if (cfg.allow_tensor_login !== false)         tabs.push({ id:'tensor',   icon:'fas fa-robot',    label:'Tensor Login' });
      if (cfg.allow_fi_password !== false)           tabs.push({ id:'fi',       icon:'fas fa-lock',     label:'FI Password' });
      tabs.push({                                                 id:'register', icon:'fas fa-user-plus', label:'Register' });

      box.innerHTML = `
        <button id="fi-dialog-close" style="position:absolute;top:12px;right:14px;background:none;border:none;color:${colors.textSecondary};font-size:16px;cursor:pointer;padding:4px;border-radius:6px;"><i class="fas fa-times"></i></button>
        <div style="text-align:center;margin-bottom:18px;">
          <div style="font-size:18px;font-weight:900;color:${colors.text};">${escapeHtml(cfg.login_dialog_header_text || 'FreeInternet Account')}</div>
          <div style="font-size:11px;color:${colors.textSecondary};margin-top:4px;line-height:1.5;">${escapeHtml(cfg.login_dialog_subtext || 'Sign in to unlock account features.')}</div>
        </div>
        <div style="display:flex;gap:6px;margin-bottom:18px;background:${colors.bgSecondary};border-radius:10px;padding:4px;">
          ${tabs.map(t => `<button data-tab="${t.id}" style="flex:1;padding:7px 4px;border-radius:7px;border:none;cursor:pointer;font-size:11px;font-weight:700;transition:all 0.18s;
            background:${view === t.id ? colors.bg : 'transparent'};color:${view === t.id ? colors.text : colors.textSecondary};
            box-shadow:${view === t.id ? '0 1px 4px rgba(0,0,0,0.2)' : 'none'};">
            <i class="${t.icon}" style="margin-right:4px;"></i>${t.label}</button>`).join('')}
        </div>
        <div id="fi-dialog-body"></div>
        <div id="fi-dialog-status" style="min-height:18px;font-size:11px;text-align:center;margin-top:10px;color:#f87171;"></div>`;

      box.querySelector('#fi-dialog-close').onclick = () => { _fiCancelBrowserLogin(); overlay.remove(); };
      box.querySelectorAll('[data-tab]').forEach(tb => {
        tb.onclick = () => { _fiCancelBrowserLogin(); view = tb.dataset.tab; renderView(); };
      });

      const body = box.querySelector('#fi-dialog-body');
      const status = box.querySelector('#fi-dialog-status');
      const setStatus = (msg, isErr = true) => { status.style.color = isErr ? '#f87171' : '#4ade80'; status.textContent = msg; };

      if (view === 'tensor') {
        body.innerHTML = `<div style="font-size:12px;color:${colors.textSecondary};margin-bottom:14px;line-height:1.6;">
          Connect your FreeInternet account using your Tensor profile. Your Tensor login is used for identity verification.</div>
          <button id="fi-tensor-btn" style="width:100%;padding:11px;border-radius:10px;border:none;background:#6366f1;color:#fff;font-size:13px;font-weight:800;cursor:pointer;transition:opacity 0.2s;">
            <i class="fas fa-robot" style="margin-right:8px;"></i>Continue with Tensor Account</button>`;
        body.querySelector('#fi-tensor-btn').onclick = async () => {
          const btn = body.querySelector('#fi-tensor-btn');
          btn.disabled = true; btn.style.opacity = '0.6';
          try {
            const acct = await communityRegisterOrLogin();
            if (acct) {
              overlay.remove();
              showToast('Signed in as ' + (communityAccountUsername || 'Account'), 'success');
            } else {
              setStatus('Could not sign in. Make sure you are logged in to Tensor on this page.');
            }
          } catch (e) {
            setStatus(e.message || 'Registration failed');
          } finally {
            btn.disabled = false; btn.style.opacity = '1';
          }
        };
      } else if (view === 'fi') {
        body.innerHTML = `<div style="display:flex;flex-direction:column;gap:10px;">
          <div><label style="font-size:10px;font-weight:700;color:${colors.textSecondary};text-transform:uppercase;letter-spacing:0.5px;">FI Username</label>
            <input id="fi-login-user" type="text" autocomplete="username" placeholder="your_username"
              style="width:100%;box-sizing:border-box;background:${colors.bgSecondary};border:1px solid ${colors.border};border-radius:8px;
                     color:${colors.text};font-size:12px;padding:9px 10px;outline:none;margin-top:4px;"></div>
          <div><label style="font-size:10px;font-weight:700;color:${colors.textSecondary};text-transform:uppercase;letter-spacing:0.5px;">Password</label>
            <input id="fi-login-pass" type="password" autocomplete="current-password" placeholder="••••••••"
              style="width:100%;box-sizing:border-box;background:${colors.bgSecondary};border:1px solid ${colors.border};border-radius:8px;
                     color:${colors.text};font-size:12px;padding:9px 10px;outline:none;margin-top:4px;"></div>
          <button id="fi-login-btn" style="width:100%;padding:10px;border-radius:9px;border:none;background:#6366f1;color:#fff;font-size:13px;font-weight:800;cursor:pointer;transition:opacity 0.2s;margin-top:2px;">
            <i class="fas fa-sign-in-alt" style="margin-right:6px;"></i>Sign In</button>
        </div>`;
        const loginBtn = body.querySelector('#fi-login-btn');
        loginBtn.onclick = async () => {
          const fiUser = body.querySelector('#fi-login-user').value.trim();
          let fiPass = body.querySelector('#fi-login-pass').value;
          if (!fiUser || !fiPass) { setStatus('Enter your username and password'); return; }
          loginBtn.disabled = true; loginBtn.style.opacity = '0.6';
          try {
            const attempt = _fiBeginBrowserLogin(true);
            const pending = communityApiCall('account_login_fi', { fiUsername: fiUser, password: fiPass, ...attempt.fields });
            fiPass = ''; body.querySelector('#fi-login-pass').value = '';
            const result = await _fiCompleteBrowserLogin(await pending, attempt);
            if (result?.ok) {
              communityAccountToken    = result.data.token;
              communityAccountId       = result.data.accountId;
              communityAccountUsername = result.data.username;
              communityAccountAvatar   = result.data.avatarUrl || null;
              communityFiUsername      = result.data.fiUsername || null;
              communityHasPassword     = true;
              persistAccountState();
              await fiLoadProfile();
              communityLinkAllTensorAccounts().catch(() => {});
              checkAndShowPendingAgreements().catch(() => {});
              overlay.remove();
              showToast('Welcome back, ' + (communityAccountUsername || 'Account') + '!', 'success');
            } else {
              setStatus(result?.error === 'banned' ? (getAccountSystemConfig().ban_message || 'Account suspended') : (result?.error || 'Login failed'));
            }
          } catch (e) {
            setStatus(e.message || 'Login failed');
          } finally {
            loginBtn.disabled = false; loginBtn.style.opacity = '1';
          }
        };
      } else {
        // register
        body.innerHTML = `<div style="font-size:12px;color:${colors.textSecondary};margin-bottom:12px;line-height:1.5;">
          Create a FreeInternet account using your Tensor identity. This allows you to share prompts, track usage, and earn type badges.</div>
          <button id="fi-reg-tensor-btn" style="width:100%;padding:11px;border-radius:10px;border:none;background:#6366f1;color:#fff;font-size:13px;font-weight:800;cursor:pointer;transition:opacity 0.2s;margin-bottom:8px;">
            <i class="fas fa-user-plus" style="margin-right:8px;"></i>Register with Tensor Account</button>
          <div style="text-align:center;font-size:10px;color:${colors.textSecondary};opacity:0.7;">You can also set an FI username & password after registering.</div>`;
        body.querySelector('#fi-reg-tensor-btn').onclick = async () => {
          const btn = body.querySelector('#fi-reg-tensor-btn');
          btn.disabled = true; btn.style.opacity = '0.6';
          try {
            const acct = await communityRegisterOrLogin();
            if (acct) {
              overlay.remove();
              showToast('Account created! Welcome, ' + (communityAccountUsername || 'Account'), 'success');
            } else {
              setStatus('Registration failed. Are you logged in to Tensor?');
            }
          } catch (e) {
            setStatus(e.message || 'Registration failed');
          } finally {
            btn.disabled = false; btn.style.opacity = '1';
          }
        };
      }
    }

    renderView();
    overlay.appendChild(box);
    document.body.appendChild(overlay);
    overlay.addEventListener('click', e => { if (e.target === overlay) { _fiCancelBrowserLogin(); overlay.remove(); } });
  }

  /**
   * Show the optional password setup dialog (after tensor registration).
   */
  function showFiPasswordSetupDialog(onDone, options = {}) {
    const colors = getThemeColors();
    const initialUsername = String(options?.initialUsername || communityFiUsername || '').trim().slice(0, 30);
    const changingExisting = !!communityHasPassword;
    document.getElementById('fiPassSetupOverlay')?.remove();
    const overlay = document.createElement('div');
    overlay.id = 'fiPassSetupOverlay';
    overlay.style.cssText = `position:fixed;inset:0;background:rgba(0,0,0,0.65);z-index:2147483647;display:flex;align-items:center;justify-content:center;`;
    const box = document.createElement('div');
    box.style.cssText = `background:${colors.bg};border:1px solid ${colors.border};border-radius:16px;padding:24px;max-width:400px;width:93%;box-shadow:0 10px 50px rgba(0,0,0,0.4);`;
    box.innerHTML = `
      <div style="font-size:16px;font-weight:900;color:${colors.text};margin-bottom:6px;"><i class="fas fa-key" style="color:#6366f1;margin-right:8px;"></i>${changingExisting ? 'Update FI Credentials' : 'Set a FI Password'}</div>
      <div style="font-size:11px;color:${colors.textSecondary};margin-bottom:16px;line-height:1.6;">
        ${changingExisting ? 'Enter your current FI password to change the username or password. This value stays inside the signed-in browser dialog.' : 'Optionally set a FreeInternet username and password so you can log in without Tensor. You can skip this and do it later in Account Settings.'}</div>
      <div style="display:flex;flex-direction:column;gap:10px;">
        <div><label style="font-size:10px;font-weight:700;color:${colors.textSecondary};text-transform:uppercase;">FI Username (optional)</label>
          <input id="fi-setup-user" type="text" placeholder="choose_username" autocomplete="username"
            style="width:100%;box-sizing:border-box;background:${colors.bgSecondary};border:1px solid ${colors.border};border-radius:8px;color:${colors.text};font-size:12px;padding:9px 10px;outline:none;margin-top:4px;"></div>
        ${changingExisting ? `<div><label style="font-size:10px;font-weight:700;color:${colors.textSecondary};text-transform:uppercase;">Current password (required for changes)</label>
          <input id="fi-setup-current-pass" type="password" autocomplete="current-password"
            style="width:100%;box-sizing:border-box;background:${colors.bgSecondary};border:1px solid ${colors.border};border-radius:8px;color:${colors.text};font-size:12px;padding:9px 10px;outline:none;margin-top:4px;"></div>` : ''}
        <div><label style="font-size:10px;font-weight:700;color:${colors.textSecondary};text-transform:uppercase;">${changingExisting ? 'New password (optional)' : 'Password (optional)'}</label>
          <input id="fi-setup-pass" type="password" placeholder="min 8 characters" autocomplete="new-password"
            style="width:100%;box-sizing:border-box;background:${colors.bgSecondary};border:1px solid ${colors.border};border-radius:8px;color:${colors.text};font-size:12px;padding:9px 10px;outline:none;margin-top:4px;"></div>
      </div>
      <div id="fi-setup-status" style="min-height:16px;font-size:11px;color:#f87171;margin-top:8px;"></div>
      <div style="display:flex;gap:8px;margin-top:14px;justify-content:flex-end;">
        <button id="fi-setup-skip" style="padding:8px 16px;border-radius:9px;border:1px solid ${colors.border};background:transparent;color:${colors.textSecondary};font-size:12px;cursor:pointer;">Skip for Now</button>
        <button id="fi-setup-save" style="padding:8px 18px;border-radius:9px;border:none;background:#6366f1;color:#fff;font-size:12px;font-weight:800;cursor:pointer;">Save</button>
      </div>`;

    const statusEl = box.querySelector('#fi-setup-status');
    box.querySelector('#fi-setup-user').value = initialUsername;
    box.querySelector('#fi-setup-skip').onclick = () => { overlay.remove(); onDone?.(); };
    box.querySelector('#fi-setup-save').onclick = async () => {
      const fiUser = box.querySelector('#fi-setup-user').value.trim();
      const fiPass = box.querySelector('#fi-setup-pass').value;
      const currentPassword = box.querySelector('#fi-setup-current-pass')?.value || '';
      if (!fiUser && !fiPass) { overlay.remove(); onDone?.(); return; }
      if (fiPass && fiPass.length < 8) { statusEl.textContent = 'Password must be at least 8 characters'; return; }
      if (changingExisting && !currentPassword) { statusEl.textContent = 'Enter your current FI password to change account credentials'; return; }
      const saveBtn = box.querySelector('#fi-setup-save');
      saveBtn.disabled = true; saveBtn.style.opacity = '0.6';
      try {
        const result = await communityApiCall('account_set_password', { token: communityAccountToken, fiUsername: fiUser, password: fiPass, ...(changingExisting ? { currentPassword } : {}) });
        if (result?.ok) {
          communityFiUsername = result.fiUsername || fiUser || null;
          communityHasPassword = result.hasPassword === true || communityHasPassword || !!fiPass;
          persistAccountState();
          updateHeaderAccountBtn();
          overlay.remove();
          showToast('FI credentials saved!', 'success');
          onDone?.({ ok: true, fiUsername: communityFiUsername, hasPassword: communityHasPassword });
        } else {
          statusEl.textContent = result?.error || 'Failed to save credentials';
        }
      } catch (e) {
        statusEl.textContent = e.message || 'Error saving credentials';
      } finally {
        saveBtn.disabled = false; saveBtn.style.opacity = '1';
      }
    };
    overlay.appendChild(box);
    document.body.appendChild(overlay);
    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  }

  /**
   * Show the type upgrade/badge notification modal.
   */
  function showFiUpgradeNotification(notif) {
    if (!notif) return;
    const colors = getThemeColors();
    const typeColor = notif.typeColor || '#6366f1';
    const icon  = notif.typeIconUrl
      ? `<img src="${escapeHtml(notif.typeIconUrl)}" style="width:48px;height:48px;border-radius:50%;object-fit:cover;">`
      : `<i class="${escapeHtml(notif.typeIcon || 'fas fa-id-badge')}" style="font-size:32px;color:${typeColor};"></i>`;

    const overlay = document.createElement('div');
    overlay.style.cssText = `position:fixed;inset:0;background:rgba(0,0,0,0.65);z-index:2147483647;display:flex;align-items:center;justify-content:center;`;
    const box = document.createElement('div');
    box.style.cssText = `background:${colors.bg};border:2px solid ${typeColor}55;border-radius:18px;padding:28px 24px;max-width:360px;width:92%;
      box-shadow:0 0 40px ${typeColor}33, 0 12px 60px rgba(0,0,0,0.5);text-align:center;`;
    box.innerHTML = `
      <div style="width:72px;height:72px;border-radius:50%;background:${typeColor}22;border:2px solid ${typeColor}55;display:flex;align-items:center;justify-content:center;margin:0 auto 14px;">${icon}</div>
      <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:1px;color:${typeColor};margin-bottom:4px;">
        ${notif.action === 'promoted' ? '<i class="fas fa-champagne-glasses"></i> You were promoted!' : notif.action === 'demoted' ? 'Account Type Updated' : 'Account Update'}</div>
      <div style="font-size:20px;font-weight:900;color:${colors.text};margin-bottom:10px;">
        <span style="color:${typeColor};">${escapeHtml(notif.typeLabel || notif.typeId || 'New Role')}</span>
      </div>
      ${notif.message ? `<div style="font-size:12px;color:${colors.textSecondary};line-height:1.6;margin-bottom:16px;">${escapeHtml(notif.message)}</div>` : ''}
      <button id="fi-upgrade-dismiss" style="padding:10px 28px;border-radius:10px;border:none;background:${typeColor};color:#fff;font-size:13px;font-weight:800;cursor:pointer;">
        Awesome!</button>`;
    box.querySelector('#fi-upgrade-dismiss').onclick = async () => {
      overlay.remove();
      communityPendingUpgrade = null;
      if (communityAccountToken && notif.id) {
        try { await communityApiCall('dismiss_upgrade_notification', { token: communityAccountToken, notifId: notif.id }); } catch (_) {}
      }
      updateHeaderAccountBtn();
    };
    overlay.appendChild(box);
    document.body.appendChild(overlay);
    overlay.addEventListener('click', e => { if (e.target === overlay) { overlay.remove(); } });
  }


  // ══════════════════════════════════════════════════════════════════════════
  //  FREEINTERNET CHAT  State & Core
  function _fiMountAccountSecurity(parent,colors) {
    const identity=communityAccountToken,section=document.createElement('section');parent.appendChild(section);
    section.style.cssText=`display:grid;gap:10px;margin-top:14px;padding:14px;border:1px solid ${colors.border};border-radius:14px;background:${colors.bgSecondary};color:${colors.text};`;
    const add=(tag,text)=>{const node=document.createElement(tag);node.textContent=text||'';section.appendChild(node);return node;};
    add('strong','Profile and Discord sign-in verification');
    add('small','Connect the official FI-Prompter extension to the same FI account to manage your shared profile and verification. Codes are sent only when you choose Send code.');
    const status=add('div','');status.setAttribute('role','status');const controls=add('div','');controls.style.cssText='display:grid;gap:9px;';
    let closed=false,busy=false,challenge=null,security=null,observer=null;
    const valid=()=>!closed&&section.isConnected&&communityAccountToken===identity;
    const clear=()=>{closed=true;challenge=null;controls.replaceChildren();observer?.disconnect();_extEventBus.get('community:profile')?.delete(changed);};
    const changed=()=>{if(communityAccountToken!==identity){clear();status.textContent='Your FI account changed. Reopen Account Settings.';}};
    if(!_extEventBus.has('community:profile'))_extEventBus.set('community:profile',new Set());_extEventBus.get('community:profile').add(changed);
    if(typeof MutationObserver!=='undefined'){observer=new MutationObserver(()=>{if(!section.isConnected)clear();});observer.observe(document.body,{childList:true,subtree:true});}
    const request=async payload=>{if(!valid())throw new Error('Your FI account changed.');const result=await _fiPrompterCommunityRequest(payload);if(!valid())throw new Error('Your FI account changed.');return result;};
    const field=(label,value='',type='text')=>{const wrap=document.createElement('label');wrap.textContent=label;const input=document.createElement('input');input.value=value;input.type=type;input.maxLength=type==='password'?128:100;input.style.cssText=`box-sizing:border-box;width:100%;margin-top:5px;padding:10px;border:1px solid ${colors.border};border-radius:8px;background:${colors.bg};color:${colors.text};`;wrap.appendChild(input);controls.appendChild(wrap);return input;};
    const button=(label,handler,parent=controls)=>{const node=document.createElement('button');node.type='button';node.textContent=label;node.style.cssText=`padding:9px 12px;border:1px solid ${colors.border};border-radius:9px;background:${colors.bg};color:${colors.text};cursor:pointer;`;parent.appendChild(node);node.onclick=async()=>{if(busy||!valid())return;busy=true;node.disabled=true;status.textContent='Working...';try{await handler();}catch(error){if(valid())status.textContent=String(error?.message||'Account request failed.').slice(0,240);}finally{busy=false;node.disabled=false;}};return node;};
    const render=(account,nextSecurity)=>{
      security=nextSecurity;challenge=null;controls.replaceChildren();
      const name=field('Display name',String(account?.displayName||account?.username||communityAccountUsername||''));
      button('Save display name',async()=>{const displayName=name.value.trim();if(!displayName||displayName.length>100)throw new Error('Enter a display name of 1-100 characters.');const result=await request({action:'account.profile.update',displayName});communityAccountUsername=String(result.account?.displayName||result.account?.username||displayName);account={...account,displayName:communityAccountUsername};persistAccountState();updateHeaderAccountBtn();status.textContent='Display name saved.';});
      const label=document.createElement('p');label.textContent=security.twoFactorEnabled?'Discord sign-in verification is enabled.':'Discord sign-in verification is disabled.';controls.appendChild(label);
      if(!security.linked){button('Connect Discord',()=>fiCreditOpenWallet('earn'));status.textContent='Link Discord first, then reload these controls.';return;}
      const password=field('Current FI password (if configured)','','password');password.autocomplete='current-password';
      const purpose=security.twoFactorEnabled?'disable':'setup';
      button(purpose==='setup'?'Send code to enable verification':'Send code to disable verification',async()=>{let currentPassword=password.value;password.value='';const pending=request({action:'security.2fa.begin',purpose,currentPassword});currentPassword='';const result=await pending;const expiry=Date.parse(String(result.expiresAt||''));if(!/^[A-Za-z0-9_-]{8,200}$/.test(String(result.challengeId||''))||!Number.isFinite(expiry)||expiry<=Date.now())throw new Error('The verification request expired. Send a new code.');challenge={id:result.challengeId,expiresAt:expiry,purpose};code.value='';status.textContent='Code sent to Discord. Enter it below'+(purpose==='disable'?' and re-enter your current FI password.':'.');});
      const code=field('Discord verification code');code.maxLength=6;code.inputMode='numeric';code.autocomplete='one-time-code';
      button(purpose==='setup'?'Confirm enable verification':'Confirm disable verification',async()=>{if(!challenge||challenge.purpose!==purpose||Date.now()>=challenge.expiresAt||!/^\d{6}$/.test(code.value))throw new Error('Request a current code, then enter its six digits.');let value=code.value,currentPassword=password.value;code.value='';password.value='';const pending=request({action:purpose==='setup'?'security.2fa.confirm':'security.2fa.disable',challengeId:challenge.id,code:value,...(purpose==='disable'?{currentPassword}:{})});value='';currentPassword='';const next=await pending;render(account,next);status.textContent=next.twoFactorEnabled?'Discord sign-in verification enabled.':'Discord sign-in verification disabled.';});
      status.textContent='Shared account settings loaded.';
    };
    button('Load profile and verification',async()=>{const [profile,security]=await Promise.all([request({action:'account.profile'}),request({action:'security.status'})]);render(profile.account,security);},section);
    return {clear};
  }

  function showFiAccountSettingsDialog() {
    const colors = getThemeColors();
    document.getElementById('fiAcctSettingsOverlay')?.remove();
    const overlay = document.createElement('div');
    overlay.id = 'fiAcctSettingsOverlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(2,6,23,.82);z-index:2147483647;display:flex;align-items:center;justify-content:center;padding:14px;backdrop-filter:blur(12px);';
    const box = document.createElement('div');
    box.style.cssText = `background:${colors.bg};border:1px solid rgba(99,102,241,.32);border-radius:20px;padding:20px;max-width:720px;width:100%;max-height:92vh;overflow-y:auto;box-shadow:0 28px 90px rgba(0,0,0,.65);`;

    const privacyDefaults = remoteConfig?.configuration?.account_system?.privacy_defaults || { analyze_tasks: true, send_error_crashes: true };
    const privacy = communityPrivacySettings || {
      analyzeTasks: privacyDefaults.analyze_tasks !== false,
      sendErrorCrashes: privacyDefaults.send_error_crashes !== false,
      allowRecognition: privacyDefaults.allow_recognition !== false,
      allowProfileOrganized: privacyDefaults.allow_profile_organized !== false,
    };

    const accountDiscord = fiCreditPlatformSnapshot?.discord || {};
    const accountDiscordIdentity = accountDiscord.identity || {};
    const accountDiscordLinked = !!accountDiscord.linked;
    const accountDiscordReady = accountDiscordLinked && !!accountDiscordIdentity.guildMember;

    box.innerHTML = `
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;">
        <div style="font-size:16px;font-weight:900;color:${colors.text};"><i class="fas fa-cog" style="color:#6366f1;margin-right:8px;"></i>Account Settings</div>
        <button id="fi-acct-close" style="background:none;border:none;color:${colors.textSecondary};font-size:16px;cursor:pointer;padding:4px;"><i class="fas fa-times"></i></button>
      </div>
      <div class="fi-acct-tabs" style="display:flex;gap:5px;padding:5px;border:1px solid ${colors.border};border-radius:12px;margin-bottom:16px;overflow-x:auto;background:${colors.bgSecondary};">
        <button class="fi-acct-tab" data-fi-tab="account" style="flex:1;padding:8px 10px;background:rgba(99,102,241,.16);border:1px solid rgba(99,102,241,.3);border-radius:8px;color:#a5b4fc;font-size:10px;font-weight:800;cursor:pointer;white-space:nowrap;"><i class="fas fa-user" style="margin-right:5px;"></i>Account</button>
        <button class="fi-acct-tab" data-fi-tab="discord" style="flex:1;padding:8px 10px;background:transparent;border:1px solid transparent;border-radius:8px;color:${colors.textSecondary};font-size:10px;font-weight:700;cursor:pointer;white-space:nowrap;"><i class="fab fa-discord" style="margin-right:5px;"></i>Discord</button>
        <button class="fi-acct-tab" data-fi-tab="privacy" style="flex:1;padding:8px 10px;background:transparent;border:1px solid transparent;border-radius:8px;color:${colors.textSecondary};font-size:10px;font-weight:700;cursor:pointer;white-space:nowrap;"><i class="fas fa-shield-halved" style="margin-right:5px;"></i>Privacy</button>
        <button class="fi-acct-tab" data-fi-tab="host" style="flex:1;padding:8px 10px;background:transparent;border:1px solid transparent;border-radius:8px;color:${colors.textSecondary};font-size:10px;font-weight:700;cursor:pointer;white-space:nowrap;"><i class="fas fa-server" style="margin-right:5px;"></i>FI Host</button>
      </div>
      <div id="fi-tab-account">
        <section style="padding:16px;border:1px solid ${colors.border};border-radius:15px;background:radial-gradient(circle at 90% 0,rgba(34,211,238,.13),transparent 34%),${colors.bgSecondary};">
          <div style="display:flex;align-items:center;gap:12px;">
            ${communityAccountAvatar ? `<img src="${escapeHtml(communityAccountAvatar)}" style="width:46px;height:46px;border-radius:15px;object-fit:cover;border:1px solid ${colors.border};">` : `<div style="width:46px;height:46px;border-radius:15px;display:grid;place-items:center;background:rgba(99,102,241,.14);color:#a5b4fc;font-size:17px;"><i class="fas fa-user"></i></div>`}
            <div style="min-width:0;flex:1;"><div style="font-size:14px;font-weight:900;color:${colors.text};overflow:hidden;text-overflow:ellipsis;">${escapeHtml(communityAccountUsername || 'FI Account')}</div><div style="margin-top:3px;font-size:10px;color:${colors.textSecondary};">${communityFiUsername ? '@' + escapeHtml(communityFiUsername) : 'FI credentials not configured'}</div></div>
            <span style="padding:5px 8px;border-radius:999px;border:1px solid rgba(52,211,153,.26);background:rgba(16,185,129,.08);color:#86efac;font-size:9px;font-weight:850;"><i class="fas fa-circle-check" style="margin-right:4px;"></i>Signed in</span>
          </div>
        </section>
        <div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:10px;">
          <button id="fi-acct-open-wallet" style="display:flex;align-items:center;gap:11px;padding:14px;border:1px solid rgba(34,211,238,.26);border-radius:14px;background:linear-gradient(135deg,rgba(8,145,178,.12),rgba(79,70,229,.08));color:${colors.text};text-align:left;cursor:pointer;"><span style="width:36px;height:36px;display:grid;place-items:center;border-radius:11px;background:rgba(34,211,238,.12);color:#67e8f9;"><i class="fas fa-coins"></i></span><span style="min-width:0;flex:1;"><small style="display:block;color:${colors.textSecondary};font-size:8px;text-transform:uppercase;letter-spacing:.7px;">FI Credits</small><strong data-fi-acct-balance title="${escapeHtml(fiCreditExactLabel(fiCreditWalletValue()))}" style="display:block;margin-top:2px;font-size:17px;color:#a5f3fc;">${escapeHtml(fiCreditPlatformSnapshot ? fiCreditFormatCompact(fiCreditWalletValue()) : 'Loading…')}</strong></span><i class="fas fa-chevron-right" style="font-size:8px;color:#64748b;"></i></button>
          <button id="fi-acct-open-discord" style="display:flex;align-items:center;gap:11px;padding:14px;border:1px solid rgba(129,140,248,.25);border-radius:14px;background:rgba(88,101,242,.08);color:${colors.text};text-align:left;cursor:pointer;"><span style="width:36px;height:36px;display:grid;place-items:center;border-radius:11px;background:rgba(88,101,242,.15);color:#a5b4fc;"><i class="fab fa-discord"></i></span><span style="min-width:0;flex:1;"><small style="display:block;color:${colors.textSecondary};font-size:8px;text-transform:uppercase;letter-spacing:.7px;">Discord</small><strong data-fi-acct-discord style="display:block;margin-top:2px;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${accountDiscordLinked ? (accountDiscordReady ? 'Connected · rewards ready' : 'Connected · join server') : 'Connect to earn'}</strong></span><i class="fas fa-chevron-right" style="font-size:8px;color:#64748b;"></i></button>
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;">${communityAccountToken ? `<button id="fi-acct-setpass" style="padding:8px 12px;border-radius:9px;border:1px solid ${colors.border};background:${colors.bgSecondary};color:${colors.text};font-size:10px;cursor:pointer;font-weight:750;"><i class="fas fa-key" style="margin-right:5px;"></i>${communityFiUsername ? 'Change FI credentials' : 'Set FI password'}</button>` : ''}<button id="fi-acct-view-profile" style="padding:8px 12px;border-radius:9px;border:1px solid ${colors.border};background:transparent;color:${colors.textSecondary};font-size:10px;cursor:pointer;font-weight:700;"><i class="fas fa-address-card" style="margin-right:5px;"></i>View community profile</button></div>
      </div>
      <div id="fi-tab-discord" style="display:none;">
        <section style="padding:18px;border:1px solid rgba(88,101,242,.32);border-radius:15px;background:radial-gradient(circle at 88% 8%,rgba(88,101,242,.22),transparent 34%),${colors.bgSecondary};">
          <div style="display:flex;align-items:flex-start;gap:13px;"><div style="width:44px;height:44px;display:grid;place-items:center;border-radius:14px;background:#5865f2;color:white;font-size:18px;box-shadow:0 10px 24px rgba(88,101,242,.22);"><i class="fab fa-discord"></i></div><div style="min-width:0;flex:1;"><div style="font-size:15px;font-weight:900;color:${colors.text};">${accountDiscordLinked ? 'Discord is connected' : 'Connect Discord to your FI account'}</div><div style="font-size:10.5px;line-height:1.6;color:${colors.textSecondary};margin-top:5px;">${accountDiscordLinked ? `${escapeHtml(accountDiscordIdentity.displayName || accountDiscordIdentity.username || 'Discord member')} is linked. ${accountDiscordReady ? 'Community rewards are ready.' : 'Join the official FI server to activate earning.'}` : 'Link once to unlock contribution rewards. FI verifies your identity and discards the temporary OAuth access token after linking.'}</div><button id="fi-acct-discord-manage" style="margin-top:12px;padding:9px 13px;border:0;border-radius:9px;background:#5865f2;color:white;font-size:10px;font-weight:850;cursor:pointer;"><i class="fab fa-discord" style="margin-right:6px;"></i>${accountDiscordLinked ? 'Manage Discord rewards' : 'Connect Discord securely'}</button></div></div>
        </section>
        ${accountDiscordLinked?`<label style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:10px;padding:11px 12px;border:1px solid ${colors.border};border-radius:11px;background:${colors.bgSecondary};color:${colors.text};font-size:10px;font-weight:750;"><span><i class="fas fa-envelope" style="margin-right:6px;color:#a5b4fc"></i>Discord reward and account DMs</span><input id="fi-acct-discord-dms" type="checkbox" ${accountDiscord.notificationsEnabled!==false?'checked':''} style="accent-color:#5865f2"></label>`:''}
        <div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:10px;"><div style="padding:11px;border:1px solid ${colors.border};border-radius:11px;background:${colors.bgSecondary};"><i class="fas fa-lock" style="color:#86efac;"></i><strong style="display:block;margin-top:7px;font-size:10px;color:${colors.text};">Secure OAuth</strong><small style="display:block;margin-top:3px;font-size:8.5px;line-height:1.45;color:${colors.textSecondary};">No Discord password is shared with FI.</small></div><div style="padding:11px;border:1px solid ${colors.border};border-radius:11px;background:${colors.bgSecondary};"><i class="fas fa-link" style="color:#a5b4fc;"></i><strong style="display:block;margin-top:7px;font-size:10px;color:${colors.text};">One-to-one link</strong><small style="display:block;margin-top:3px;font-size:8.5px;line-height:1.45;color:${colors.textSecondary};">One Discord identity per FI account.</small></div><div style="padding:11px;border:1px solid ${colors.border};border-radius:11px;background:${colors.bgSecondary};"><i class="fas fa-gift" style="color:#f9a8d4;"></i><strong style="display:block;margin-top:7px;font-size:10px;color:${colors.text};">Earn credits</strong><small style="display:block;margin-top:3px;font-size:8.5px;line-height:1.45;color:${colors.textSecondary};">Enabled community tasks reward your wallet.</small></div></div>
      </div>
      <div id="fi-tab-privacy" style="display:none;">
        <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:${colors.textSecondary};margin-bottom:10px;">Privacy</div>
        <div style="display:flex;flex-direction:column;gap:8px;margin-bottom:18px;">
          <label style="display:flex;align-items:flex-start;gap:10px;cursor:pointer;">
            <input type="checkbox" id="fi-priv-analyze" ${privacy.analyzeTasks ? 'checked' : ''} style="margin-top:2px;accent-color:#6366f1;width:14px;height:14px;">
            <div><div style="font-size:12px;font-weight:700;color:${colors.text};">Share Task Analytics</div><div style="font-size:10px;color:${colors.textSecondary};margin-top:2px;">Helps improve bypass success rates by sharing anonymous task outcomes.</div></div>
          </label>
          <label style="display:flex;align-items:flex-start;gap:10px;cursor:pointer;">
            <input type="checkbox" id="fi-priv-errors" ${privacy.sendErrorCrashes ? 'checked' : ''} style="margin-top:2px;accent-color:#6366f1;width:14px;height:14px;">
            <div><div style="font-size:12px;font-weight:700;color:${colors.text};">Send Error Reports</div><div style="font-size:10px;color:${colors.textSecondary};margin-top:2px;">Sends anonymous crash details to help fix bugs. Personal data is excluded.</div></div>
          </label>
          <label style="display:flex;align-items:flex-start;gap:10px;cursor:pointer;">
            <input type="checkbox" id="fi-priv-recognition" ${privacy.allowRecognition !== false ? 'checked' : ''} style="margin-top:2px;accent-color:#6366f1;width:14px;height:14px;">
            <div><div style="font-size:12px;font-weight:700;color:${colors.text};">Allow my profile to be recognized</div><div style="font-size:10px;color:${colors.textSecondary};margin-top:2px;">Allows community member recognition beside your Tensor.art comments.</div></div>
          </label>
          <label style="display:flex;align-items:flex-start;gap:10px;cursor:pointer;">
            <input type="checkbox" id="fi-priv-organized" ${privacy.allowProfileOrganized !== false ? 'checked' : ''} style="margin-top:2px;accent-color:#6366f1;width:14px;height:14px;">
            <div><div style="font-size:12px;font-weight:700;color:${colors.text};">Allow my profile to be organized</div><div style="font-size:10px;color:${colors.textSecondary};margin-top:2px;">Allows your public prompts and contributions to be indexed for discovery.</div></div>
          </label>
        </div>

      </div>
      <div id="fi-tab-host" style="display:none;">
        <div style="display:flex;align-items:center;gap:9px;margin-bottom:10px;"><i class="fas fa-server" style="color:#22d3ee;font-size:16px;"></i><div><div style="font-size:12px;font-weight:800;color:${colors.text};">FI Host desktop access</div><div style="font-size:10px;color:${colors.textSecondary};margin-top:2px;">Manual recovery key for the desktop app only.</div></div></div>
        <div style="font-size:10px;color:${colors.textSecondary};line-height:1.55;margin-bottom:12px;">This scoped key cannot sign in to Community, change your FI account, or reveal your Tensor session. The server stores only its hash. Active use renews its 30-day idle expiry.</div>
        <div id="fi-host-key-status" style="padding:10px 12px;border:1px solid ${colors.border};border-radius:9px;background:${colors.bgSecondary};font-size:10px;color:${colors.textSecondary};margin-bottom:10px;">${communityAccountToken ? 'Checking FI Host access key…' : 'Sign in to your FI account to create a Host access key.'}</div>
        <div id="fi-host-key-reveal" style="display:none;margin-bottom:10px;padding:10px;border:1px solid rgba(34,211,238,.45);border-radius:9px;background:rgba(34,211,238,.07);">
          <div style="font-size:10px;font-weight:800;color:#67e8f9;margin-bottom:6px;">Copy now — this key is shown once</div>
          <div style="display:flex;gap:6px;"><input id="fi-host-key-value" readonly style="flex:1;min-width:0;padding:7px 9px;border:1px solid ${colors.border};border-radius:7px;background:${colors.bg};color:${colors.text};font:10px monospace;"><button id="fi-host-key-copy" style="padding:7px 11px;border:1px solid #22d3ee;border-radius:7px;background:rgba(34,211,238,.12);color:#67e8f9;font-size:10px;font-weight:800;cursor:pointer;">Copy</button></div>
        </div>
        <div style="display:flex;gap:7px;flex-wrap:wrap;"><button id="fi-host-key-rotate" ${communityAccountToken ? '' : 'disabled'} style="padding:7px 12px;border:1px solid #22d3ee;border-radius:8px;background:rgba(34,211,238,.1);color:#67e8f9;font-size:10px;font-weight:800;cursor:${communityAccountToken ? 'pointer' : 'not-allowed'};">Create / rotate key</button><button id="fi-host-key-revoke" ${communityAccountToken ? '' : 'disabled'} style="padding:7px 12px;border:1px solid rgba(248,113,113,.5);border-radius:8px;background:rgba(248,113,113,.08);color:#fca5a5;font-size:10px;font-weight:800;cursor:${communityAccountToken ? 'pointer' : 'not-allowed'};">Revoke key</button></div>
      </div>
      <div id="fi-acct-status" style="min-height:16px;font-size:11px;color:#4ade80;margin-top:10px;"></div>
      <div style="display:flex;gap:8px;margin-top:16px;justify-content:flex-end;"><button id="fi-acct-cancel" style="padding:8px 16px;border-radius:9px;border:1px solid ${colors.border};background:transparent;color:${colors.textSecondary};font-size:12px;cursor:pointer;">Close</button><button id="fi-acct-save" style="display:none;padding:8px 18px;border-radius:9px;border:none;background:linear-gradient(135deg,#6366f1,#8b5cf6);color:#fff;font-size:12px;font-weight:800;cursor:pointer;">Save Privacy</button></div>`;

    const statusEl = box.querySelector('#fi-acct-status');
    const switchTab = (button, tabId) => {
      box.querySelectorAll('[id^="fi-tab-"]').forEach(panel => { panel.style.display = 'none'; });
      const panel = box.querySelector('#fi-tab-' + tabId);
      if (panel) panel.style.display = '';
      box.querySelectorAll('.fi-acct-tab').forEach(tab => {
        tab.style.background = 'transparent';
        tab.style.borderColor = 'transparent';
        tab.style.color = colors.textSecondary;
        tab.style.fontWeight = '700';
      });
      button.style.background = 'rgba(99,102,241,.16)';
      button.style.borderColor = 'rgba(99,102,241,.3)';
      button.style.color = '#a5b4fc';
      button.style.fontWeight = '800';
      const save = box.querySelector('#fi-acct-save');
      if (save) save.style.display = tabId === 'privacy' ? '' : 'none';
      statusEl.textContent = '';
    };
    box.querySelectorAll('.fi-acct-tab').forEach(button => button.addEventListener('click', () => switchTab(button, button.dataset.fiTab)));
    box.querySelector('#fi-acct-open-wallet')?.addEventListener('click', () => { overlay.remove(); fiCreditOpenWallet('overview'); });
    box.querySelector('#fi-acct-open-discord')?.addEventListener('click', () => { overlay.remove(); fiCreditOpenWallet('earn'); });
    box.querySelector('#fi-acct-discord-manage')?.addEventListener('click', () => { overlay.remove(); fiCreditOpenWallet('earn'); });
    box.querySelector('#fi-acct-discord-dms')?.addEventListener('change', async event => { const input=event.currentTarget;input.disabled=true;try{await fiCreditCoreCall('discord.notifications.update',{enabled:input.checked});if(fiCreditPlatformSnapshot?.discord)fiCreditPlatformSnapshot.discord.notificationsEnabled=input.checked;fiCreditWritePersistentCache();showToast(input.checked?'Discord DMs enabled':'Discord DMs disabled','success');}catch(error){input.checked=!input.checked;showToast(error?.message||String(error),'error');}finally{input.disabled=false;} });
    box.querySelector('#fi-acct-view-profile')?.addEventListener('click', () => { overlay.remove(); isExpanded = true; currentTab = 'community'; updateUI(); });

    const hostKeyStatus = box.querySelector('#fi-host-key-status');
    const renderHostKeyStatus = data => {
      if (!hostKeyStatus) return;
      if (!data?.active) {
        hostKeyStatus.innerHTML = `<strong style="color:${colors.text};">No active key</strong><div style="margin-top:3px;">Create one only when automatic browser pairing is unavailable.</div>`;
        return;
      }
      hostKeyStatus.innerHTML = `<strong style="color:#4ade80;">Active Host key</strong><div style="margin-top:3px;font-family:monospace;color:${colors.text};">${escapeHtml(data.prefix || 'fihk_…')}…</div><div style="margin-top:3px;">Expires ${escapeHtml(data.expiresAt || 'after 30 days idle')}${data.lastUsedAt ? ` · last used ${escapeHtml(data.lastUsedAt)}` : ''}</div>`;
    };
    if (communityAccountToken && hostKeyStatus) {
      communityApiCall('account_fihost_key_status', { token: communityAccountToken }).then(response => renderHostKeyStatus(response?.data || {})).catch(error => {
        hostKeyStatus.innerHTML = `<strong style="color:#fca5a5;">Host key unavailable</strong><div style="margin-top:3px;">${escapeHtml(error?.message || String(error))}</div>`;
      });
    }
    box.querySelector('#fi-host-key-rotate')?.addEventListener('click', async event => {
      const button = event.currentTarget;
      if (!communityAccountToken || button.disabled || !confirm('Create a new FI Host access key? Any previous Host access key will be revoked.')) return;
      button.disabled = true;
      const oldText = button.textContent;
      button.textContent = 'Creating…';
      try {
        const response = await communityApiCall('account_fihost_key_rotate', { token: communityAccountToken, label: 'FI Host desktop' });
        const data = response?.data || {};
        const value = String(data.accessKey || '');
        if (!/^fihk_[a-f0-9]{64}$/i.test(value)) throw new Error('The server did not return a valid Host access key.');
        const reveal = box.querySelector('#fi-host-key-reveal');
        const input = box.querySelector('#fi-host-key-value');
        if (input) input.value = value;
        if (reveal) reveal.style.display = '';
        renderHostKeyStatus({ ...data, active: true });
        showToast('New FI Host access key created. Copy it now; it is shown once.', 'success', 9000);
      } catch (error) {
        showToast(`Could not create FI Host key: ${error?.message || error}`, 'error', 10000);
      } finally {
        button.disabled = false;
        button.textContent = oldText;
      }
    });
    box.querySelector('#fi-host-key-copy')?.addEventListener('click', async () => {
      const input = box.querySelector('#fi-host-key-value');
      const value = String(input?.value || '');
      if (!value) return;
      try { await navigator.clipboard.writeText(value); }
      catch { input?.select(); document.execCommand('copy'); }
      showToast('FI Host access key copied.', 'success', 3500);
    });
    box.querySelector('#fi-host-key-revoke')?.addEventListener('click', async event => {
      const button = event.currentTarget;
      if (!communityAccountToken || button.disabled || !confirm('Revoke your active FI Host access key? Existing scoped desktop sessions remain valid until their own expiry.')) return;
      button.disabled = true;
      try {
        await communityApiCall('account_fihost_key_revoke', { token: communityAccountToken });
        const reveal = box.querySelector('#fi-host-key-reveal');
        const input = box.querySelector('#fi-host-key-value');
        if (input) input.value = '';
        if (reveal) reveal.style.display = 'none';
        renderHostKeyStatus({ active: false });
        showToast('FI Host access key revoked.', 'success', 5000);
      } catch (error) {
        showToast(`Could not revoke FI Host key: ${error?.message || error}`, 'error', 9000);
      } finally { button.disabled = false; }
    });

    box.querySelector('#fi-acct-close').onclick = () => overlay.remove();
    box.querySelector('#fi-acct-cancel').onclick = () => overlay.remove();
    box.querySelector('#fi-acct-setpass')?.addEventListener('click', () => { overlay.remove(); showFiPasswordSetupDialog(); });
    box.querySelector('#fi-acct-save').onclick = async () => {
      const analyzeTasks = box.querySelector('#fi-priv-analyze')?.checked ?? true;
      const sendErrorCrashes = box.querySelector('#fi-priv-errors')?.checked ?? true;
      const allowRecognition = box.querySelector('#fi-priv-recognition')?.checked ?? true;
      const allowProfileOrganized = box.querySelector('#fi-priv-organized')?.checked ?? true;
      const saveButton = box.querySelector('#fi-acct-save');
      saveButton.disabled = true;
      saveButton.style.opacity = '0.6';
      try {
        const result = await communityApiCall('update_privacy_settings', { token: communityAccountToken || '', analyzeTasks, sendErrorCrashes, allowRecognition, allowProfileOrganized, scriptVersion: GM_info?.script?.version || '' });
        if (!result?.ok) throw new Error(result?.error || 'Failed to save');
        communityPrivacySettings = { analyzeTasks, sendErrorCrashes, allowRecognition, allowProfileOrganized };
        persistAccountState();
        statusEl.style.color = '#4ade80';
        statusEl.textContent = 'Privacy settings saved!';
        setTimeout(() => overlay.remove(), 900);
      } catch (error) {
        statusEl.style.color = '#f87171';
        statusEl.textContent = error?.message || 'Error';
      } finally {
        saveButton.disabled = false;
        saveButton.style.opacity = '1';
      }
    };

    overlay.appendChild(box);
    document.body.appendChild(overlay);
    _fiMountAccountSecurity(box.querySelector('#fi-tab-account'),colors);
    fiCreditRefresh(false).then(() => {
      if (!overlay.isConnected) return;
      const balance = box.querySelector('[data-fi-acct-balance]');
      if (balance) { balance.textContent = fiCreditFormatCompact(fiCreditWalletValue()); balance.title = fiCreditExactLabel(fiCreditWalletValue()); }
    }).catch(() => {});
    overlay.addEventListener('click', event => { if (event.target === overlay) overlay.remove(); });
  }

  // ─── end v2 Account System Helpers ─────────────────────────────────────────

  function showPromptFlagDialog(currentFlagId, onFlag) {
    const colors = getThemeColors();
    const flags  = getPromptsConfig().prompt_flags || [];
    const overlay = document.createElement('div');
    overlay.style.cssText = `position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:2147483647; display:flex; align-items:center; justify-content:center;`;
    const box = document.createElement('div');
    box.style.cssText = `background:${colors.bg}; border:1px solid ${colors.border}; border-radius:16px; padding:22px; max-width:380px; width:90%; box-shadow:0 8px 40px rgba(0,0,0,0.4);`;
    box.innerHTML = `<div style="font-size:15px; font-weight:800; color:${colors.text}; margin-bottom:14px;"><i class="fas fa-flag" style="color:${colors.primary}; margin-right:7px;"></i>Add a Flag Warning</div>
      <div style="font-size:11px; color:${colors.textSecondary}; margin-bottom:12px; line-height:1.5;">A flag adds a spoiler/warning overlay on your card so viewers can choose to reveal the content.</div>
      <div id="fi-flag-list" style="display:flex; flex-direction:column; gap:7px; margin-bottom:14px;"></div>
      <div style="display:flex; gap:8px; justify-content:flex-end;">
        ${currentFlagId ? `<button id="fi-flag-remove" style="padding:7px 14px; border-radius:8px; border:1px solid #f87171; background:transparent; color:#f87171; font-size:11px; cursor:pointer;"><i class="fas fa-times"></i> Remove Flag</button>` : ''}
        <button id="fi-flag-cancel" style="padding:7px 14px; border-radius:8px; border:1px solid ${colors.border}; background:transparent; color:${colors.textSecondary}; font-size:11px; cursor:pointer;">Cancel</button>
      </div>`;
    const list = box.querySelector('#fi-flag-list');
    flags.forEach(f => {
      const item = document.createElement('button');
      const isSelected = f.id === currentFlagId;
      item.style.cssText = `display:flex; align-items:center; gap:10px; padding:10px 12px; border-radius:9px; border:2px solid ${isSelected ? f.color : colors.border}; background:${isSelected ? f.color + '22' : colors.bgSecondary}; cursor:pointer; text-align:left; transition:all 0.15s;`;
      item.innerHTML = `<i class="${f.icon}" style="color:${f.color}; font-size:16px; width:18px; text-align:center;"></i>
        <div style="flex:1;"><div style="font-size:12px; font-weight:700; color:${colors.text};">${escapeHtml(f.label)}</div>
        <div style="font-size:10px; color:${colors.textSecondary}; margin-top:1px;">${escapeHtml(f.description || '')}</div></div>
        ${isSelected ? `<i class="fas fa-check-circle" style="color:${f.color};"></i>` : ''}`;
      item.onclick = () => { overlay.remove(); onFlag(f.id); };
      list.appendChild(item);
    });
    overlay.appendChild(box);
    document.body.appendChild(overlay);
    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
    box.querySelector('#fi-flag-cancel').onclick = () => overlay.remove();
    if (currentFlagId) { box.querySelector('#fi-flag-remove').onclick = () => { overlay.remove(); onFlag(null); }; }
  }

  function showPromptReportDialog(promptId, onDone) {
    const colors      = getThemeColors();
    const reportTypes = getPromptsConfig().report_types || [];
    const overlay = document.createElement('div');
    overlay.style.cssText = `position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:2147483647; display:flex; align-items:center; justify-content:center;`;
    const box = document.createElement('div');
    box.style.cssText = `background:${colors.bg}; border:1px solid ${colors.border}; border-radius:16px; padding:22px; max-width:400px; width:92%; box-shadow:0 8px 40px rgba(0,0,0,0.4);`;
    box.innerHTML = `<div style="font-size:15px; font-weight:800; color:${colors.text}; margin-bottom:12px;"><i class="fas fa-flag" style="color:#f87171; margin-right:7px;"></i>Report Prompt</div>
      <div style="font-size:11px; color:${colors.textSecondary}; margin-bottom:12px; line-height:1.5;">Choose a reason for reporting. Our team will review it within 24 hours.</div>
      <div id="fi-report-types" style="display:flex; flex-direction:column; gap:6px; margin-bottom:10px;"></div>
      <textarea id="fi-report-desc" placeholder="Additional details (optional)…" style="width:100%; box-sizing:border-box; background:${colors.bgSecondary}; border:1px solid ${colors.border}; border-radius:8px; color:${colors.text}; font-size:11px; padding:8px; resize:vertical; outline:none; margin-bottom:12px;" rows="3"></textarea>
      <div style="display:flex; gap:8px; justify-content:flex-end;">
        <button id="fi-report-cancel" style="padding:7px 14px; border-radius:8px; border:1px solid ${colors.border}; background:transparent; color:${colors.textSecondary}; font-size:11px; cursor:pointer;">Cancel</button>
        <button id="fi-report-send" disabled style="padding:7px 16px; border-radius:8px; border:none; background:#f87171; color:#fff; font-size:11px; font-weight:700; cursor:not-allowed; opacity:0.5;">Report</button>
      </div>`;
    let selectedType = null;
    const typeContainer = box.querySelector('#fi-report-types');
    const sendBtn = box.querySelector('#fi-report-send');
    reportTypes.forEach(rt => {
      const item = document.createElement('button');
      item.style.cssText = `display:flex; align-items:center; gap:8px; padding:8px 11px; border-radius:8px; border:1px solid ${colors.border}; background:${colors.bgSecondary}; cursor:pointer; text-align:left; transition:all 0.1s;`;
      item.innerHTML = `<div style="flex:1;"><div style="font-size:11.5px; font-weight:600; color:${colors.text};">${escapeHtml(rt.label)}</div>
        <div style="font-size:10px; color:${colors.textSecondary};">${escapeHtml(rt.description || '')}</div></div>`;
      item.onclick = () => {
        selectedType = rt.id;
        typeContainer.querySelectorAll('button').forEach(b => { b.style.borderColor = colors.border; b.style.background = colors.bgSecondary; });
        item.style.borderColor = '#f87171';
        item.style.background  = '#f8717122';
        sendBtn.disabled = false; sendBtn.style.opacity = '1'; sendBtn.style.cursor = 'pointer';
      };
      typeContainer.appendChild(item);
    });
    overlay.appendChild(box);
    document.body.appendChild(overlay);
    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
    box.querySelector('#fi-report-cancel').onclick = () => overlay.remove();
    sendBtn.onclick = async () => {
      if (!selectedType) return;
      const desc = box.querySelector('#fi-report-desc').value.trim();
      sendBtn.disabled = true; sendBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
      try {
        await communityReportPrompt(promptId, selectedType, desc);
        overlay.remove();
        showToast('Report submitted. Thank you!', 'success');
        if (onDone) onDone();
      } catch (err) {
        showToast('Report failed: ' + String(err?.message || err), 'error');
        sendBtn.disabled = false; sendBtn.innerHTML = 'Report';
      }
    };
  }

  function showPromptCustomizeDialog(currentColor, onApply) {
    const colors  = getThemeColors();
    const presets = ['#6366f1', '#8b5cf6', '#ec4899', '#f59e0b', '#10b981', '#06b6d4', '#f97316', '#ef4444', '#64748b', ''];
    const overlay = document.createElement('div');
    overlay.style.cssText = `position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:2147483647; display:flex; align-items:center; justify-content:center;`;
    const box = document.createElement('div');
    box.style.cssText = `background:${colors.bg}; border:1px solid ${colors.border}; border-radius:16px; padding:22px; max-width:340px; width:92%; box-shadow:0 8px 40px rgba(0,0,0,0.4);`;
    let picked = currentColor || '';
    box.innerHTML = `<div style="font-size:15px; font-weight:800; color:${colors.text}; margin-bottom:12px;"><i class="fas fa-palette" style="color:${colors.primary}; margin-right:7px;"></i>Post Color</div>
      <div style="font-size:11px; color:${colors.textSecondary}; margin-bottom:12px; line-height:1.5;">Choose an accent color that will tint the border of your prompt card.</div>
      <div id="fi-color-presets" style="display:flex; flex-wrap:wrap; gap:8px; margin-bottom:14px;"></div>
      <div id="fi-color-preview" style="padding:10px 12px; border-radius:10px; border:2px solid ${picked || colors.border}; background:${colors.bgSecondary}; font-size:11px; color:${colors.text}; margin-bottom:14px; transition:border-color 0.2s;">
        Preview card border color
      </div>
      <div style="display:flex; gap:8px; justify-content:flex-end;">
        <button id="fi-color-cancel" style="padding:7px 14px; border-radius:8px; border:1px solid ${colors.border}; background:transparent; color:${colors.textSecondary}; font-size:11px; cursor:pointer;">Cancel</button>
        <button id="fi-color-apply" style="padding:7px 16px; border-radius:8px; border:none; background:${colors.primary}; color:#fff; font-size:11px; font-weight:700; cursor:pointer;">Apply</button>
      </div>`;
    const preview = box.querySelector('#fi-color-preview');
    const presetsEl = box.querySelector('#fi-color-presets');
    const updatePreview = () => { preview.style.borderColor = picked || colors.border; };
    presets.forEach(c => {
      const dot = document.createElement('button');
      const isNone = c === '';
      dot.title = isNone ? 'No color (default)' : c;
      dot.style.cssText = `width:28px; height:28px; border-radius:50%; border:2px solid ${picked === c ? (c || colors.border) : 'transparent'}; background:${isNone ? colors.bgSecondary : c}; cursor:pointer; box-shadow:0 1px 4px rgba(0,0,0,0.2); transition:border-color 0.15s; outline:${isNone ? `1px dashed ${colors.border}` : 'none'};`;
      if (isNone) dot.innerHTML = `<i class="fas fa-times" style="font-size:10px; color:${colors.textSecondary};"></i>`;
      dot.onclick = () => {
        picked = c;
        presetsEl.querySelectorAll('button').forEach((b, i) => { b.style.borderColor = presets[i] === c ? (c || colors.border) : 'transparent'; });
        updatePreview();
      };
      presetsEl.appendChild(dot);
    });
    overlay.appendChild(box);
    document.body.appendChild(overlay);
    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
    box.querySelector('#fi-color-cancel').onclick = () => overlay.remove();
    box.querySelector('#fi-color-apply').onclick  = () => { overlay.remove(); onApply(picked || null); };
  }

  function showProfileContextPopup(anchorEl, accountInfo) {
    document.querySelectorAll('.fi-profile-popup').forEach(e => e.remove());
    const colors = getThemeColors();
    const popup  = document.createElement('div');
    popup.className = 'fi-profile-popup';
    popup.style.cssText = `position:fixed; z-index:2147483647; background:${colors.bg}; border:1px solid ${colors.border}; border-radius:14px; padding:14px 16px; min-width:200px; max-width:260px; box-shadow:0 8px 32px rgba(0,0,0,0.4); animation:fadeIn 0.15s ease;`;
    const avatarHtml = accountInfo.avatarUrl
      ? `<img src="${escapeHtml(accountInfo.avatarUrl)}" style="width:38px; height:38px; border-radius:50%; object-fit:cover; border:2px solid ${colors.border};" alt="">`
      : `<div style="width:38px; height:38px; border-radius:50%; background:${colors.primary}33; display:flex; align-items:center; justify-content:center; border:2px solid ${colors.border};"><i class="fas fa-user" style="color:${colors.primary}; font-size:15px;"></i></div>`;
    const isMe = communityAccountId && communityAccountId === accountInfo.accountId;
    popup.innerHTML = `
      <div style="display:flex; align-items:center; gap:10px; margin-bottom:10px;">
        ${avatarHtml}
        <div style="min-width:0;"><div style="font-size:13px; font-weight:700; color:${colors.text}; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">@${escapeHtml(accountInfo.username || 'Unknown')}</div>
        ${isMe ? `<div style="font-size:10px; color:${colors.primary}; font-weight:600;">You</div>` : ''}</div>
      </div>
      ${accountInfo.bio ? `<div style="font-size:10.5px; color:${colors.textSecondary}; margin-bottom:8px; line-height:1.5;">${escapeHtml(accountInfo.bio)}</div>` : ''}
      <div style="font-size:10px; color:${colors.textSecondary}; margin-bottom:${!isMe ? '10px' : '0'};"><i class="fas fa-layer-group" style="margin-right:4px; opacity:0.6;"></i>${accountInfo.postCount ?? '?'} prompts</div>
      ${!isMe && communityAccountToken ? `<div style="display:flex; gap:6px;">
        <button data-fi-profile-block style="flex:1; padding:5px 8px; border-radius:7px; border:1px solid ${colors.border}; background:transparent; color:${colors.textSecondary}; font-size:10px; cursor:pointer;"><i class="fas fa-ban"></i> Block</button>
        <button data-fi-profile-hide  style="flex:1; padding:5px 8px; border-radius:7px; border:1px solid ${colors.border}; background:transparent; color:${colors.textSecondary}; font-size:10px; cursor:pointer;"><i class="fas fa-eye-slash"></i> Hide</button>
      </div>` : ''}`;
    document.body.appendChild(popup);
    // Position near anchor
    const rect = anchorEl.getBoundingClientRect();
    const top  = Math.min(rect.bottom + 6, window.innerHeight - 180);
    const left = Math.max(8, Math.min(rect.left, window.innerWidth - 270));
    popup.style.top  = top  + 'px';
    popup.style.left = left + 'px';
    const close = e => { if (!popup.contains(e.target) && e.target !== anchorEl) { popup.remove(); document.removeEventListener('mousedown', close); } };
    setTimeout(() => document.addEventListener('mousedown', close), 50);
    popup.querySelector('[data-fi-profile-block]')?.addEventListener('click', async () => {
      popup.remove();
      try { await communityBlockUser(accountInfo.accountId); showToast('User blocked.', 'success'); } catch (_) {}
    });
    popup.querySelector('[data-fi-profile-hide]')?.addEventListener('click', async () => {
      popup.remove();
      try { await communityHideUser(accountInfo.accountId); showToast('User hidden.', 'success'); } catch (_) {}
    });
  }

  const COMMUNITY_PROMPTS_LS_KEY = 'freeBypassCommunityPromptsLS';

  async function communityFetchPrompts(forceRefresh = false) {
    // In-memory cache (fast path during session)
    const ttl = Number(remoteConfig?.configuration?.api_community_prompts?.cacheExpireMs) || 300000;
    if (!forceRefresh && communityPromptsCache && (Date.now() - communityPromptsCacheAt) < ttl) {
      return communityPromptsCache;
    }
    // localStorage persistence: serve stale data when not forcing refresh
    if (!forceRefresh) {
      try {
        const lsRaw = localStorage.getItem(COMMUNITY_PROMPTS_LS_KEY);
        if (lsRaw) {
          const lsParsed = JSON.parse(lsRaw);
          if (Array.isArray(lsParsed)) {
            communityPromptsCache = lsParsed;
            communityPromptsCacheAt = Date.now();
            return communityPromptsCache;
          }
        }
      } catch (_) {}
    }
    const limit = Number(remoteConfig?.configuration?.api_community_prompts?.maxPromptsPerPage) || 20;
    const payload = { limit };
    if (communityAccountToken) payload.token = communityAccountToken;
    const result = await communityApiCall('get_prompts', payload);
    communityPromptsCache = Array.isArray(result?.data) ? result.data : [];
    communityPromptsCacheAt = Date.now();
    // Persist to localStorage for next page load
    try { localStorage.setItem(COMMUNITY_PROMPTS_LS_KEY, JSON.stringify(communityPromptsCache)); } catch (_) {}
    return communityPromptsCache;
  }

  async function communitySharePrompt(promptText, promptType, toolUrl, { tags = [], flagId = null, instructions = null, postColor = null, isAnonymous = false, allowComments = true, allowReplies = true } = {}) {
    if (communityIsRestricted || !canSharePrompts()) {
      showToast('Your account does not have permission to share prompts.', 'warning');
      return { ok: false, error: 'restricted' };
    }
    const payload = { promptText, promptType, toolUrl: toolUrl || '', tags, isAnonymous, allowComments, allowReplies };
    if (communityAccountToken) payload.token = communityAccountToken;
    if (flagId)       payload.flagId       = flagId;
    if (instructions) payload.instructions = instructions;
    if (postColor)    payload.postColor    = postColor;
    return communityApiCall('add_prompt', payload);
  }

  // Gen Profile sharing helpers ─────────────────────────────────────────────
  async function communityShareGenProfile(toolId, toolName, profileName, nodes, { tags = [], flagId = null, instructions = null, postColor = null, isAnonymous = false } = {}) {
    if (!communityAccountToken) throw new Error('Login required to share gen profiles');
    const payload = { toolId, toolName, profileName, nodes, tags, isAnonymous };
    payload.token = communityAccountToken;
    if (flagId)       payload.flagId       = flagId;
    if (instructions) payload.instructions = instructions;
    if (postColor)    payload.postColor    = postColor;
    return communityApiCall('share_genprofile', payload);
  }

  async function communityGetGenProfiles({ toolId = null, limit = 20, offset = 0 } = {}) {
    const payload = { limit, offset };
    if (toolId) payload.toolId = toolId;
    if (communityAccountToken) payload.token = communityAccountToken;
    return communityApiCall('get_genprofiles', payload);
  }

  async function communityLikeGenProfile(profileId) {
    if (!communityAccountToken) throw new Error('Login required');
    return communityApiCall('like_genprofile', { profileId, token: communityAccountToken });
  }

  async function communityDeleteGenProfile(profileId) {
    if (!communityAccountToken) throw new Error('Login required');
    return communityApiCall('delete_genprofile', { profileId, token: communityAccountToken });
  }

  // Shows the gen profile share dialog (flag / color / instructions / tags before confirming share)
  function showShareGenProfileDialog(templateId, entry, prof) {
    const colors = getThemeColors();
    let shareTags = [];
    let shareFlagId = null;
    let sharePostColor = null;
    let shareIsAnonymous = false;
    let shareInstructions = null;

    const overlay = document.createElement('div');
    overlay.style.cssText = `position:fixed; inset:0; background:rgba(0,0,0,0.65); z-index:2147483647; display:flex; align-items:center; justify-content:center; padding:16px;`;

    const box = document.createElement('div');
    box.style.cssText = `background:${colors.bg}; border:1px solid ${colors.border}; border-radius:18px; width:min(480px,96vw); max-height:85vh; display:flex; flex-direction:column; overflow:hidden; box-shadow:0 24px 80px rgba(0,0,0,0.6); font-size:12px; color:${colors.text};`;

    // Header
    const hdr = document.createElement('div');
    hdr.style.cssText = `display:flex; align-items:center; justify-content:space-between; padding:13px 16px 11px; background:${colors.bgSecondary}; border-bottom:1px solid ${colors.border};`;
    hdr.innerHTML = `<span style="font-weight:800; font-size:13px;"><i class="fas fa-cloud-upload-alt" style="color:${colors.primary}; margin-right:7px;"></i>Share Gen Profile to Community</span>`;
    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.style.cssText = `border:none; background:none; color:${colors.textSecondary}; font-size:14px; cursor:pointer; padding:2px 6px;`;
    closeBtn.innerHTML = '<i class="fas fa-times"></i>';
    closeBtn.onclick = () => overlay.remove();
    hdr.appendChild(closeBtn);
    box.appendChild(hdr);

    const body = document.createElement('div');
    body.style.cssText = `flex:1; overflow-y:auto; padding:14px 16px; display:flex; flex-direction:column; gap:10px;`;

    // Profile info preview
    const infoCard = document.createElement('div');
    infoCard.style.cssText = `padding:10px; border-radius:9px; background:${colors.bgSecondary}; border:1px solid ${colors.border}; display:flex; flex-direction:column; gap:4px;`;
    const nodesToShare = (prof.nodes || []).filter(n => !_isAutoSnapshotSkipField(n));
    infoCard.innerHTML = `
      <div style="font-size:11px; font-weight:800; color:${colors.primary}; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;"><i class="fas fa-sliders-h" style="margin-right:5px;"></i>${escapeHtml(prof.name || 'Unnamed Profile')}</div>
      <div style="font-size:10px; color:${colors.textSecondary};">${escapeHtml(entry.templateName || templateId)} · ${nodesToShare.length} params</div>
      <div style="max-height:80px; overflow-y:auto; margin-top:4px; display:flex; flex-direction:column; gap:2px;">
        ${nodesToShare.slice(0, 10).map(n => `<div style="display:flex; gap:8px; font-size:10px;"><span style="color:${colors.primary}; min-width:80px; flex-shrink:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${escapeHtml(n.fieldDisplayName || n.fieldName)}</span><span style="color:${colors.textSecondary};">${escapeHtml(String(n.fieldValue ?? '').slice(0, 60))}</span></div>`).join('')}
        ${nodesToShare.length > 10 ? `<div style="font-size:9px; color:${colors.textSecondary}; margin-top:2px;">…and ${nodesToShare.length - 10} more</div>` : ''}
      </div>`;
    body.appendChild(infoCard);

    // Tags
    const tagsSection = document.createElement('div');
    tagsSection.style.cssText = 'display:flex; flex-direction:column; gap:4px;';
    const tagsLabel = document.createElement('label');
    tagsLabel.style.cssText = `font-size:10px; color:${colors.textSecondary}; font-weight:700; text-transform:uppercase; letter-spacing:.04em;`;
    tagsLabel.textContent = 'Tags (optional)';
    const tagsInput = document.createElement('input');
    tagsInput.type = 'text';
    tagsInput.placeholder = 'e.g. portrait, realistic, landscape';
    tagsInput.style.cssText = `width:100%; box-sizing:border-box; padding:7px 10px; border-radius:8px; border:1px solid ${colors.border}; background:${colors.bgSecondary}; color:${colors.text}; font-size:11px; outline:none;`;
    tagsInput.onfocus = () => tagsInput.style.borderColor = colors.primary;
    tagsInput.onblur  = () => tagsInput.style.borderColor = colors.border;
    tagsSection.appendChild(tagsLabel);
    tagsSection.appendChild(tagsInput);
    body.appendChild(tagsSection);

    // Instructions
    const instrSection = document.createElement('div');
    instrSection.style.cssText = 'display:flex; flex-direction:column; gap:4px;';
    const instrLabel = document.createElement('label');
    instrLabel.style.cssText = `font-size:10px; color:${colors.textSecondary}; font-weight:700; text-transform:uppercase; letter-spacing:.04em;`;
    instrLabel.textContent = 'Instructions / Notes (optional)';
    const instrInput = document.createElement('textarea');
    instrInput.rows = 3;
    instrInput.placeholder = 'Describe what this profile is good for…';
    instrInput.style.cssText = `width:100%; box-sizing:border-box; padding:7px 10px; border-radius:8px; border:1px solid ${colors.border}; background:${colors.bgSecondary}; color:${colors.text}; font-size:11px; outline:none; resize:vertical; font-family:inherit;`;
    instrInput.onfocus = () => instrInput.style.borderColor = colors.primary;
    instrInput.onblur  = () => instrInput.style.borderColor = colors.border;
    instrSection.appendChild(instrLabel);
    instrSection.appendChild(instrInput);
    body.appendChild(instrSection);

    // Options row (flag / color / anonymous)
    const optRow = document.createElement('div');
    optRow.style.cssText = `display:flex; gap:6px; flex-wrap:wrap;`;
    const mkOptBtn = (icon, label, onClick) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.style.cssText = `padding:5px 11px; border-radius:8px; border:1px solid ${colors.border}; background:${colors.bgSecondary}; color:${colors.textSecondary}; font-size:10px; cursor:pointer; display:flex; align-items:center; gap:5px; transition:all 0.12s;`;
      b.innerHTML = `<i class="${icon}"></i> ${label}`;
      b.onmouseenter = () => b.style.borderColor = colors.primary;
      b.onmouseleave = () => b.style.borderColor = colors.border;
      b.onclick = (e) => { e.stopPropagation(); onClick(b); };
      return b;
    };
    const flagBtn = mkOptBtn('fas fa-flag', 'Flag', () => {
      showPromptFlagDialog(shareFlagId, fid => { shareFlagId = fid; flagBtn.innerHTML = `<i class="fas fa-flag"></i> ${fid ? fid : 'Flag'}`; flagBtn.style.color = fid ? '#f97316' : colors.textSecondary; });
    });
    const colorBtn = mkOptBtn('fas fa-palette', 'Color', () => {
      showPromptCustomizeDialog(sharePostColor, c => { sharePostColor = c; colorBtn.style.background = c ? c + '22' : colors.bgSecondary; colorBtn.style.borderColor = c || colors.border; });
    });
    const anonBtn = mkOptBtn('fas fa-user-secret', 'Anonymous', () => {
      shareIsAnonymous = !shareIsAnonymous;
      anonBtn.style.background = shareIsAnonymous ? colors.primary + '22' : colors.bgSecondary;
      anonBtn.style.borderColor = shareIsAnonymous ? colors.primary : colors.border;
      anonBtn.style.color = shareIsAnonymous ? colors.primary : colors.textSecondary;
    });
    optRow.appendChild(flagBtn);
    optRow.appendChild(colorBtn);
    if (communityAccountToken) optRow.appendChild(anonBtn);
    body.appendChild(optRow);

    box.appendChild(body);

    // Footer
    const foot = document.createElement('div');
    foot.style.cssText = `display:flex; gap:8px; padding:12px 16px; background:${colors.bgSecondary}; border-top:1px solid ${colors.border};`;
    const cancelBtn = document.createElement('button');
    cancelBtn.type = 'button';
    cancelBtn.style.cssText = `padding:8px 16px; border-radius:9px; border:1px solid ${colors.border}; background:transparent; color:${colors.textSecondary}; font-size:11px; cursor:pointer;`;
    cancelBtn.textContent = 'Cancel';
    cancelBtn.onclick = () => overlay.remove();
    const shareBtn = document.createElement('button');
    shareBtn.type = 'button';
    shareBtn.style.cssText = `flex:1; padding:9px; border-radius:9px; border:none; background:${colors.primary}; color:#fff; font-size:12px; font-weight:700; cursor:pointer; display:flex; align-items:center; justify-content:center; gap:7px;`;
    shareBtn.innerHTML = `<i class="fas fa-cloud-upload-alt"></i> Share to Community`;
    shareBtn.onclick = async () => {
      shareBtn.disabled = true;
      shareBtn.innerHTML = `<i class="fas fa-spinner fa-spin"></i> Sharing…`;
      const rawTags = tagsInput.value.trim();
      const tagArr  = rawTags ? rawTags.split(',').map(t => t.trim()).filter(Boolean) : [];
      const instrVal = instrInput.value.trim() || null;
      try {
        const res = await communityShareGenProfile(templateId, entry.templateName || templateId, prof.name || 'Profile', nodesToShare, {
          tags: tagArr,
          flagId: shareFlagId,
          instructions: instrVal,
          postColor: sharePostColor,
          isAnonymous: shareIsAnonymous,
        });
        if (res && res.ok) {
          overlay.remove();
          showToast('Gen profile shared to community!', 'success');
        } else {
          throw new Error(res?.error || 'Unknown error');
        }
      } catch (err) {
        showToast('Failed to share: ' + String(err?.message || err), 'error');
        shareBtn.disabled = false;
        shareBtn.innerHTML = `<i class="fas fa-cloud-upload-alt"></i> Share to Community`;
      }
    };
    foot.appendChild(cancelBtn);
    foot.appendChild(shareBtn);
    box.appendChild(foot);

    overlay.appendChild(box);
    overlay.onclick = (e) => { if (e.target === overlay) overlay.remove(); };
    document.body.appendChild(overlay);
  }

  async function communityAddComment(promptId, commentText, { parentId = null, commentType = 'general', promptText = null, instructions = null, isAnonymous = false } = {}) {
    const payload = { promptId, commentText, commentType, isAnonymous };
    if (parentId) payload.parentId = parentId;
    if (promptText && commentType === 'enhance') payload.promptText = promptText;
    if (instructions && commentType === 'enhance') payload.instructions = instructions;
    if (communityAccountToken) payload.token = communityAccountToken;
    return communityApiCall('add_comment', payload);
  }

