      const age = now - (Number(item.uploadedAt || 0) || now);
      const hasData = _hasUploadedMediaDataPayload(item);
      const remoteUrl = _getUploadedMediaPreferredRemoteUrl(item);
      const isRemoteOnly = !hasData && /^https?:\/\//i.test(remoteUrl || getUploadedMediaSrc(item));

