    wrap.title = info.expiresAt
      ? `${info.detail}. Added ${new Date(_getUploadedMediaAddedAt(item)).toLocaleString()}. Cleanup time ${new Date(info.expiresAt).toLocaleString()}.`
      : info.detail;
    wrap.style.cssText = `border:1px solid ${info.border};background:${info.bg};border-radius:8px;padding:5px 6px;display:flex;flex-direction:column;gap:4px;color:${info.tone};box-shadow:${info.active ? `0 0 18px ${fiColorMix(info.tone, 18, 'transparent')}` : 'none'};`;
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0;';
    row.innerHTML = `<span style="display:inline-flex;align-items:center;gap:5px;min-width:0;font-size:9px;font-weight:900;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;"><i class="fas ${info.icon}"></i>${escapeHtml(info.detail)}</span><span style="font-size:8px;font-weight:900;opacity:.9;">${info.pinned ? 'PIN' : (info.active ? `${Math.round(info.progressPct)}%` : '')}</span>`;
    wrap.appendChild(row);
    const bar = document.createElement('div');
    bar.style.cssText = 'height:4px;border-radius:999px;background:rgba(148,163,184,.18);overflow:hidden;position:relative;';
    const width = info.active ? Math.max(4, Math.min(100, info.progressPct)) : 100;
    bar.innerHTML = `<div class="fi-media-ttl-fill" style="height:100%;width:${width}%;background:${info.active ? info.tone : (colors.border || 'rgba(148,163,184,.5)')};border-radius:999px;"></div>`;
    wrap.appendChild(bar);
    return wrap;
