      store: typeof definition.store === 'function' ? definition.store : null,
      resolve: typeof definition.resolve === 'function' ? definition.resolve : null,
      refresh: typeof definition.refresh === 'function' ? definition.refresh : null,
      read: typeof definition.read === 'function' ? definition.read : null,
      readPreview: typeof definition.readPreview === 'function' ? definition.readPreview : null,
      isAvailable: typeof definition.isAvailable === 'function' ? definition.isAvailable : null,
