      label: String(def.label || actionId).slice(0, 80),
      title: String(def.title || def.label || actionId).slice(0, 180),
      icon: String(def.icon || 'fa-plug').replace(/[^a-zA-Z0-9 _-]/g, '').slice(0, 80),
