      id: actionId,
      label: String(def.label || actionId).slice(0, 80),
      title: String(def.title || def.label || actionId).slice(0, 180),
      description: String(def.description || '').slice(0, 260),
      icon: String(def.icon || 'fa-server').replace(/[^a-zA-Z0-9 _-]/g, '').slice(0, 80),
