    const CARD_CSS = `._fi-ic{padding:10px 12px;border-radius:10px;border:1px solid;margin-bottom:1px;}._fi-it{font-weight:700;margin-bottom:4px;font-size:11px;display:flex;align-items:center;gap:6px;}._fi-ib{color:#94a3b8;font-size:11px;line-height:1.55;}._fi-ib kbd{background:rgba(255,255,255,0.1);border-radius:4px;padding:1px 5px;font-family:monospace;font-size:10px;}._fi-ib strong{color:#cbd5e1;}`;

