        statusDot.style.cssText = `width:6px; height:6px; border-radius:50%; background:${d.isCurrent ? '#34d399' : '#64748b'}; flex-shrink:0;`;
        cardHeader.appendChild(statusDot); cardHeader.appendChild(nameEl);

        const totalSpan = document.createElement('div');
