        if (d.dailyAmount > 0) subLine.innerHTML += `<span><i class="fas fa-calendar-day" style="margin-right:2px; color:#60a5fa;"></i>${d.dailyAmount.toLocaleString(undefined,{maximumFractionDigits:0})} daily</span>`;
        if (d.restrictedAmount > 0) subLine.innerHTML += `<span><i class="fas fa-lock" style="margin-right:2px; color:#f87171;"></i>${d.restrictedAmount.toLocaleString(undefined,{maximumFractionDigits:0})} restricted</span>`;
