  // ═══════════════════════════════════════════════════════════════════════════
  //  FI CREDIT GUARD (FICG)   intercept /create before sending, enforce budgets
  // ═══════════════════════════════════════════════════════════════════════════

  /** Get the most relevant cached credits entry for the current session. */
  function ficgGetCurrentBalance() {
    if (!accountCreditsCache || typeof accountCreditsCache !== 'object') return null;
    // Try to match current userToken first
    if (userToken) {
      try {
        const acctInfo = cachedUserAccounts[userToken] || {};
        const profileData = cachedUserProfiles[userToken] || {};
        const userId = acctInfo.userId || profileData?.profile?.info?.userId || null;
        if (userId && accountCreditsCache[userId]) return accountCreditsCache[userId];
        const fallbackKey = 'token_' + userToken.slice(-12);
        if (accountCreditsCache[fallbackKey]) return accountCreditsCache[fallbackKey];
      } catch { /* ignore */ }
    }
    // Fallback: return most recently fetched entry
    let best = null, bestTs = 0;
    for (const entry of Object.values(accountCreditsCache)) {
      if (entry && typeof entry.fetchedAt === 'number' && entry.fetchedAt > bestTs) {
        bestTs = entry.fetchedAt; best = entry;
      }
    }
    return best;
  }

  /**
   * Compute credits spent across all cached tasks within the given time window.
   * @param {number} windowMs  milliseconds back from now (e.g. 86400000 = 1 day)
   * @returns {number} credits spent
   */
  function ficgGetCreditsSpent(windowMs) {
    const cutoff = Date.now() - windowMs;
    let spent = 0;
    const seen = new Set();
    try {
      (itemsData || []).forEach(item => {
        const meta = (typeof itemMap !== 'undefined' && itemMap)
          ? (itemMap.get?.(item.id) || itemMap.get?.(String(item.id)) || {})
          : {};
        const rawTask = meta.rawTask || {};
        const taskId = rawTask.taskId || rawTask.id || item.taskId || item.id;
        if (!taskId || seen.has(taskId)) return;
        seen.add(taskId);
        const credits = parseFloat(rawTask.credits) || 0;
        if (!credits) return;
        const tsRaw = parseInt(rawTask.createdAt) || 0;
        const tsMs = tsRaw > 9e8 ? tsRaw * 1000 : tsRaw; // seconds → ms
        if (tsMs >= cutoff) spent += credits;
      });
    } catch { /* ignore */ }
    return spent;
  }

  /**
   * Pre-flight credit guard check. Returns {blocked:false} if allowed,
   * or {blocked:true, reason, ...data} if blocked.
   */
  function ficgCheckAndBlock() {
    if (!settings.creditGuardEnabled) return { blocked: false };
    try {
      // 1. Minimum balance protection
      if (settings.creditGuardMinBalanceEnabled) {
        const entry = ficgGetCurrentBalance();
        if (entry && typeof entry.totalRemaining === 'number') {
          const bal = entry.totalRemaining;
          const minBal = settings.creditGuardMinBalance || 0;
          if (bal < minBal) return { blocked: true, reason: 'min_balance', balance: bal, minBalance: minBal };
        }
      }
      // 2. Time budget
      if (settings.creditGuardBudgetEnabled) {
        const period = settings.creditGuardBudgetPeriod || 'day';
        const windowMs = period === 'week' ? 7 * 24 * 3600 * 1000 : 24 * 3600 * 1000;
        const spent = ficgGetCreditsSpent(windowMs);
        const budget = settings.creditGuardBudgetAmount || 0;
        if (budget > 0 && spent >= budget) return { blocked: true, reason: 'budget', spent, budget, period };
      }
    } catch { /* never block on error */ }
    return { blocked: false };
  }

