    // Numbers   \b correctly skips the _N_ inside placeholders
    s = s.replace(/\b(-?\d+\.?\d*(?:[eE][+-]?\d+)?)\b/g, '<span style="color:#f97316;">$1</span>');
    // Booleans / null
    s = s.replace(/\b(true|false|null)\b/g, '<span style="color:#fb923c;font-style:italic;">$1</span>');
    // Structural chars
    s = s.replace(/([{}[\]])/g, '<span style="color:#22d3ee;font-weight:700;">$1</span>');
    // Restore strings: followed by colon → key (purple), else → value (green / cyan for URLs)
    s = s.replace(/\x00_(\d+)_\x00(\s*:)/g, (_, i, colon) =>
      `<span style="color:#818cf8;font-weight:600;">${strs[i].replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</span>${colon}`);
