        // 2. Read response body + headers before showing dialog
        let _inRespText = '';
        try { _inRespText = await _inResp.clone().text(); } catch {}
        const _inRespHdrs = {};
        try { _inResp.headers.forEach((v, k) => { _inRespHdrs[k] = v; }); } catch {}
