            fitagMonitorLog('info', `[Modifier] Incoming response forwarded (edited=${_outBody !== _inRespText})`);
            return new Response(_outBody, { status: _inResp.status, statusText: _inResp.statusText, headers: new Headers(_outHdrs) });
