    try { const r = StorageEngine.getItem(SCRIPT_EXTENSIONS_KEY); if (r) fromIDB = JSON.parse(r); } catch {}
    try { if (typeof GM_getValue === 'function') { const r = FIManagerStore.get(SCRIPT_EXTENSIONS_KEY, null); if (r) fromGM = JSON.parse(r); } } catch {}
    _fiExtSysLog('info', 'storage', `layers - IDB: ${fromIDB?.length ?? 'null'}, GM: ${fromGM?.length ?? 'null'}`);
    const best = [fromIDB, fromGM]
