        _extWindowRegistry.get(safeId)?.remove?.();
        const colors = getThemeColors();
        const root = document.createElement('div');
        root.setAttribute('data-fi-ext-window-runtime', 'true');
        root.setAttribute('data-fi-ext-window-id', safeId);
        const width = Math.max(220, Math.min(Number(options.width) || 380, Math.max(240, window.innerWidth - 20)));
