              status: String(entry?.status || 'queued'),
              taskSource: String(entry?.taskSource || entry?.source || ''),
              endpoint: String(entry?.endpoint || entry?.path || FITAG_PATH).replace(/^https:\/\/api\.tensor\.art\//i, '').replace(/^\/+/, '').split(/[?#]/)[0].slice(0, 500),
