        remove(key) { try { localStorage.removeItem(key); return true; } catch { return false; } },
        list(prefix) { try { const p = prefix || 'freeBypass'; return Object.keys(localStorage).filter(k => k.startsWith(p)).sort(); } catch { return []; } },
        keys(contains) { try { let all = Object.keys(localStorage).sort(); if (contains) { const f = String(contains).toLowerCase(); all = all.filter(k => k.toLowerCase().includes(f)); } return all; } catch { return []; } },
