        min(arr, key) { const a = Array.isArray(arr) ? arr : []; return a.length ? Math.min(...a.map(it => Number(key ? it?.[key] : it) || 0)) : null; },
        max(arr, key) { const a = Array.isArray(arr) ? arr : []; return a.length ? Math.max(...a.map(it => Number(key ? it?.[key] : it) || 0)) : null; },
