        lines(s) { return String(s ?? '').split('\n'); },
        words(s) { return String(s ?? '').trim().split(/\s+/).filter(Boolean); },
        count(s, sub) { const str = String(s ?? ''); if (!sub) return str.length; const f = String(sub); let n = 0, i = 0; while ((i = str.indexOf(f, i)) !== -1) { n++; i += f.length; } return n; },
        includes(s, sub) { return String(s ?? '').toLowerCase().includes(String(sub ?? '').toLowerCase()); },
        camel(s) { return String(s ?? '').replace(/[-_\s]+(.)?/g, (_, c) => c ? c.toUpperCase() : ''); },
        snake(s) { return String(s ?? '').replace(/([a-z])([A-Z])/g, '$1_$2').replace(/[\s-]+/g, '_').toLowerCase(); },
        kebab(s) { return String(s ?? '').replace(/([a-z])([A-Z])/g, '$1-$2').replace(/[\s_]+/g, '-').toLowerCase(); },
        template(tmpl, vars) { return String(tmpl ?? '').replace(/\{\{(\w+)\}\}/g, (_, k) => vars?.[k] ?? ''); },
        toBase64(s) { try { return btoa(unescape(encodeURIComponent(String(s ?? '')))); } catch { return null; } },
