    //  Recent Images Gallery ────────────────────────────────────────────
    panels.background.appendChild(_sectionHead('Recent Images', 'fa-history'));
    const recentGrid = document.createElement('div');
    recentGrid.style.cssText = 'display:flex;flex-wrap:wrap;gap:8px;margin-bottom:14px;';
    const _buildRecentGrid = () => {
      recentGrid.innerHTML = '';
      const recent = Array.isArray(settings.ciAppBgRecent) ? settings.ciAppBgRecent : [];
      if (!recent.length) {
        const empty = document.createElement('div');
        empty.style.cssText = 'font-size:10px;color:#6e7681;padding:6px 0;';
        empty.textContent = 'No recent images. Apply a URL or file above to add one.';
        recentGrid.appendChild(empty);
        return;
      }
      recent.forEach((item, idx) => {
        const thumb = document.createElement('div');
        thumb.style.cssText = 'position:relative;width:64px;height:64px;border-radius:8px;overflow:hidden;cursor:pointer;border:2px solid #30363d;transition:border-color .15s,transform .12s;flex-shrink:0;';
        thumb.innerHTML = `<div style="position:absolute;inset:0;background-image:url(${item.src});background-size:cover;background-position:center;"></div>`;
        const delBtn = document.createElement('button');
        delBtn.innerHTML = '<i class="fas fa-times" style="font-size:9px;"></i>';
        delBtn.style.cssText = 'position:absolute;top:2px;right:2px;width:18px;height:18px;border-radius:50%;border:none;background:rgba(0,0,0,0.7);color:#fff;cursor:pointer;display:flex;align-items:center;justify-content:center;opacity:0;transition:opacity .15s;z-index:2;';
        thumb.appendChild(delBtn);
        thumb.onmouseenter = () => { thumb.style.borderColor = '#38bdf8'; thumb.style.transform = 'scale(1.06)'; delBtn.style.opacity = '1'; };
        thumb.onmouseleave = () => { thumb.style.borderColor = '#30363d'; thumb.style.transform = ''; delBtn.style.opacity = '0'; };
        thumb.onclick = (e) => {
          if (e.target.closest('button')) return;
          settings.ciAppBgImageUrl = item.src;
          settings.ciAppBgImageKey = null;
          bgUrlInp.value = item.src || '';
          saveSettings(); _refreshBgPreview(item.src); _applyAppearance();
        };
        delBtn.onclick = (e) => {
          e.stopPropagation();
          if (!Array.isArray(settings.ciAppBgRecent)) settings.ciAppBgRecent = [];
          settings.ciAppBgRecent.splice(idx, 1);
          saveSettings(); _buildRecentGrid();
        };
        recentGrid.appendChild(thumb);
      });
    };
    _buildRecentGrid();
    panels.background.appendChild(recentGrid);

    // Helper: add a src to recent images (called on URL apply / file upload)
    const _addToRecent = (src, type) => {
      if (!src) return;
      if (!Array.isArray(settings.ciAppBgRecent)) settings.ciAppBgRecent = [];
      // Remove existing entry with same src
      settings.ciAppBgRecent = settings.ciAppBgRecent.filter(r => r.src !== src);
      settings.ciAppBgRecent.unshift({ src, type: type || 'url', addedAt: Date.now() });
      // Keep max 12 recent items
      if (settings.ciAppBgRecent.length > 12) settings.ciAppBgRecent.length = 12;
      saveSettings(); _buildRecentGrid();
    };

