    panels.effects.appendChild(_mkSliderRow('Panel / Card Corner Radius (px)', 0, 20, 1, settings.ciPanelBorderRadius ?? 8, 'px', v => { settings.ciPanelBorderRadius = v; saveSettings(); _applyAppearance(); }));
