    customFontInp.value = settings.ciWindowFontFamily || '';
    customFontInp.style.cssText = 'flex:1;padding:7px 12px;border-radius:8px;border:1px solid #30363d;background:#161b22;color:#e6edf3;font-size:11px;font-family:inherit;outline:none;';
    const customFontApply = document.createElement('button');
    customFontApply.textContent = 'Apply'; customFontApply.style.cssText = 'padding:7px 14px;border-radius:8px;border:none;background:#38bdf8;color:#0d1117;font-weight:700;cursor:pointer;font-size:11px;font-family:inherit;';
    customFontApply.onclick = () => { settings.ciWindowFontFamily = customFontInp.value.trim() || 'Cascadia Code'; saveSettings(); _applyAppearance(); };
    customFontRow.appendChild(customFontLbl); customFontRow.appendChild(customFontInp); customFontRow.appendChild(customFontApply);
    panels.typography.appendChild(customFontRow);

