    panels.typography.appendChild(_mkSliderRow('Output Line Height', 1.2, 2.5, 0.1, settings.ciAppOutputLineHeight ?? 1.6, '', v => { settings.ciAppOutputLineHeight = v; saveSettings(); _applyAppearance(); }));
    panels.typography.appendChild(_mkSliderRow('Input Padding (px)', 4, 24, 2, settings.ciAppInputPadding ?? 10, 'px', v => { settings.ciAppInputPadding = v; saveSettings(); _applyAppearance(); }));

