    const _mkSizePairRow = (label, wKey, hKey) => {
      const row = _mkRow(label, 'CSS value, e.g. 760px or min(860px,95vw)');
      const wrap = document.createElement('div'); wrap.style.cssText = 'display:flex;gap:6px;flex-shrink:0;';
      const wInp = document.createElement('input'); wInp.type = 'text'; wInp.placeholder = 'Width'; wInp.value = settings[wKey] || ''; wInp.style.cssText = 'width:100px;padding:5px 8px;border-radius:7px;border:1px solid #30363d;background:#161b22;color:#e6edf3;font-size:11px;font-family:monospace;';
      const hInp = document.createElement('input'); hInp.type = 'text'; hInp.placeholder = 'Height'; hInp.value = settings[hKey] || ''; hInp.style.cssText = 'width:100px;padding:5px 8px;border-radius:7px;border:1px solid #30363d;background:#161b22;color:#e6edf3;font-size:11px;font-family:monospace;';
      const applyBtn = document.createElement('button'); applyBtn.textContent = 'Set'; applyBtn.style.cssText = 'padding:5px 12px;border-radius:7px;border:none;background:#38bdf8;color:#0d1117;font-weight:700;cursor:pointer;font-size:11px;font-family:inherit;';
      applyBtn.onclick = () => { if (wInp.value.trim()) settings[wKey] = wInp.value.trim(); if (hInp.value.trim()) settings[hKey] = hInp.value.trim(); saveSettings(); _applyAppearance(); };
      wrap.appendChild(wInp); wrap.appendChild(hInp); wrap.appendChild(applyBtn); row.appendChild(wrap);
      return row;
    };
    panels.layout.appendChild(_mkSizePairRow('Default Size', 'ciWindowDefaultWidth', 'ciWindowDefaultHeight'));
    panels.layout.appendChild(_mkSliderRow('Border Radius (px)', 0, 40, 2, settings.ciWindowBorderRadius ?? 16, 'px', v => { settings.ciWindowBorderRadius = v; saveSettings(); _applyAppearance(); }));

