    panels.animations.appendChild(_mkSelectRow('AC Drop Animation', 'How the autocomplete list appears', [['fade','Fade In'],['slide','Slide Down'],['none','None']], settings.ciAcAnimation || 'fade', v => { settings.ciAcAnimation = v; saveSettings(); }));
