    cssApplyBtn.style.cssText = 'margin-top:8px;padding:7px 16px;border-radius:8px;border:none;background:#38bdf8;color:#0d1117;font-weight:700;cursor:pointer;font-size:11px;font-family:inherit;';
    cssApplyBtn.innerHTML = '<i class="fas fa-play" style="margin-right:5px;"></i>Apply CSS';
