    _userScTitle.style.cssText = 'font-size:9px;color:#58a6ff;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px;display:flex;align-items:center;justify-content:space-between;';
    _userScTitle.innerHTML = `<span><i class="fas fa-user" style="margin-right:4px;"></i>Custom Shortcuts</span>`;
