    _clearLogsBtn.onmouseenter = () => { _clearLogsBtn.style.color = '#f85149'; _clearLogsBtn.style.borderColor = '#f8514944'; };
    _clearLogsBtn.onmouseleave = () => { _clearLogsBtn.style.color = UI.muted; _clearLogsBtn.style.borderColor = UI.border; };
    _clearLogsBtn.onclick = () => { outputPane.innerHTML = ''; const tab = _getActiveTab(); if (tab) tab.outputHTML = ''; };
    logStatsBar.appendChild(_clearLogsBtn);

