    statusBar.innerHTML = `<span id="ci-status-text"><i class="fas fa-circle" style="color:#3fb950; font-size:8px;"></i> Ready</span><span id="ci-syntax-badges" style="display:${settings.ciSyntaxErrorEnabled !== false ? 'flex' : 'none'};align-items:center;gap:8px;margin-left:6px;"><span id="ci-badge-err" style="color:#f85149;display:flex;align-items:center;gap:2px;opacity:0.4;"><i class="fas fa-times-circle" style="font-size:9px;"></i><span>0</span></span><span id="ci-badge-warn" style="color:#d29922;display:flex;align-items:center;gap:2px;opacity:0.4;"><i class="fas fa-exclamation-triangle" style="font-size:9px;"></i><span>0</span></span><span id="ci-badge-info" style="color:#58a6ff;display:flex;align-items:center;gap:2px;opacity:0.4;"><i class="fas fa-info-circle" style="font-size:9px;"></i><span>0</span></span></span><span style="margin-left:auto; opacity:0.6;">Tab/Enter=autocomplete | ↑↓=navigate | Esc=close | Shift+Enter=newline (multi)</span>`;
    win.appendChild(statusBar);

    //  Syntax badge click handlers  toggle error/warning/info levels ────
