      if (!rawOverride) { ciHistory.unshift(raw); if (ciHistory.length > (settings.ciMaxHistory || 100)) ciHistory.length = settings.ciMaxHistory || 100; ciHistIdx = -1; if (!settings.ciKeepInputAfterRun) { cmdInput.value = ''; cmdInput.rows = 1; ghostText.textContent = ''; ghostText.innerHTML = ''; _ghostSuggestion = ''; syntaxOverlay.innerHTML = ''; _errorUnderlay.innerHTML = ''; _syntaxErrors = []; errorStatusBar.style.display = 'none'; cmdInput.style.color = UI.text; } acDrop.style.display = 'none'; docsPanel.style.display = 'none'; }
