            acDrop.innerHTML = `<div style="padding:10px 14px;font-size:11px;color:${UI.muted};"><i class="fas fa-cube" style="margin-right:6px;color:${_libColor2};opacity:0.6;"></i>No commands found for prefix <b>${_pfxStr}:</b></div>`;
            acFilteredEntries = [];
