          _libHdr.innerHTML = `<i class="fas fa-cube" style="font-size:8px;"></i>${_pfxStr}:  ${_libFiltered.length} command${_libFiltered.length !== 1 ? 's' : ''}`;
          acDrop.appendChild(_libHdr);
