        const textToCursor = val.slice(0, cursor);
        // Build effective shortcut maps: user shortcuts WIN over built-ins (user can override)
        const _userSC = {};
        (settings.ciTypingShortcuts || []).forEach(sc => { if (sc.from && sc.to) _userSC[sc.from.toLowerCase()] = sc.to; });
        const _nsMap = Object.assign({}, CI_TYPING_SHORTCUTS_BUILTIN.namespaces, _userSC);
