      uiScanPane.style.display = 'flex';
      dlgHeader.querySelector('#fbTabConsole').style.cssText = `padding:6px 14px; font-size:12px; font-weight:600; cursor:pointer; background:transparent; color:${colors.textSecondary}; border:none;`;
      dlgHeader.querySelector('#fbTabUIScan').style.cssText = 'padding:6px 14px; font-size:12px; font-weight:700; cursor:pointer; background:#6366f1; color:#fff; border:none;';
