    document.body.appendChild(acWrap);

    const cmdRow = document.createElement('div');
    cmdRow.style.cssText = 'display:flex; align-items:center; gap:6px; padding:8px 10px; background:#080d14; border-top:1px solid #21262d; flex-shrink:0;';
