            btn.style.cssText = `display:flex;align-items:center;justify-content:center;gap:6px;padding:7px 8px;border-radius:8px;border:1px solid ${isActive ? _doColors.primary : _doColors.border};background:${isActive ? _doColors.primary + '22' : 'transparent'};color:${isActive ? _doColors.primary : _doColors.textSecondary};cursor:pointer;font-size:10px;font-weight:800;`;
            btn.innerHTML = `<i class="${icon}"></i>${label}`;
