            const isActive = curOrder === key;
            const btn = document.createElement('button');
            btn.style.cssText = `display:flex; align-items:center; gap:6px; padding:7px 10px; border-radius:8px; border:1px solid ${isActive ? _doColors.primary : _doColors.border}; background:${isActive ? _doColors.primary + '22' : 'transparent'}; color:${isActive ? _doColors.primary : _doColors.textSecondary}; cursor:pointer; font-size:10px; font-weight:${isActive ? 800 : 600}; text-align:left; transition:all 0.15s;`;
            btn.innerHTML = `<i class="${icon}"></i>${label}`;
