              const colBtn = document.createElement('button');
              colBtn.style.cssText = `flex:1; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:5px; padding:8px 3px; border-radius:8px; border:1px solid ${isActive ? _doColors.primary : _doColors.border}; background:${isActive ? _doColors.primary + '22' : 'transparent'}; color:${isActive ? _doColors.primary : _doColors.textSecondary}; cursor:pointer; font-size:11px; font-weight:${isActive ? 800 : 600}; transition:all 0.15s;`;
