      xhrSection.content.appendChild(xhrNote);

      const { row: xhrToggleRow, input: xhrToggleInput } = createSettingsToggleRow({
        labelText: 'Enable XHR Intercept Mode',
        icon: 'fa-bolt',
        tooltip: 'When enabled, this mode rewrites tasks query request/response and turns off Inject On DOM + Safe View.',
        checked: !!settings.xhrInterceptEnabled,
        fontSize: '14px',
        textColor: colors.text,
        settingKey: 'xhrInterceptEnabled'
      });
      xhrToggleInput.onchange = () => {
        settings.xhrInterceptEnabled = xhrToggleInput.checked;
        enforceXhrInterceptModeState();
        saveSettings();
        tensorInterceptLog('info', `XHR Intercept mode ${settings.xhrInterceptEnabled ? 'enabled' : 'disabled'}`, { source: 'settings' });
        injectBlockedMediaIntoDom();
        updateUI();
      };
      xhrSection.content.appendChild(xhrToggleRow);

      // This API-action observer remains independent from optional response rewriting.
      const itemDeletionSection = createCollapsibleSection('Item deletion actions', 'fa-trash-can', true);
      const itemDeletionNote = document.createElement('div');
      itemDeletionNote.style.cssText = `padding:10px 12px;margin-bottom:10px;border:1px solid ${colors.primary}44;border-radius:10px;background:${colors.primary}12;color:${colors.textSecondary};font-size:12px;line-height:1.5;`;
      itemDeletionNote.innerHTML = '<strong style="color:'+colors.text+'"><i class="fas fa-code-branch"></i> Intercept confirmed Tensor deletions</strong><br>Choose what FI should remove only after Tensor returns a successful <code>delete_task</code> response.';
      itemDeletionSection.content.appendChild(itemDeletionNote);
      const tensorDeleteSyncCard = document.createElement('div');
      tensorDeleteSyncCard.dataset.settingKey = 'tensorTaskDeleteSyncMode';
      tensorDeleteSyncCard.style.cssText = 'display:grid;grid-template-columns:minmax(0,1fr) minmax(230px,320px);align-items:center;gap:14px;padding:12px 14px;margin-top:10px;border:1px solid '+colors.border+';border-radius:12px;background:linear-gradient(135deg,'+colors.bgSecondary+','+colors.bg+');color:'+colors.text+';';
      const tensorDeleteSyncInfo = document.createElement('div');
      tensorDeleteSyncInfo.style.cssText = 'min-width:0;display:flex;gap:10px;align-items:flex-start;';
      tensorDeleteSyncInfo.innerHTML = '<span style="width:30px;height:30px;border-radius:9px;display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;background:'+colors.primary+'1f;color:'+colors.primary+';border:1px solid '+colors.primary+'55;"><i class="fas fa-trash-arrow-up"></i></span><span style="min-width:0;"><span style="display:flex;align-items:center;gap:7px;flex-wrap:wrap;font-size:13px;font-weight:800;color:'+colors.text+';">Tensor task deletion sync <span data-fi-delete-sync-status style="font-size:9px;padding:2px 7px;border-radius:999px;border:1px solid '+colors.border+';color:'+colors.textSecondary+';background:'+colors.panel+';"></span></span><small style="display:block;margin-top:4px;color:'+colors.textSecondary+';line-height:1.45;">After Tensor confirms <code>delete_task</code> success, remove matching task IDs and their FI Item records. This observer works even when response rewriting is off.</small></span>';
      const tensorDeleteSyncControl = document.createElement('div');
      tensorDeleteSyncControl.style.cssText = 'display:grid;gap:5px;min-width:0;';
      const tensorDeleteSyncSelect = document.createElement('select');
      tensorDeleteSyncSelect.setAttribute('data-fi-setting', 'tensorTaskDeleteSyncMode');
      tensorDeleteSyncSelect.setAttribute('aria-label', 'Tensor task deletion synchronization mode');
      tensorDeleteSyncSelect.style.cssText = 'width:100%;padding:9px 11px;border-radius:9px;border:1px solid '+colors.border+';background:'+(colors.panel || colors.bg)+';color:'+colors.text+';font:inherit;font-size:12px;font-weight:700;cursor:pointer;';
      [['off','Off — keep FI records'],['local','Delete from FI locally (default)'],['services','Delete from FI + connected services']].forEach(([value, label]) => {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = label;
        tensorDeleteSyncSelect.appendChild(option);
      });
      const tensorDeleteSyncHelp = document.createElement('small');
      tensorDeleteSyncHelp.style.cssText = 'font-size:10px;line-height:1.4;color:'+colors.textSecondary+';';
      const renderTensorDeleteSyncMode = () => {
        const mode = ['off','local','services'].includes(String(settings.tensorTaskDeleteSyncMode || '').toLowerCase()) ? String(settings.tensorTaskDeleteSyncMode).toLowerCase() : 'local';
        tensorDeleteSyncSelect.value = mode;
        const badge = tensorDeleteSyncInfo.querySelector('[data-fi-delete-sync-status]');
        if (badge) badge.textContent = mode === 'off' ? 'OFF' : mode === 'services' ? 'FI + HOST' : 'LOCAL';
        tensorDeleteSyncHelp.textContent = mode === 'services' ? 'Also asks FI Host to remove matching SQLite records and FI-owned files when the Host extension is connected.' : mode === 'local' ? 'Removes matching FI browser records and IndexedDB data. FI Host data is left unchanged.' : 'Tensor deletions will not change any FI records.';
      };
      tensorDeleteSyncSelect.onchange = () => {
        settings.tensorTaskDeleteSyncMode = tensorDeleteSyncSelect.value;
        saveSettings();
        renderTensorDeleteSyncMode();
        showToast('Tensor task deletion sync updated.', 'success');
      };
      tensorDeleteSyncControl.append(tensorDeleteSyncSelect, tensorDeleteSyncHelp);
      tensorDeleteSyncCard.append(tensorDeleteSyncInfo, tensorDeleteSyncControl);
      xhrSection.content.appendChild(tensorDeleteSyncCard);
      renderTensorDeleteSyncMode();

      //  DOM Patch after async URL resolution ────────────────────────────
      const { row: xhrDomPatchRow, input: xhrDomPatchInput } = createSettingsToggleRow({
        labelText: 'DOM Patch  replace forbidden URLs in live page',
        icon: 'fa-paintbrush',
        tooltip: 'After async bypass URL resolution, directly replace forbidden.jpg <img> elements and CSS backgrounds in the live page DOM. Fixes items that React already rendered before the async URL arrived.\n\n⚡ Requires XHR Intercept Mode to be enabled.',
        checked: !!settings.xhrInterceptDomPatch,
        fontSize: '13px',
        textColor: colors.text,
        settingKey: 'xhrInterceptDomPatch'
      });
      xhrDomPatchRow.style.opacity = settings.xhrInterceptEnabled ? '1' : '0.45';
      xhrDomPatchRow.title = settings.xhrInterceptEnabled ? '' : 'Enable XHR Intercept Mode above to use this feature.';
      xhrDomPatchInput.onchange = () => {
        settings.xhrInterceptDomPatch = xhrDomPatchInput.checked;
        saveSettings();
        tensorInterceptLog('info', `DOM patch after async resolve: ${settings.xhrInterceptDomPatch ? 'ON' : 'OFF'}`, { source: 'settings' });
      };
      xhrSection.content.appendChild(xhrDomPatchRow);

      //  Verbose XHR Trace Logging ────────────────────────────────────────
      const { row: xhrTraceRow, input: xhrTraceInput } = createSettingsToggleRow({
        labelText: 'Verbose XHR Trace Logging (console)',
        icon: 'fa-terminal',
        tooltip: 'Emit color-coded, per-item trace logs to the browser console for every XHR intercept event: 🟢 hit, 🔴 miss, 🟡 async resolve, 🔵 ok, 🟣 DOM patch. Useful for debugging. Disable in production.\n\n⚡ Requires XHR Intercept Mode to be enabled.',
        checked: !!settings.xhrInterceptTraceLog,
        fontSize: '13px',
        textColor: colors.text,
        settingKey: 'xhrInterceptTraceLog'
      });
      xhrTraceRow.style.opacity = settings.xhrInterceptEnabled ? '1' : '0.45';
      xhrTraceRow.title = settings.xhrInterceptEnabled ? '' : 'Enable XHR Intercept Mode above to use this feature.';
      xhrTraceInput.onchange = () => {
        settings.xhrInterceptTraceLog = xhrTraceInput.checked;
        saveSettings();
        tensorInterceptLog('info', `XHR verbose trace logging: ${settings.xhrInterceptTraceLog ? 'ON' : 'OFF'}`, { source: 'settings' });
        if (settings.xhrInterceptTraceLog) {
          if (!settings.xhrInterceptEnabled) {
            showToast('XHR Intercept Mode must be enabled for trace logging to work. Enable it above.', 'warning', 4500);
          } else {
            _xhrTraceLog('ok', '[XHR Trace] Verbose trace logging ENABLED  watching for bypass events…');
          }
        }
      };
      xhrSection.content.appendChild(xhrTraceRow);

      //  Pause Page Loading Until Bypass URLs Ready ───────────────────────
      const { row: xhrPauseRow, input: xhrPauseInput } = createSettingsToggleRow({
        labelText: 'Pause page loading until bypass URLs ready',
        icon: 'fa-pause-circle',
        tooltip: 'When enabled, the XHR tasks-query response is held and the page\'s framework handler is delayed until all bypass URLs are fully resolved asynchronously. This ensures React renders with real URLs instead of forbidden.jpg. Adds a brief delay on first uncached load.\n\n⚡ Requires XHR Intercept Mode to be enabled.',
        checked: !!settings.xhrInterceptPauseResponse,
        fontSize: '13px',
        textColor: colors.text,
        settingKey: 'xhrInterceptPauseResponse'
      });
      xhrPauseRow.style.opacity = settings.xhrInterceptEnabled ? '1' : '0.45';
      xhrPauseRow.title = settings.xhrInterceptEnabled ? '' : 'Enable XHR Intercept Mode above to use this feature.';
      xhrPauseInput.onchange = () => {
        settings.xhrInterceptPauseResponse = xhrPauseInput.checked;
        saveSettings();
        tensorInterceptLog('info', `XHR pause-response mode: ${settings.xhrInterceptPauseResponse ? 'ON' : 'OFF'}`, { source: 'settings' });
        if (settings.xhrInterceptPauseResponse && !settings.xhrInterceptEnabled) {
          showToast('XHR Intercept Mode must be enabled for pause-response to work. Enable it above.', 'warning', 4500);
        }
      };
      xhrSection.content.appendChild(xhrPauseRow);

      //  On-Load Bypass URL Refresh Sub-Section ────────────────────────────
      const refreshSubSection = document.createElement('div');
      refreshSubSection.style.cssText = `margin-top:12px; border:1px solid rgba(34,197,94,0.25); border-radius:12px; overflow:hidden;`;

      const refreshSubHeader = document.createElement('div');
      refreshSubHeader.style.cssText = `display:flex; align-items:center; justify-content:space-between; padding:9px 14px; background:rgba(34,197,94,0.08); cursor:pointer; user-select:none;`;
      const refreshSubHeaderLeft = document.createElement('div');
      refreshSubHeaderLeft.style.cssText = `display:flex; align-items:center; gap:8px; font-size:13px; font-weight:700; color:#22c55e;`;
      refreshSubHeaderLeft.innerHTML = `<i class="fas fa-shield-halved"></i> On-Load Bypass URL Refresh`;
      const refreshSubChevron = document.createElement('i');
      refreshSubChevron.className = 'fas fa-chevron-down';
      refreshSubChevron.style.cssText = `font-size:11px; color:${colors.textSecondary}; transition:transform 0.2s;`;
      refreshSubHeader.appendChild(refreshSubHeaderLeft);
      refreshSubHeader.appendChild(refreshSubChevron);

      const refreshSubContent = document.createElement('div');
      refreshSubContent.style.cssText = `padding:12px; display:flex; flex-direction:column; gap:8px;`;

      let refreshSubOpen = true;
      refreshSubHeader.onclick = () => {
        refreshSubOpen = !refreshSubOpen;
        refreshSubContent.style.display = refreshSubOpen ? 'flex' : 'none';
        refreshSubChevron.style.transform = refreshSubOpen ? '' : 'rotate(-90deg)';
      };

      // Info note
      const refreshNote = document.createElement('div');
      refreshNote.style.cssText = 'background:rgba(34,197,94,0.08);border:1px solid rgba(34,197,94,0.25);border-radius:8px;padding:8px 10px;font-size:11px;color:#94a3b8;line-height:1.5;';
      refreshNote.innerHTML = '<strong style="color:#22c55e;"><i class="fas fa-info-circle"></i> Smart API Protection</strong><br>Controls how aggressively bypass URLs are refreshed on page load. Reduces unnecessary API calls that could flag your account.';
      refreshSubContent.appendChild(refreshNote);

      // Less API Requests toggle
      const { row: lessApiRow, input: lessApiInput } = createSettingsToggleRow({
        labelText: 'Enable Less API Requests (Recommended)',
        icon: 'fa-shield-halved',
        tooltip: 'Reduce API calls by skipping expired tasks, stopping retries for repeatedly failed items, and respecting failure thresholds. Highly recommended to prevent account flagging.',
        checked: settings.lessApiRequests !== false,
        fontSize: '13px',
        textColor: colors.text,
        settingKey: 'lessApiRequests'
      });
      lessApiInput.onchange = () => {
        if (!lessApiInput.checked) {
          // Show warning before disabling
          showConfirmDialog(
            '⚠️ Disabling Less API Requests is a BAD idea!\n\n' +
            'This will cause aggressive retries to Tensor\'s backend for broken/expired tasks, which can:\n' +
            '• Get your account flagged or rate-limited\n' +
            '• Spam Tensor\'s servers with unnecessary requests\n' +
            '• Waste bandwidth on items that will never resolve\n\n' +
            'Are you sure you want to disable this protection?',
            () => {
              settings.lessApiRequests = false;
              saveSettings();
              showToast('Less API Requests disabled  your account may be at risk of rate limiting.', 'warning', 6000);
            },
            () => {
              lessApiInput.checked = true;
            }
          );
        } else {
          settings.lessApiRequests = true;
          saveSettings();
          showToast('Less API Requests enabled  your account is protected.', 'success');
        }
      };
      refreshSubContent.appendChild(lessApiRow);

      // Max failures threshold
      const failureRow = document.createElement('div');
      failureRow.style.cssText = `display:flex;align-items:center;gap:10px;padding:6px 0;`;
      failureRow.innerHTML = `
        <span style="font-size:12px;color:${colors.text};flex:1;"><i class="fas fa-rotate" style="color:#f87171;margin-right:6px;width:14px;"></i>Max retry failures before skip</span>
      `;
      const failureInput = document.createElement('input');
      failureInput.type = 'number';
      failureInput.min = '1';
      failureInput.max = '20';
      failureInput.value = String(settings.bypassRefreshMaxFailures || 3);
      failureInput.style.cssText = 'width:60px;padding:5px 8px;border-radius:6px;border:1px solid #475569;background:#1e293b;color:#f1f5f9;font-size:12px;text-align:center;';
      failureInput.onchange = () => {
        const val = Math.max(1, Math.min(20, parseInt(failureInput.value, 10) || 3));
        failureInput.value = String(val);
        settings.bypassRefreshMaxFailures = val;
        saveSettings();
      };
      failureRow.appendChild(failureInput);
      refreshSubContent.appendChild(failureRow);

      // Skip expired tasks toggle
      const { row: skipExpiredRow, input: skipExpiredInput } = createSettingsToggleRow({
        labelText: 'Skip expired tasks on refresh',
        icon: 'fa-clock',
        tooltip: 'Do not attempt to refresh bypass URLs for tasks whose expireAt timestamp has passed.',
        checked: settings.bypassRefreshSkipExpiredTasks !== false,
        fontSize: '12px',
        textColor: colors.text,
        settingKey: 'bypassRefreshSkipExpiredTasks'
      });
      skipExpiredInput.onchange = () => {
        settings.bypassRefreshSkipExpiredTasks = skipExpiredInput.checked;
        saveSettings();
      };
      refreshSubContent.appendChild(skipExpiredRow);

      // Protective Refresh (smart load control) ──────────────────────────
      const protectiveDiv = document.createElement('div');
      protectiveDiv.style.cssText = `margin-top:6px; padding:10px 12px; border-radius:10px; border:1px solid rgba(99,102,241,0.28); background:rgba(99,102,241,0.07); display:flex; flex-direction:column; gap:8px;`;

      const protectiveTitle = document.createElement('div');
      protectiveTitle.style.cssText = `font-size:12px; font-weight:700; color:#a5b4fc; display:flex; align-items:center; gap:6px;`;
      protectiveTitle.innerHTML = `<i class="fas fa-shield"></i> Protective Refresh Mode`;
      protectiveDiv.appendChild(protectiveTitle);

      const protectiveInfo = document.createElement('div');
      protectiveInfo.style.cssText = `font-size:10px; color:${colors.textSecondary}; line-height:1.5;`;
      protectiveInfo.innerHTML = `Limit how many bypass URLs are checked/refreshed on page load. Startup is hard-capped at ${STARTUP_ITEM_HARD_CAP} newest items; older items stay stored and refresh lazily when they actually appear in an XHR response.`;
      protectiveDiv.appendChild(protectiveInfo);

      // Max on-load limit row
      const loadLimitRow = document.createElement('div');
      loadLimitRow.style.cssText = `display:flex; align-items:center; gap:10px; padding:4px 0;`;
      loadLimitRow.innerHTML = `<span style="font-size:12px;color:${colors.text};flex:1;"><i class="fas fa-list-ol" style="color:#a5b4fc;margin-right:6px;width:14px;"></i>Max items checked/refreshed on load <span style="font-size:10px;color:${colors.textSecondary};">(1-${STARTUP_ITEM_HARD_CAP}, newest first)</span></span>`;
      const loadLimitInput = document.createElement('input');
      loadLimitInput.type = 'number';
      loadLimitInput.min = '1';
      loadLimitInput.max = String(STARTUP_ITEM_HARD_CAP);
      loadLimitInput.step = '50';
      loadLimitInput.value = String(getStartupRecheckItemLimit());
      loadLimitInput.style.cssText = `width:72px; padding:5px 8px; border-radius:6px; border:1px solid #4c51a0; background:#1e1e3f; color:#e0e7ff; font-size:12px; text-align:center;`;
      loadLimitInput.onchange = () => {
        const val = Math.max(1, Math.min(STARTUP_ITEM_HARD_CAP, parseInt(loadLimitInput.value, 10) || STARTUP_RECHECK_DEFAULT_CAP));
        loadLimitInput.value = String(val);
        settings.recheckLinksOnLoadMax = val;
        saveSettings();
        showToast(`On-load refresh limit set to newest ${val} item(s)`, 'info');
      };
      loadLimitRow.appendChild(loadLimitInput);
      protectiveDiv.appendChild(loadLimitRow);

      const startupTuneRow = document.createElement('div');
      startupTuneRow.style.cssText = `display:grid;grid-template-columns:1fr auto 1fr auto;gap:8px;align-items:center;padding:4px 0;`;
      startupTuneRow.innerHTML = `
        <span style="font-size:11px;color:${colors.textSecondary};"><i class="fas fa-clock" style="color:#a5b4fc;margin-right:5px;"></i>Startup delay (ms)</span>
        <input data-fi-startup-recheck-delay type="number" min="0" max="30000" step="500" value="${escapeHtml(String(settings.startupRecheckDelayMs ?? defaultSettings.startupRecheckDelayMs))}" style="width:76px;padding:5px 7px;border-radius:6px;border:1px solid #4c51a0;background:#1e1e3f;color:#e0e7ff;font-size:11px;text-align:center;">
        <span style="font-size:11px;color:${colors.textSecondary};"><i class="fas fa-layer-group" style="color:#a5b4fc;margin-right:5px;"></i>Batch size</span>
        <input data-fi-startup-recheck-batch type="number" min="1" max="12" step="1" value="${escapeHtml(String(settings.startupRecheckBatchSize ?? defaultSettings.startupRecheckBatchSize))}" style="width:58px;padding:5px 7px;border-radius:6px;border:1px solid #4c51a0;background:#1e1e3f;color:#e0e7ff;font-size:11px;text-align:center;">
      `;
      startupTuneRow.querySelector('[data-fi-startup-recheck-delay]').onchange = (ev) => {
        settings.startupRecheckDelayMs = Math.min(30000, Math.max(0, Math.floor(Number(ev.target.value) || 0)));
        ev.target.value = String(settings.startupRecheckDelayMs);
        saveSettings();
      };
      startupTuneRow.querySelector('[data-fi-startup-recheck-batch]').onchange = (ev) => {
        settings.startupRecheckBatchSize = Math.min(12, Math.max(1, Math.floor(Number(ev.target.value) || 6)));
        ev.target.value = String(settings.startupRecheckBatchSize);
        saveSettings();
      };
      protectiveDiv.appendChild(startupTuneRow);

      const { row: targetedSlotsRow, input: targetedSlotsInput } = createSettingsToggleRow({
        labelText: 'Targeted slots refresh (latest-only)',
        icon: 'fa-bullseye',
        tooltip: 'When enabled, on-load refresh checks only the newest startup window. Older cached items stay stored and refresh lazily when needed. Recommended for large histories.',
        checked: !!settings.targetedSlotsRefreshOnLoad,
        fontSize: '12px',
        textColor: colors.text,
        settingKey: 'targetedSlotsRefreshOnLoad'
      });
      targetedSlotsInput.onchange = () => {
        settings.targetedSlotsRefreshOnLoad = targetedSlotsInput.checked;
        saveSettings();
        showToast(`Targeted slots refresh ${targetedSlotsInput.checked ? 'enabled' : 'disabled'}`, 'info');
      };
      protectiveDiv.appendChild(targetedSlotsRow);

      // Lazy XHR bypass toggle
      const { row: lazyXhrRow, input: lazyXhrInput } = createSettingsToggleRow({
        labelText: 'Lazy XHR bypass refresh',
        icon: 'fa-bolt',
        tooltip: 'When a tasks/query XHR response arrives, automatically refresh any expired or missing bypass URLs for items in that response, right before the page receives the data. Deferred items from the on-load limit are resolved this way.',
        checked: settings.lazyBypassOnXhrQuery !== false,
        fontSize: '12px',
        textColor: colors.text,
      });
      lazyXhrInput.onchange = () => {
        settings.lazyBypassOnXhrQuery = lazyXhrInput.checked;
        saveSettings();
        showToast(`Lazy XHR bypass refresh ${lazyXhrInput.checked ? 'enabled' : 'disabled'}`, 'info');
      };
      protectiveDiv.appendChild(lazyXhrRow);

      refreshSubContent.appendChild(protectiveDiv);

      // Analysis stats
      const analysisStats = document.createElement('div');
      analysisStats.style.cssText = 'padding:8px 10px;background:rgba(99,102,241,0.08);border:1px solid rgba(99,102,241,0.18);border-radius:8px;font-size:11px;color:#94a3b8;display:flex;gap:16px;flex-wrap:wrap;';
      const nrCount = getNonRegainableCount();
      const failCount = Object.keys(bypassAnalysisCache).length;
      analysisStats.innerHTML = `
        <span><i class="fas fa-ban" style="color:#f87171;"></i> <strong>${nrCount}</strong> non-regainable</span>
        <span><i class="fas fa-chart-bar" style="color:#6366f1;"></i> <strong>${failCount}</strong> tracked failures</span>
      `;
      const clearAnalysisBtn = document.createElement('button');
      clearAnalysisBtn.style.cssText = 'margin-left:auto;background:transparent;border:1px solid rgba(239,68,68,0.3);color:#f87171;border-radius:6px;padding:3px 8px;font-size:10px;cursor:pointer;';
      clearAnalysisBtn.innerHTML = '<i class="fas fa-eraser"></i> Reset Analysis';
      clearAnalysisBtn.onclick = () => {
        showConfirmDialog('Clear all bypass failure tracking data?\nThis will reset failure counts for all items, allowing them to be retried again.', () => {
          clearAllBypassAnalysis();
          showToast('Bypass analysis data cleared', 'success');
          analysisStats.querySelector('strong:nth-of-type(2)').textContent = '0';
        });
      };
      analysisStats.appendChild(clearAnalysisBtn);
      refreshSubContent.appendChild(analysisStats);

      refreshSubSection.appendChild(refreshSubHeader);
      refreshSubSection.appendChild(refreshSubContent);
      xhrSection.content.appendChild(refreshSubSection);

      // OnClear expired item cleanup ───────────────────────────────────────
      const onClearSection = document.createElement('div');
      onClearSection.dataset.fiXhrOnClear = 'true';
      onClearSection.style.cssText = 'margin-top:12px;border:1px solid rgba(248,113,113,.28);border-radius:12px;overflow:hidden;';
      const onClearHeader = document.createElement('div');
      onClearHeader.style.cssText = 'display:flex;align-items:center;justify-content:space-between;padding:9px 14px;background:rgba(248,113,113,.08);cursor:pointer;user-select:none;';
      onClearHeader.innerHTML = `<div style="display:flex;align-items:center;gap:8px;font-size:13px;font-weight:800;color:#fb7185;"><i class="fas fa-broom"></i> OnClear · Expired Items <span style="padding:1px 6px;border-radius:999px;background:rgba(248,113,113,.13);font-size:8px;letter-spacing:.4px;">ON LOAD</span></div><i data-chevron class="fas fa-chevron-down" style="font-size:11px;color:${colors.textSecondary};transition:transform .2s;"></i>`;
      const onClearContent = document.createElement('div');
      onClearContent.style.cssText = 'padding:12px;display:flex;flex-direction:column;gap:8px;';
      let onClearOpen = localStorage.getItem('section_xhr_onclear_expired') !== 'false';
      const syncOnClearOpen = () => {
        onClearContent.style.display = onClearOpen ? 'flex' : 'none';
        onClearHeader.querySelector('[data-chevron]').style.transform = onClearOpen ? '' : 'rotate(-90deg)';
      };
      onClearHeader.onclick = () => { onClearOpen = !onClearOpen; localStorage.setItem('section_xhr_onclear_expired', String(onClearOpen)); syncOnClearOpen(); };
      syncOnClearOpen();

      const onClearNote = document.createElement('div');
      onClearNote.style.cssText = 'padding:9px 10px;border-radius:9px;border:1px solid rgba(248,113,113,.23);background:rgba(248,113,113,.07);font-size:10.5px;line-height:1.5;color:#cbd5e1;';
      onClearNote.innerHTML = '<strong style="color:#fda4af;"><i class="fas fa-database"></i> Batch cleanup before refresh</strong><br>On page load, FI removes only records with a known task expiry in the past. Unknown expiry is preserved. Cleanup updates task, account, FITAG, link, analysis, Items and Data Control indexes before On-Load URL refresh begins.';
      onClearContent.appendChild(onClearNote);

      const { row: onClearEnabledRow } = createSettingsToggleRow({
        labelText: 'Remove expired cached items on page load',
        icon: 'fa-trash-clock',
        tooltip: 'Opt-in destructive cleanup. Runs once per page load after IndexedDB hydration and before bypass URL refresh.',
        checked: settings.onClearExpiredItemsEnabled === true,
        settingKey: 'onClearExpiredItemsEnabled',
        onChange: (event) => {
          settings.onClearExpiredItemsEnabled = event.target.checked;
          saveSettings();
          showToast(`OnClear expired cleanup ${event.target.checked ? 'enabled for the next page load' : 'disabled'}`, event.target.checked ? 'success' : 'info');
        }
      });
      onClearContent.appendChild(onClearEnabledRow);

      const onClearLimitRow = document.createElement('div');
      onClearLimitRow.style.cssText = `display:flex;align-items:center;gap:10px;padding:7px 0;color:${colors.text};`;
      onClearLimitRow.innerHTML = `<div style="flex:1;min-width:0;"><div style="font-size:12px;font-weight:800;"><i class="fas fa-list-check" style="color:#fb7185;margin-right:6px;"></i>Maximum cached items checked</div><div style="font-size:9.5px;color:${colors.textSecondary};margin-top:2px;">1–5,000 unique items per cleanup; oldest known expiries are evaluated first.</div></div>`;
      const onClearLimitInput = document.createElement('input');
      onClearLimitInput.type = 'number'; onClearLimitInput.min = '1'; onClearLimitInput.max = '5000'; onClearLimitInput.step = '50';
      onClearLimitInput.value = String(settings.onClearExpiredItemsMaxCheck || 500);
      onClearLimitInput.style.cssText = 'width:82px;padding:6px 8px;border-radius:7px;border:1px solid rgba(248,113,113,.35);background:#1e293b;color:#f8fafc;font-size:11px;text-align:center;';
      onClearLimitInput.onchange = () => {
        settings.onClearExpiredItemsMaxCheck = Math.min(5000, Math.max(1, Math.floor(Number(onClearLimitInput.value) || 500)));
        onClearLimitInput.value = String(settings.onClearExpiredItemsMaxCheck); saveSettings();
      };
      onClearLimitRow.appendChild(onClearLimitInput); onClearContent.appendChild(onClearLimitRow);

      const { row: onClearNotifyRow } = createSettingsToggleRow({
        labelText: 'Show cleanup result notification', icon: 'fa-bell',
        tooltip: 'Show removed item/task counts and estimated metadata bytes freed after automatic OnClear.',
        checked: settings.onClearExpiredItemsNotify !== false, settingKey: 'onClearExpiredItemsNotify',
        onChange: event => { settings.onClearExpiredItemsNotify = event.target.checked; saveSettings(); }
      });
      onClearContent.appendChild(onClearNotifyRow);

      const { row: onClearSavedRow } = createSettingsToggleRow({
        labelText: 'Also remove explicitly saved FI Library media', icon: 'fa-photo-film',
        tooltip: 'Destructive: also delete matching copies saved deliberately in FI Items Library. Disabled by default so durable user saves remain available.',
        checked: settings.onClearExpiredItemsRemoveSavedMedia === true, settingKey: 'onClearExpiredItemsRemoveSavedMedia',
        onChange: event => {
          settings.onClearExpiredItemsRemoveSavedMedia = event.target.checked; saveSettings();
          if (event.target.checked) showToast('OnClear will also delete matching saved FI Library media.', 'warning', 4200);
        }
      });
      onClearContent.appendChild(onClearSavedRow);

      const runOnClearBtn = document.createElement('button');
      runOnClearBtn.className = 'bypass-btn bypass-btn-secondary';
      runOnClearBtn.style.cssText = 'align-self:flex-start;width:auto;padding:7px 11px;border-color:rgba(248,113,113,.35);color:#fda4af;';
      runOnClearBtn.innerHTML = '<i class="fas fa-broom"></i> Run OnClear now';
      runOnClearBtn.onclick = async () => {
        if (!confirm(`Check up to ${settings.onClearExpiredItemsMaxCheck || 500} cached items and permanently remove records whose known task expiry has passed?`)) return;
        runOnClearBtn.disabled = true; runOnClearBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Cleaning…';
        try { await runOnClearExpiredItems({ reason: 'manual' }); }
        finally { runOnClearBtn.disabled = false; runOnClearBtn.innerHTML = '<i class="fas fa-broom"></i> Run OnClear now'; }
      };
      onClearContent.appendChild(runOnClearBtn);
      onClearSection.append(onClearHeader, onClearContent);
      xhrSection.content.appendChild(onClearSection);

      //  Canvas Support Sub-Section ────────────────────────────────────────
      const canvasSubSection = document.createElement('div');
      canvasSubSection.style.cssText = `margin-top:12px; border:1px solid rgba(56,189,248,0.25); border-radius:12px; overflow:hidden;`;

      const canvasSubHeader = document.createElement('div');
      canvasSubHeader.style.cssText = `display:flex; align-items:center; justify-content:space-between; padding:9px 14px; background:rgba(56,189,248,0.08); cursor:pointer; user-select:none;`;
      const canvasSubHeaderLeft = document.createElement('div');
      canvasSubHeaderLeft.style.cssText = `display:flex; align-items:center; gap:8px; font-size:13px; font-weight:700; color:${colors.primary || '#38bdf8'};`;
      canvasSubHeaderLeft.innerHTML = `<i class="fas fa-palette"></i> Canvas Support <span id="canvasDebugBadgeInline" style="display:${settings.canvasDebugBadge ? 'inline-flex' : 'none'}; align-items:center; background:rgba(251,191,36,0.22); color:#fbbf24; font-size:10px; font-weight:700; padding:1px 7px; border-radius:20px; margin-left:4px;">DEBUG</span>`;
      const canvasSubChevron = document.createElement('i');
      canvasSubChevron.className = 'fas fa-chevron-down';
      canvasSubChevron.style.cssText = `font-size:11px; color:${colors.textSecondary}; transition:transform 0.2s;`;
      canvasSubHeader.appendChild(canvasSubHeaderLeft);
      canvasSubHeader.appendChild(canvasSubChevron);

      const canvasSubContent = document.createElement('div');
      canvasSubContent.style.cssText = `padding:12px; display:flex; flex-direction:column; gap:8px;`;
      const canvasSubSectionKey = 'section_canvas_support_sub';
      let canvasSubOpen = localStorage.getItem(canvasSubSectionKey) !== 'false';
      if (!canvasSubOpen) canvasSubContent.style.display = 'none';
      canvasSubChevron.style.transform = canvasSubOpen ? 'rotate(0deg)' : 'rotate(-90deg)';
      canvasSubHeader.onclick = () => {
        canvasSubOpen = !canvasSubOpen;
        canvasSubContent.style.display = canvasSubOpen ? 'flex' : 'none';
        canvasSubChevron.style.transform = canvasSubOpen ? 'rotate(0deg)' : 'rotate(-90deg)';
        localStorage.setItem(canvasSubSectionKey, String(canvasSubOpen));
      };

      canvasSubSection.appendChild(canvasSubHeader);
      canvasSubSection.appendChild(canvasSubContent);
      xhrSection.content.appendChild(canvasSubSection);

      // enableCanvasSupport toggle
      const { row: canvasSupportRow, input: canvasSupportInput } = createSettingsToggleRow({
        labelText: 'Enable Canvas support (canvas.tensor.art)',
        icon: 'fa-palette',
        tooltip: 'Continuously intercepts /canvas/v1/canvas/update, injects config-driven welcome content, and tracks Canvas projects/media. Requires XHR Intercept mode.',
        checked: !!settings.enableCanvasSupport,
        fontSize: '13px',
        textColor: colors.text,
        settingKey: 'enableCanvasSupport'
      });
      canvasSupportInput.onchange = () => {
        settings.enableCanvasSupport = canvasSupportInput.checked;
        if (settings.enableCanvasSupport && !settings.xhrInterceptEnabled) {
          const ok = confirm('Canvas support requires XHR Interception. Enable XHR now and disable DOM/Safe View injection?');
          if (ok) {
            settings.xhrInterceptEnabled = true;
            enforceXhrInterceptModeState();
            showToast('XHR Interception enabled for Canvas support.', 'success');
          } else {
            showToast('Canvas support is enabled but will not run until XHR Interception is enabled.', 'warning');
          }
        }
        saveSettings();
        setTimeout(updateUI, 0);
      };
      canvasSubContent.appendChild(canvasSupportRow);

      // canvasWelcomeInjectEnabled toggle
      const { row: canvasWelcomeRow, input: canvasWelcomeInput } = createSettingsToggleRow({
        labelText: 'Inject welcome content into Canvas',
        icon: 'fa-comment-dots',
        tooltip: 'When enabled, applies the welcome text/template from canvas remote config into new Canvas sessions.',
        checked: !!settings.canvasWelcomeInjectEnabled,
        fontSize: '13px',
        textColor: colors.text
      });
      canvasWelcomeInput.onchange = () => {
        settings.canvasWelcomeInjectEnabled = canvasWelcomeInput.checked;
        saveSettings();
        tensorInterceptLog('info', `Canvas welcome inject ${settings.canvasWelcomeInjectEnabled ? 'enabled' : 'disabled'}`, { source: 'settings' });
      };
      canvasSubContent.appendChild(canvasWelcomeRow);

      // canvasShowProjectCover toggle
      const { row: canvasCoverRow, input: canvasCoverInput } = createSettingsToggleRow({
        labelText: 'Show project cover image in Projects section',
        icon: 'fa-image',
        tooltip: 'When enabled, shows the most recent media thumbnail as a cover on each canvas project card.',
        checked: !!settings.canvasShowProjectCover,
        fontSize: '13px',
        textColor: colors.text
      });
      canvasCoverInput.onchange = () => {
        settings.canvasShowProjectCover = canvasCoverInput.checked;
        saveSettings();
        tabContentCache.delete('home');
        updateUI();
      };
      canvasSubContent.appendChild(canvasCoverRow);

      // canvasDebugBadge toggle
      const { row: canvasDebugBadgeRow, input: canvasDebugBadgeInput } = createSettingsToggleRow({
        labelText: 'Show debug badge on canvas items',
        icon: 'fa-bug',
        tooltip: 'Show a DEBUG badge in the canvas sub-section header and debug info on canvas item cards.',
        checked: !!settings.canvasDebugBadge,
        fontSize: '13px',
        textColor: colors.text
      });
      canvasDebugBadgeInput.onchange = () => {
        settings.canvasDebugBadge = canvasDebugBadgeInput.checked;
        saveSettings();
        const badge = canvasSubHeaderLeft.querySelector('#canvasDebugBadgeInline');
        if (badge) badge.style.display = settings.canvasDebugBadge ? 'inline-flex' : 'none';
        tabContentCache.delete('home');
        updateUI();
      };
      canvasSubContent.appendChild(canvasDebugBadgeRow);

      //  Canvas Remote Config ─────────────────────────────────────────────
      const canvasRemoteConfigWarning = createSettingsAlertNote({
        tone: 'warning',
        title: 'Advanced   Canvas Remote Config override',
        text: 'Local override merges with the fetched remote config. Invalid JSON or wrong values can break Canvas welcome/template behavior.',
        colors,
        marginTop: '8px'
      });
      canvasSubContent.appendChild(canvasRemoteConfigWarning);

      const canvasRemoteConfigPanel = document.createElement('div');
      canvasRemoteConfigPanel.style.cssText = `padding:10px; border-radius:10px; border:1px solid ${colors.border}; background:${colors.bgSecondary}; display:flex; flex-direction:column; gap:8px;`;

      const canvasRemoteConfigTitle = document.createElement('div');
      canvasRemoteConfigTitle.style.cssText = `font-size:12px; font-weight:700; color:${colors.text}; display:flex; align-items:center; justify-content:space-between;`;
      canvasRemoteConfigTitle.innerHTML = `<span><i class="fas fa-sliders"></i> Canvas Remote Config</span>`;

      const canvasConfigBtnsRow = document.createElement('div');
      canvasConfigBtnsRow.style.cssText = 'display:flex; gap:6px;';

      const showRawJsonBtn = document.createElement('button');
      showRawJsonBtn.className = 'bypass-btn bypass-btn-secondary';
      showRawJsonBtn.style.cssText = 'width:auto; padding:4px 9px; font-size:10px;';
      showRawJsonBtn.innerHTML = '<i class="fas fa-code"></i> Raw JSON';
      let showingRawJson = false;

      const editConfigDialogBtn = document.createElement('button');
      editConfigDialogBtn.className = 'bypass-btn bypass-btn-primary';
      editConfigDialogBtn.style.cssText = 'width:auto; padding:4px 9px; font-size:10px;';
      editConfigDialogBtn.innerHTML = '<i class="fas fa-pen-to-square"></i> Edit Config';

      canvasConfigBtnsRow.appendChild(showRawJsonBtn);
      canvasConfigBtnsRow.appendChild(editConfigDialogBtn);
      canvasRemoteConfigTitle.appendChild(canvasConfigBtnsRow);
      canvasRemoteConfigPanel.appendChild(canvasRemoteConfigTitle);

      // Dynamic HTML view of effective config
      const effectiveCfg = Object.assign({}, canvasRemoteConfig || {}, canvasRemoteConfigOverride || {});
      const cfgHtmlView = document.createElement('div');
      cfgHtmlView.style.cssText = `display:flex; flex-direction:column; gap:5px;`;
      const renderCfgHtmlView = () => {
        const cfg = Object.assign({}, canvasRemoteConfig || {}, canvasRemoteConfigOverride || {});
        cfgHtmlView.innerHTML = '';
        const fields = [
          { key: 'enabled', label: 'Enabled', type: 'bool' },
          { key: 'welcomeInjectEnabled', label: 'Welcome Inject', type: 'bool' },
          { key: 'welcomeText', label: 'Welcome Text', type: 'text' },
          { key: 'textShapeTemplate', label: 'Text Shape Template', type: 'text' }
        ];
        const allKeys = new Set([...fields.map(f => f.key), ...Object.keys(cfg)]);
        allKeys.forEach(k => {
          const fieldDef = fields.find(f => f.key === k) || { key: k, label: k, type: typeof cfg[k] === 'boolean' ? 'bool' : 'text' };
          const val = cfg[k];
          const isOverridden = Object.prototype.hasOwnProperty.call(canvasRemoteConfigOverride || {}, k);
          const row = document.createElement('div');
          row.style.cssText = `display:flex; align-items:baseline; gap:8px; padding:4px 8px; border-radius:7px; background:${isOverridden ? 'rgba(56,189,248,0.07)' : 'transparent'}; border:1px solid ${isOverridden ? 'rgba(56,189,248,0.2)' : 'transparent'};`;
          const keyEl = document.createElement('span');
          keyEl.style.cssText = `font-size:11px; font-weight:700; color:${colors.textSecondary}; min-width:130px; flex-shrink:0; font-family:Consolas,'Courier New',monospace;`;
          keyEl.textContent = fieldDef.label + (isOverridden ? ' *' : '');
          const valEl = document.createElement('span');
          valEl.style.cssText = `font-size:11px; color:${colors.text}; word-break:break-all; flex:1;`;
          if (fieldDef.type === 'bool' || typeof val === 'boolean') {
            const boolVal = !!val;
            valEl.innerHTML = boolVal
              ? `<span style="color:#4ade80; font-weight:700;"><i class="fas fa-check-circle"></i> Yes</span>`
              : `<span style="color:#f87171; font-weight:700;"><i class="fas fa-times-circle"></i> No</span>`;
          } else if (val === undefined || val === null) {
            valEl.innerHTML = `<span style="color:${colors.textSecondary}; font-style:italic;">not set</span>`;
          } else {
            const strVal = String(val);
            valEl.textContent = strVal.length > 120 ? strVal.slice(0, 120) + '…' : strVal;
          }
          row.appendChild(keyEl);
          row.appendChild(valEl);
          cfgHtmlView.appendChild(row);
        });
        if (isOverridden) {
          const note = document.createElement('div');
          note.style.cssText = `font-size:10px; color:#38bdf8; opacity:0.7;`;
          note.textContent = '* = locally overridden';
          cfgHtmlView.appendChild(note);
        }
      };
      const isOverrideNonEmpty = () => Object.keys(canvasRemoteConfigOverride || {}).length > 0;
      const isOverridden = isOverrideNonEmpty();
      renderCfgHtmlView();
      canvasRemoteConfigPanel.appendChild(cfgHtmlView);

      // Raw JSON textarea (hidden by default)
      const canvasRemoteConfigEditor = document.createElement('textarea');
      canvasRemoteConfigEditor.rows = 7;
      canvasRemoteConfigEditor.spellcheck = false;
      canvasRemoteConfigEditor.value = JSON.stringify(canvasRemoteConfigOverride || {}, null, 2);
      canvasRemoteConfigEditor.style.cssText = `width:100%; padding:10px; border-radius:10px; border:1px solid ${colors.border}; background:${colors.bg}; color:${colors.text}; font-size:12px; font-family:Consolas, 'Courier New', monospace; resize:vertical; display:none; box-sizing:border-box;`;
      canvasRemoteConfigPanel.appendChild(canvasRemoteConfigEditor);

      showRawJsonBtn.onclick = () => {
        showingRawJson = !showingRawJson;
        canvasRemoteConfigEditor.style.display = showingRawJson ? 'block' : 'none';
        cfgHtmlView.style.display = showingRawJson ? 'none' : 'flex';
        showRawJsonBtn.innerHTML = showingRawJson ? '<i class="fas fa-list"></i> Visual View' : '<i class="fas fa-code"></i> Raw JSON';
      };

      // Raw JSON save/reset buttons
      const canvasRemoteConfigActions = document.createElement('div');
      canvasRemoteConfigActions.style.cssText = 'display:flex; gap:8px; flex-wrap:wrap;';

      const saveCanvasRemoteConfigBtn = document.createElement('button');
      saveCanvasRemoteConfigBtn.className = 'bypass-btn bypass-btn-primary';
      saveCanvasRemoteConfigBtn.style.cssText = 'width:auto; padding:7px 10px; font-size:11px;';
      saveCanvasRemoteConfigBtn.innerHTML = '<i class="fas fa-save"></i> Save override from JSON';
      saveCanvasRemoteConfigBtn.onclick = () => {
        try {
          const parsed = JSON.parse(String(canvasRemoteConfigEditor.value || '{}'));
          if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
            showToast('Override must be a JSON object', 'error');
            return;
          }
          saveCanvasRemoteConfigOverride(parsed);
          applyCanvasRemoteConfigOverride();
          renderCfgHtmlView();
          showToast('Canvas override saved', 'success');
        } catch (err) {
          showToast(`Invalid JSON: ${err?.message || err}`, 'error');
        }
      };

      const clearCanvasRemoteConfigBtn = document.createElement('button');
      clearCanvasRemoteConfigBtn.className = 'bypass-btn bypass-btn-secondary';
      clearCanvasRemoteConfigBtn.style.cssText = 'width:auto; padding:7px 10px; font-size:11px;';
      clearCanvasRemoteConfigBtn.innerHTML = '<i class="fas fa-eraser"></i> Reset override';
      clearCanvasRemoteConfigBtn.onclick = () => {
        saveCanvasRemoteConfigOverride({});
        applyCanvasRemoteConfigOverride();
        canvasRemoteConfigEditor.value = '{}';
        renderCfgHtmlView();
        showToast('Canvas override reset', 'success');
      };

      canvasRemoteConfigActions.appendChild(saveCanvasRemoteConfigBtn);
      canvasRemoteConfigActions.appendChild(clearCanvasRemoteConfigBtn);
      canvasRemoteConfigPanel.appendChild(canvasRemoteConfigActions);
      canvasSubContent.appendChild(canvasRemoteConfigPanel);

      // Edit Config dialog button handler
      editConfigDialogBtn.onclick = () => {
        const cfg = Object.assign({}, canvasRemoteConfig || {}, canvasRemoteConfigOverride || {});
        const overlay = document.createElement('div');
        overlay.style.cssText = `position:fixed; inset:0; background:rgba(0,0,0,0.65); z-index:200000; display:flex; align-items:center; justify-content:center;`;
        const dlg = document.createElement('div');
        dlg.style.cssText = `background:${colors.bgSecondary}; border:1px solid ${colors.border}; border-radius:16px; padding:20px; width:min(520px,94vw); max-height:80vh; overflow-y:auto; display:flex; flex-direction:column; gap:14px; box-shadow:0 24px 64px rgba(0,0,0,0.5);`;
        dlg.innerHTML = `<div style="font-size:15px; font-weight:800; color:${colors.text};"><i class="fas fa-sliders" style="color:#38bdf8; margin-right:8px;"></i>Edit Canvas Remote Config</div>`;
        const subTitle = document.createElement('div');
        subTitle.style.cssText = `font-size:11px; color:${colors.textSecondary};`;
        subTitle.textContent = 'Changes here are saved as a local override that merges with the fetched remote config.';
        dlg.appendChild(subTitle);
        const editFields = [
          { key: 'enabled', label: 'enabled', type: 'bool', desc: 'Master enable for canvas interception' },
          { key: 'welcomeInjectEnabled', label: 'welcomeInjectEnabled', type: 'bool', desc: 'Inject welcome content into new sessions' },
          { key: 'welcomeText', label: 'welcomeText', type: 'string', desc: 'Welcome text to inject' },
          { key: 'textShapeTemplate', label: 'textShapeTemplate', type: 'textarea', desc: 'Text shape template JSON' }
        ];
        const editedOverride = Object.assign({}, canvasRemoteConfigOverride || {});
        const inputs = {};
        editFields.forEach(f => {
          const fieldWrap = document.createElement('div');
          fieldWrap.style.cssText = 'display:flex; flex-direction:column; gap:4px;';
          const lbl = document.createElement('div');
          lbl.style.cssText = `font-size:11px; font-weight:700; color:${colors.textSecondary}; display:flex; align-items:center; gap:6px;`;
          lbl.innerHTML = `<span style="font-family:Consolas,'Courier New',monospace;">${escapeHtml(f.label)}</span><span style="font-weight:400;">${escapeHtml(f.desc)}</span>`;
          fieldWrap.appendChild(lbl);
          if (f.type === 'bool') {
            const currentVal = Object.prototype.hasOwnProperty.call(editedOverride, f.key) ? !!editedOverride[f.key] : (typeof cfg[f.key] === 'boolean' ? cfg[f.key] : false);
            const toggleWrap = document.createElement('div');
            toggleWrap.style.cssText = 'display:flex; align-items:center; gap:10px;';
            const sel = document.createElement('select');
            sel.style.cssText = `padding:6px 10px; border-radius:8px; border:1px solid ${colors.border}; background:${colors.bg}; color:${colors.text}; font-size:12px;`;
            ['not set', 'true', 'false'].forEach(v => {
              const opt = document.createElement('option');
              opt.value = v; opt.textContent = v;
              if (Object.prototype.hasOwnProperty.call(editedOverride, f.key)) {
                opt.selected = String(!!editedOverride[f.key]) === v;
              } else { opt.selected = v === 'not set'; }
              sel.appendChild(opt);
            });
            sel.onchange = () => {
              if (sel.value === 'not set') { delete editedOverride[f.key]; }
              else { editedOverride[f.key] = sel.value === 'true'; }
            };
            inputs[f.key] = sel;
            toggleWrap.appendChild(sel);
            fieldWrap.appendChild(toggleWrap);
          } else if (f.type === 'textarea') {
            const ta = document.createElement('textarea');
            ta.rows = 5;
            ta.spellcheck = false;
            ta.style.cssText = `width:100%; padding:8px; border-radius:8px; border:1px solid ${colors.border}; background:${colors.bg}; color:${colors.text}; font-size:11px; font-family:Consolas,'Courier New',monospace; resize:vertical; box-sizing:border-box;`;
            ta.value = Object.prototype.hasOwnProperty.call(editedOverride, f.key) ? String(editedOverride[f.key]) : (cfg[f.key] != null ? String(cfg[f.key]) : '');
            ta.placeholder = '(leave empty to remove from override)';
            ta.onchange = () => { if (ta.value.trim()) { editedOverride[f.key] = ta.value.trim(); } else { delete editedOverride[f.key]; } };
            inputs[f.key] = ta;
            fieldWrap.appendChild(ta);
          } else {
            const inp = document.createElement('input');
            inp.type = 'text';
            inp.style.cssText = `width:100%; padding:8px; border-radius:8px; border:1px solid ${colors.border}; background:${colors.bg}; color:${colors.text}; font-size:12px; box-sizing:border-box;`;
            inp.value = Object.prototype.hasOwnProperty.call(editedOverride, f.key) ? String(editedOverride[f.key]) : (cfg[f.key] != null ? String(cfg[f.key]) : '');
            inp.placeholder = '(leave empty to remove from override)';
            inp.onchange = () => { if (inp.value.trim()) { editedOverride[f.key] = inp.value.trim(); } else { delete editedOverride[f.key]; } };
            inputs[f.key] = inp;
            fieldWrap.appendChild(inp);
          }
          dlg.appendChild(fieldWrap);
        });
        const dlgActions = document.createElement('div');
        dlgActions.style.cssText = 'display:flex; gap:8px; justify-content:flex-end; margin-top:6px;';
        const cancelBtn2 = document.createElement('button');
        cancelBtn2.className = 'bypass-btn bypass-btn-secondary';
        cancelBtn2.style.cssText = 'width:auto; padding:8px 16px; font-size:12px;';
        cancelBtn2.innerHTML = '<i class="fas fa-times"></i> Cancel';
        cancelBtn2.onclick = () => overlay.remove();
        const applyBtn = document.createElement('button');
        applyBtn.className = 'bypass-btn bypass-btn-primary';
        applyBtn.style.cssText = 'width:auto; padding:8px 16px; font-size:12px;';
        applyBtn.innerHTML = '<i class="fas fa-save"></i> Save Override';
        applyBtn.onclick = () => {
          saveCanvasRemoteConfigOverride(editedOverride);
          applyCanvasRemoteConfigOverride();
          canvasRemoteConfigEditor.value = JSON.stringify(editedOverride, null, 2);
          renderCfgHtmlView();
          showToast('Canvas config override saved', 'success');
          overlay.remove();
        };
        dlgActions.appendChild(cancelBtn2);
        dlgActions.appendChild(applyBtn);
        dlg.appendChild(dlgActions);
        overlay.appendChild(dlg);
        overlay.onclick = (e) => { if (e.target === overlay) overlay.remove(); };
        document.body.appendChild(overlay);
      };



      const { row: xhrLogsToggleRow, input: xhrLogsToggleInput } = createSettingsToggleRow({
        labelText: 'Enable Tensor intercept logs',
        icon: 'fa-terminal',
        tooltip: 'Write colorful Tensor intercept logs to the console and the Tensor XHR tab.',
        checked: !!settings.tensorInterceptEnableUiLogs,
        fontSize: '13px',
        textColor: colors.text
      });
      xhrLogsToggleInput.onchange = () => {
        settings.tensorInterceptEnableUiLogs = xhrLogsToggleInput.checked;
        saveSettings();
        tensorInterceptLog('info', `Tensor intercept logs ${settings.tensorInterceptEnableUiLogs ? 'enabled' : 'disabled'}`, { source: 'settings' });
        updateUI();
      };
      xhrSection.content.appendChild(xhrLogsToggleRow);

      const { row: xhrTelegramInjectRow, input: xhrTelegramInjectInput } = createSettingsToggleRow({
        labelText: 'Implemet telegram injection',
        icon: 'fab fa-telegram',
        tooltip: 'Inject Telegram quick queue buttons into native Tensor task hover actions.',
        checked: !!settings.tensorInjectTelegramButtons,
        fontSize: '13px',
        textColor: colors.text
      });
      xhrTelegramInjectInput.onchange = () => {
        settings.tensorInjectTelegramButtons = xhrTelegramInjectInput.checked;
        saveSettings();
        tensorInterceptLog('info', `Tensor Telegram quick injection ${settings.tensorInjectTelegramButtons ? 'enabled' : 'disabled'}`, { source: 'settings' });
        injectBlockedMediaIntoDom();
        updateUI();
      };
      xhrSection.content.appendChild(xhrTelegramInjectRow);

      const { row: xhrDiscordInjectRow, input: xhrDiscordInjectInput } = createSettingsToggleRow({
        labelText: 'Implemnt discord inejction',
        icon: 'fab fa-discord',
        tooltip: 'Inject Discord quick queue buttons into native Tensor task hover actions.',
        checked: !!settings.tensorInjectDiscordButtons,
        fontSize: '13px',
        textColor: colors.text
      });
      xhrDiscordInjectInput.onchange = () => {
        settings.tensorInjectDiscordButtons = xhrDiscordInjectInput.checked;
        saveSettings();
        tensorInterceptLog('info', `Tensor Discord quick injection ${settings.tensorInjectDiscordButtons ? 'enabled' : 'disabled'}`, { source: 'settings' });
        injectBlockedMediaIntoDom();
        updateUI();
      };
