      const _xhrmSubHdr = document.createElement('div');
      _xhrmSubHdr.style.cssText = 'display:flex;align-items:center;justify-content:space-between;padding:9px 14px;background:rgba(99,102,241,0.08);cursor:pointer;user-select:none;';
      const _xhrmSubHdrLeft = document.createElement('div');
