      _xhrmNote.innerHTML = '<strong style="color:#818cf8;"><i class="fas fa-display"></i> XHR Monitor</strong> A floating Wireshark-style panel that visualizes all XHR/fetch intercepts in real time.<br>'
        + '<span style="color:#475569;">• <strong style="color:#4ade80;">Ctrl+Shift+Q</strong> to open/close &nbsp;·&nbsp; Right-click any request row to block or intercept it &nbsp;·&nbsp; Charts update every 2s &nbsp;·&nbsp; Headers sync across tabs</span>';
      _xhrmSubContent.appendChild(_xhrmNote);

      // Open Monitor button
      const _xhrmOpenBtn = document.createElement('button');
      _xhrmOpenBtn.style.cssText = 'width:100%;padding:10px 14px;font-size:12px;font-weight:700;background:linear-gradient(135deg,rgba(99,102,241,0.22),rgba(167,139,250,0.12));border:1px solid rgba(99,102,241,0.35);border-radius:10px;color:#818cf8;display:flex;align-items:center;justify-content:center;gap:8px;cursor:pointer;transition:all 0.15s;';
      _xhrmOpenBtn.innerHTML = '<i class="fas fa-display"></i> Open XHR Monitor &nbsp;<kbd style="font-size:9px;background:rgba(99,102,241,0.15);border:1px solid rgba(99,102,241,0.3);border-radius:4px;padding:1px 5px;color:#818cf8;">Ctrl+Shift+Q</kbd>';
      _xhrmOpenBtn.onmouseenter = () => _xhrmOpenBtn.style.background = 'linear-gradient(135deg,rgba(99,102,241,0.35),rgba(167,139,250,0.22))';
      _xhrmOpenBtn.onmouseleave = () => _xhrmOpenBtn.style.background = 'linear-gradient(135deg,rgba(99,102,241,0.22),rgba(167,139,250,0.12))';
      _xhrmOpenBtn.onclick = () => { fitagBuildMonitor(); };
      _xhrmSubContent.appendChild(_xhrmOpenBtn);

      // Quick-action row (gear + blocked count)
      const _xhrmQuickRow = document.createElement('div');
      _xhrmQuickRow.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;';
      const _mkXhrmQuickBtn = (label, icon, col, onClick) => {
        const b = document.createElement('button');
        b.style.cssText = `flex:1;min-width:90px;padding:6px 10px;border-radius:8px;border:1px solid ${col}35;background:${col}0d;color:${col};font-size:10px;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:5px;transition:all 0.12s;`;
        b.innerHTML = `<i class="fas ${icon}"></i> ${label}`;
        b.onmouseenter = () => b.style.background = col+'20';
        b.onmouseleave = () => b.style.background = col+'0d';
        b.onclick = onClick; return b;
      };
      _xhrmQuickRow.appendChild(_mkXhrmQuickBtn('Quick Settings','fa-gear','#818cf8', () => { fitagBuildMonitor(); setTimeout(xhrmShowGearDialog,120); }));
      _xhrmQuickRow.appendChild(_mkXhrmQuickBtn('Block List','fa-ban','#f87171', () => { fitagBuildMonitor(); setTimeout(()=>{ document.getElementById('xhrm-tab-blocked')?.click(); },120); }));
      _xhrmQuickRow.appendChild(_mkXhrmQuickBtn('Interceptor','fa-filter','#fbbf24', () => { fitagBuildMonitor(); setTimeout(()=>{ document.getElementById('xhrm-tab-modifier')?.click(); },120); }));
      _xhrmSubContent.appendChild(_xhrmQuickRow);

      // Toggles
      const _xhrmToggles = [
        { key:'fitagMonitorEnabled',           label:'Enable XHR Monitor',                icon:'fa-toggle-on',     tip:'Enable the floating XHR Monitor window (Ctrl+Shift+Q)' },
        { key:'fitagMonitorAlwaysVisible',     label:'Always Show Floating Button',       icon:'fa-eye',           tip:'Keep the Bypass floating button visible even when the XHR Monitor panel is open' },
        { key:'fitagMonitorCrossTabSync',       label:'Cross-Tab Header Sync',             icon:'fa-arrows-rotate', tip:'Sync FITAG signing headers across browser tabs via BroadcastChannel' },
        { key:'fitagMonitorAutoOpenOnLimit',    label:'Auto-Open on Rate Limit',           icon:'fa-bell',          tip:'Automatically open the monitor when a rate limit is detected' },
        { key:'fitagMonitorVisualFx',           label:'Visual Effects (Glow / Pulse)',     icon:'fa-star',          tip:'Enable glow and pulse animations in the monitor' },
        { key:'fitagHdrCacheAutoClean',         label:'Auto-Clean Expired Header Cache',   icon:'fa-broom',         tip:'Automatically prune stale signing headers based on TTL' },
      ];
      _xhrmToggles.forEach(({ key, label, icon, tip }) => {
        const { row: tRow, input: tInput } = createSettingsToggleRow({ labelText: label, icon, tooltip: tip, checked: !!settings[key], fontSize: '13px', textColor: colors.text });
        tInput.onchange = () => {
          settings[key] = tInput.checked;
          saveSettings();
          if (key === 'fitagMonitorCrossTabSync' && tInput.checked) fitagInitCrossTabSync();
          // Immediately apply pill visibility when the "Always Show Floating Button" toggle changes
          if (key === 'fitagMonitorAlwaysVisible') {
            const _p = document.getElementById('fitag-pill');
            if (_p) _p.style.display = tInput.checked ? 'flex' : 'none';
            if (tInput.checked) { _fitagInjectPillCSS(); if (!_p) fitagInitFab(); }
          }
        };
        _xhrmSubContent.appendChild(tRow);
      });

      // TTL spinner
      const _ttlRow = document.createElement('div');
