      const _ttlLabel = document.createElement('label');
      _ttlLabel.style.cssText = `font-size:13px;color:${colors.text};flex:1;display:flex;align-items:center;gap:6px;`;
      _ttlLabel.innerHTML = '<i class="fas fa-clock" style="color:#818cf8;font-size:12px;"></i>Header Cache TTL (minutes)';
      const _ttlInput = document.createElement('input');
      _ttlInput.type = 'number'; _ttlInput.min = '5'; _ttlInput.max = '480'; _ttlInput.step = '5';
      _ttlInput.value = String(settings.fitagHdrCacheTTLMins || 60);
      _ttlInput.style.cssText = `width:70px;padding:5px 8px;border-radius:7px;border:1px solid rgba(99,102,241,0.3);background:rgba(0,0,0,0.3);color:#e2e8f0;font-size:12px;text-align:center;`;
      _ttlInput.onchange = () => { settings.fitagHdrCacheTTLMins = Math.max(5, Math.min(480, parseInt(_ttlInput.value)||60)); saveSettings(); };
      _ttlRow.appendChild(_ttlLabel); _ttlRow.appendChild(_ttlInput);
      _xhrmSubContent.appendChild(_ttlRow);

      // IDB stats card
      const _idbCard = document.createElement('div');
      _idbCard.style.cssText = 'padding:10px 12px;border-radius:10px;border:1px solid rgba(99,102,241,0.2);background:rgba(99,102,241,0.05);';
      const _idbCardHdr = document.createElement('div');
      _idbCardHdr.style.cssText = 'font-size:10px;color:#64748b;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px;display:flex;align-items:center;gap:6px;';
      _idbCardHdr.innerHTML = '<i class="fas fa-database" style="color:#818cf8;font-size:9px;"></i>IndexedDB Header Cache<button id="xhrm-idb-refresh" style="margin-left:auto;background:none;border:1px solid rgba(71,85,105,0.3);border-radius:4px;color:#475569;font-size:9px;padding:2px 7px;cursor:pointer;">REFRESH</button>';
      const _idbStatsEl = document.createElement('div');
      _idbStatsEl.id = 'xhrm-idb-stats-content';
      _idbStatsEl.style.cssText = 'font-size:11px;color:#475569;';
      _idbStatsEl.textContent = 'Loading…';
      const _idbActBtns = document.createElement('div');
      _idbActBtns.style.cssText = 'display:flex;gap:6px;margin-top:8px;';
      const _mkIdbBtn = (label, col, onClick) => {
        const b = document.createElement('button');
        b.style.cssText = `flex:1;padding:5px 8px;border-radius:7px;border:1px solid ${col}35;background:${col}0e;color:${col};font-size:10px;font-weight:600;cursor:pointer;`;
        b.textContent = label; b.onclick = onClick; return b;
      };
      const _refreshIdbStats = () => {
        const stats = fitagGetHdrCacheStats();
        _idbStatsEl.innerHTML = `<div style="display:flex;gap:10px;flex-wrap:wrap;">
          <span><b style="color:#818cf8;">${stats.totalPaths}</b> paths</span>
          <span><b style="color:#4ade80;">${stats.freshPaths}</b> fresh</span>
          <span><b style="color:#fbbf24;">${stats.stalePaths}</b> stale</span>
          <span><b style="color:#f87171;">${stats.expiredPaths}</b> expired</span>
          <span><b style="color:#94a3b8;">${stats.estimatedBytes} B</b> est. size</span>
        </div>`;
      };
      _idbActBtns.appendChild(_mkIdbBtn('Clean Stale','#fbbf24',()=>{ fitagCleanHdrCache(); _refreshIdbStats(); showToast('Stale headers cleaned','success'); }));
      _idbActBtns.appendChild(_mkIdbBtn('Clear All','#f87171',()=>{ if(confirm('Clear ALL cached signing headers from IDB?')){ fitagClearAllHdrCache(); _refreshIdbStats(); showToast('Header cache cleared','warning'); } }));
      _idbCard.appendChild(_idbCardHdr);
