      if (!StorageEngine.isIndexedDB()) {
        const sdrSection = createCollapsibleSection('Smart Data Replacement', 'fa-recycle', false);

        const sdrNote = document.createElement('div');
        sdrNote.style.cssText = `padding:10px 12px; border-radius:10px; border:1px solid rgba(34,197,94,0.28); background:rgba(34,197,94,0.07); color:${colors.textSecondary}; font-size:12px; line-height:1.6; margin-bottom:8px;`;
        sdrNote.innerHTML = `<span style="color:#86efac; font-weight:700;"><i class="fas fa-recycle"></i> Smart Data Replacement (SDR)</span><br>
When localStorage approaches the safe limit, SDR <strong>automatically evicts the oldest tasks and cached URLs</strong> to make room for new data  preventing the "blind process" where the tool can no longer read or write its cache.<br><br>
<span style="color:#fbbf24;"><i class="fas fa-exclamation-triangle"></i></span> This section is <strong>only visible in localStorage mode</strong>. If you switch to IndexedDB, SDR is not needed (IndexedDB has virtually unlimited storage).<br><br>
<ul style="margin:4px 0 0 16px; padding:0; line-height:2;">
  <li><i class="fas fa-recycle" style="width:16px;text-align:center;"></i> <b>Pass 1</b>: Removes 40% oldest entries from task cache</li>
  <li><i class="fas fa-link" style="width:16px;text-align:center;"></i> <b>Pass 2</b>: Removes 30% oldest download URL cache entries</li>
  <li><i class="fas fa-user" style="width:16px;text-align:center;"></i> <b>Pass 3</b>: Trims per-account task data to 150 entries</li>
  <li><i class="fas fa-trash-can" style="width:16px;text-align:center;"></i> <b>Pass 4</b>: Clears non-critical caches (config, announcements)</li>
</ul>`;
        sdrSection.content.appendChild(sdrNote);

        const { row: sdrEnableRow, input: sdrEnableInput } = createSettingsToggleRow({
          labelText: 'Enable Smart Data Replacement',
          icon: 'fa-recycle',
          tooltip: 'When localStorage is almost full, automatically remove oldest tasks and cached data to prevent storage failure.',
          checked: settings.smartDataReplacementEnabled !== false,
          fontSize: '14px',
          textColor: colors.text
        });
        sdrEnableInput.onchange = () => {
          settings.smartDataReplacementEnabled = sdrEnableInput.checked;
          saveSettings();
          tensorInterceptLog('info', `Smart Data Replacement ${settings.smartDataReplacementEnabled ? 'enabled' : 'disabled'}`, { source: 'settings' });
          showToast(settings.smartDataReplacementEnabled ? 'SDR enabled  oldest data will be evicted when storage is almost full' : 'SDR disabled  writes will be blocked at the safe limit', settings.smartDataReplacementEnabled ? 'success' : 'warning');
        };
        sdrSection.content.appendChild(sdrEnableRow);

        //  Storage usage bar ────────────────────────────────────────────
        const sdrUsageWrap = document.createElement('div');
        sdrUsageWrap.style.cssText = 'margin-top:8px;';
        const usedBytes = _estimateRealLsUsageBytes();
        const capBytes = _getLsSafeLimitBytes();
        const pct = Math.min(100, (usedBytes / capBytes) * 100);
        const barColor = pct > 90 ? '#ef4444' : pct > 70 ? '#f59e0b' : '#22c55e';
        sdrUsageWrap.innerHTML = `
          <div style="display:flex;justify-content:space-between;font-size:11px;color:${colors.textSecondary};margin-bottom:4px;">
            <span><i class="fas fa-database"></i> localStorage Usage</span>
            <span>${(usedBytes / 1048576).toFixed(2)} MB / ${(capBytes / 1048576).toFixed(1)} MB (${pct.toFixed(0)}%)</span>
          </div>
          <div style="width:100%;height:8px;border-radius:4px;background:${colors.bgSecondary};overflow:hidden;">
            <div style="width:${pct.toFixed(1)}%;height:100%;border-radius:4px;background:${barColor};transition:width 0.3s;"></div>
          </div>
          ${pct > 80 ? `<div style="font-size:10px;color:#f59e0b;margin-top:4px;"><i class="fas fa-exclamation-triangle"></i> Storage is getting full. SDR will automatically evict old data when needed.</div>` : ''}`;
        sdrSection.content.appendChild(sdrUsageWrap);

        //  Manual evict button ──────────────────────────────────────────
        const sdrEvictBtn = document.createElement('button');
        sdrEvictBtn.className = 'bypass-btn bypass-btn-secondary';
        sdrEvictBtn.style.cssText = 'width:100%; padding:8px 10px; font-size:12px; margin-top:8px;';
        sdrEvictBtn.innerHTML = '<i class="fas fa-broom"></i> Evict Old Data Now';
        sdrEvictBtn.onclick = () => {
          if (StorageEngine.isIndexedDB()) {
            showToast('IndexedDB mode  SDR eviction only applies to localStorage mode. No action needed.', 'info');
            return;
          }
          const freed = _smartDataReplacementEvict(0);
          if (_sdrLastEvictCount > 0) {
            showToast(`♻️ Smart Data Replacement evicted ${_sdrLastEvictCount} old entries, freed ~${(freed / 1024).toFixed(0)} KB`, 'success');
          } else {
            showToast('No old data to evict  storage is clean', 'info');
          }
          // refresh the section
          updateUI();
        };
        sdrSection.content.appendChild(sdrEvictBtn);

        form.appendChild(sdrSection.section);
      }

