          // ─── Time Budget ──────────────────────────────────────────────────
          const cgBudHdr = document.createElement('div');
          cgBudHdr.style.cssText = `font-size:10.5px;font-weight:700;color:${colors.textSecondary};text-transform:uppercase;letter-spacing:1px;margin-bottom:8px;display:flex;align-items:center;gap:6px;`;
          cgBudHdr.innerHTML = `<i class="fas fa-chart-pie" style="color:#fbbf24;"></i>Time-Based Budget`;
          cgSection.content.appendChild(cgBudHdr);

          const cgBudDesc = document.createElement('div');
          cgBudDesc.style.cssText = `font-size:11px;color:${colors.textSecondary};margin-bottom:10px;line-height:1.5;padding:8px 12px;border-radius:8px;background:${colors.bgSecondary};border:1px solid ${colors.border};`;
          cgBudDesc.textContent = 'Reads your cached task history to sum credits spent in the selected period. When the total reaches the budget, new task creation is blocked until the period resets.';
          cgSection.content.appendChild(cgBudDesc);

          const { row: cgBudRow, input: cgBudInput } = createSettingsToggleRow({
            labelText: 'Enable Time Budget', icon: 'fa-calendar-check',
            tooltip: 'Block /create when credits spent this period ≥ budget amount',
            checked: !!settings.creditGuardBudgetEnabled, fontSize: '13px', textColor: colors.text, settingKey: 'creditGuardBudgetEnabled'
          });
          cgBudInput.onchange = () => { settings.creditGuardBudgetEnabled = cgBudInput.checked; saveSettings(); _renderCgBudStatus(); };
          cgSection.content.appendChild(cgBudRow);

          const cgBudAmtRow = document.createElement('div');
          cgBudAmtRow.style.cssText = `display:flex;align-items:center;gap:10px;margin:8px 0 8px;padding:10px 14px;border-radius:10px;background:${colors.bgSecondary};border:1px solid ${colors.border};`;
          cgBudAmtRow.innerHTML = `<i class="fas fa-coins" style="color:#fbbf24;flex-shrink:0;font-size:13px;"></i><span style="flex:1;font-size:12px;font-weight:600;color:${colors.text};">Budget Amount (credits)</span>`;
          const cgBudNumInput = document.createElement('input');
          cgBudNumInput.type = 'number'; cgBudNumInput.min = '1'; cgBudNumInput.step = '50';
          cgBudNumInput.value = String(settings.creditGuardBudgetAmount || 500);
          cgBudNumInput.style.cssText = `width:90px;padding:5px 8px;border-radius:7px;border:1px solid ${colors.border};background:${colors.bg};color:${colors.text};font-size:12px;font-weight:700;text-align:right;`;
          cgBudNumInput.onchange = () => {
            const v = parseFloat(cgBudNumInput.value);
            if (!isNaN(v) && v > 0) { settings.creditGuardBudgetAmount = v; saveSettings(); _renderCgBudStatus(); }
            else cgBudNumInput.value = String(settings.creditGuardBudgetAmount);
          };
          cgBudAmtRow.appendChild(cgBudNumInput);
          cgSection.content.appendChild(cgBudAmtRow);

          const cgPeriodRow = document.createElement('div');
