              fiItemsLimitInp.style.cssText = 'width:78px; font-size:11px; padding:3px 6px;';
              fiItemsLimitInp.onchange = () => {
                const v = Math.max(1, Math.min(4096, parseInt(fiItemsLimitInp.value, 10) || 250));
                fiItemsLimitInp.value = String(v);
                settings.fiItemsLibraryStorageLimitMB = v;
                saveSettings();
                saveFiItemsLibrary(loadFiItemsLibrary({ force: true }), { showEvictToast: true, reason: 'storage-limit-change' });
              };
              fiItemsLimitRow.appendChild(fiItemsLimitLbl);
              fiItemsLimitRow.appendChild(fiItemsLimitInp);
