      addPerfMonitorSlider('Ladder hibernate score', 'perfPressureLadderHibernationScore', 1, 20, 0.1, '');
      const perfSeriesColorBox = document.createElement('div');
      perfSeriesColorBox.style.cssText = `grid-column:1/-1;margin-top:6px;padding:10px;border-radius:11px;border:1px solid ${colors.primary || '#38bdf8'}33;background:${colors.bgSecondary}55;display:grid;gap:7px;`;
      perfSeriesColorBox.innerHTML = `<div><b style="color:${colors.text};font-size:11px;"><i class="fas fa-palette" style="color:${colors.primary};"></i> Per-series graph colors</b><div style="color:${colors.textSecondary};font-size:9px;margin-top:2px;">Saved per series and shared by lines, legends, breakpoints, hit markers, regions, notes, and tooltips. Low-contrast choices show a warning.</div></div>`;
      const perfSeriesColorGrid = document.createElement('div');
      perfSeriesColorGrid.style.cssText = 'display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:6px;';
      fiPerfSeriesList(colors.primary || '#22d3ee', true).forEach(series => {
        const row = document.createElement('label');
        const ratio = fiPerfColorContrastRatio(series.color, '#020617');
        row.style.cssText = `display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:7px;padding:7px;border-radius:9px;border:1px solid ${series.color}33;background:${series.color}0b;`;
        row.innerHTML = `<span style="min-width:0;"><b style="display:block;color:${series.color};font-size:10px;">${escapeHtml(series.label)}</b><small style="color:${ratio < 3 ? '#fbbf24' : colors.textSecondary};">${ratio < 3 ? 'Low contrast warning' : `Contrast ${ratio.toFixed(1)}:1`}</small></span><span style="display:flex;gap:5px;align-items:center;"><input type="color" value="${escapeHtml(series.color)}" style="width:34px;height:28px;border:0;background:transparent;cursor:pointer;"><button type="button" title="Reset color" style="border:1px solid ${series.color}44;background:${colors.bg};color:${colors.text};border-radius:7px;padding:5px 7px;cursor:pointer;"><i class="fas fa-rotate-left"></i></button></span>`;
        const colorInput = row.querySelector('input');
        const resetButton = row.querySelector('button');
        colorInput.oninput = () => { fiPerfSetSeriesColor(series.key, colorInput.value, { persist: false, record: false }); const monitor = document.getElementById('fi-perf-floating-monitor'); if (monitor) monitor.querySelector('[data-chart]') && fiPerfDrawCanvas(monitor.querySelector('[data-chart]'), true, { zoom: settings.perfMonitorGraphZoom }); };
        colorInput.onchange = () => { fiPerfSetSeriesColor(series.key, colorInput.value); saveSettingsDebounced(150); };
        resetButton.onclick = event => { event.preventDefault(); fiPerfResetSeriesColor(series.key); saveSettingsDebounced(150); updateUI(false); };
        perfSeriesColorGrid.appendChild(row);
      });
      perfSeriesColorBox.appendChild(perfSeriesColorGrid);
      perfFloatVisualsBox.appendChild(perfSeriesColorBox);
      appearanceSection.content.appendChild(perfFloatVisualsBox);
      (fiPerformanceSettingsContent || appearanceSection.content).appendChild(perfEngineSettingsBox);

      const perfUnitBox = document.createElement('div');
      perfUnitBox.style.cssText = `margin-top:10px;padding:12px;border-radius:12px;border:1px solid rgba(16,185,129,.32);background:linear-gradient(135deg,rgba(16,185,129,.09),${colors.bgSecondary}55);display:grid;gap:9px;`;
      const unitState = fiPerfUnitState();
      const unitAgeSec = unitState.lastOkTs ? Math.max(0, Math.round((Date.now() - unitState.lastOkTs) / 1000)) : null;
      perfUnitBox.innerHTML = `<div style="display:flex;align-items:flex-start;gap:9px;"><div style="width:34px;height:34px;border-radius:10px;background:rgba(16,185,129,.16);display:grid;place-items:center;color:#34d399;flex:0 0 auto;"><i class="fas fa-microchip"></i></div><div style="min-width:0;flex:1;"><div style="font-size:12px;font-weight:950;color:${colors.text};">FI Performance Unit</div><div style="font-size:9.8px;line-height:1.45;color:${colors.textSecondary};">Optional authenticated localhost companion for Windows/browser process CPU and memory plus optional Chromium target metrics. FI never sends tokens, prompts, cookies, request bodies, or query strings.</div></div></div>`;
      const { row: perfUnitEnabledRow, input: perfUnitEnabledInput } = createSettingsToggleRow({
        labelText: 'Connect to FI Performance Unit',
        tooltip: 'Enables asynchronous localhost polling. Native page sampling stays non-blocking if the companion is offline.',
        checked: settings.perfUnitEnabled === true,
        fontSize: '11px',
        textColor: colors.text
      });
      perfUnitEnabledInput.onchange = () => {
        settings.perfUnitEnabled = perfUnitEnabledInput.checked;
        saveSettings();
        if (settings.perfUnitEnabled) void fiPerfUnitMaybeSync(fiPerfCollectSample('performance-unit-enabled', { drainDomBurst: false }), true);
      };
      perfUnitBox.appendChild(perfUnitEnabledRow);
      const addUnitInput = (label, key, type = 'text', min = null, max = null, step = null) => {
        const row = document.createElement('label');
        row.style.cssText = 'display:grid;grid-template-columns:145px minmax(0,1fr);gap:8px;align-items:center;font-size:10.5px;';
        const text = document.createElement('span');
        text.style.cssText = `color:${colors.textSecondary};font-weight:850;`;
        text.textContent = label;
        const input = document.createElement('input');
        input.type = type;
        input.value = String(settings[key] ?? defaultSettings[key] ?? '');
        if (min != null) input.min = String(min);
        if (max != null) input.max = String(max);
        if (step != null) input.step = String(step);
        input.autocomplete = 'off';
        input.style.cssText = `min-width:0;width:100%;padding:6px 8px;border-radius:8px;border:1px solid ${colors.border};background:${colors.bg};color:${colors.text};font:10.5px ${type === 'password' ? 'monospace' : 'system-ui,sans-serif'};`;
        input.onchange = () => {
          if (type === 'number') settings[key] = Math.min(Number(max), Math.max(Number(min), Number(input.value) || Number(defaultSettings[key]) || 0));
          else settings[key] = String(input.value || '').trim();
          saveSettings();
        };
        row.append(text, input);
        perfUnitBox.appendChild(row);
        return input;
      };
      addUnitInput('Local API endpoint', 'perfUnitEndpoint', 'url');
      addUnitInput('Bearer token', 'perfUnitToken', 'password');
      addUnitInput('Polling interval', 'perfUnitPollMs', 'number', 1000, 60000, 500);
      [
        ['Send sanitized page sample', 'perfUnitSendPageSample', 'Only allowlisted numeric performance counters plus the exact Tensor origin and visibility state are sent.'],
        ['Graph system CPU', 'perfUnitShowSystemCpu', 'Adds the green system CPU series when fresh companion evidence exists.'],
        ['Graph browser CPU', 'perfUnitShowBrowserCpu', 'Adds browser-process aggregate CPU. This is not guaranteed to belong to one tab.'],
        ['Graph browser memory', 'perfUnitShowBrowserMemory', 'Adds browser aggregate private/RSS memory scaled as MB/4.'],
        ['Graph target task work', 'perfUnitShowTargetTask', 'Adds CDP target TaskDuration delta when a matching debug target is available.'],
        ['Graph native pressure', 'perfUnitShowNativePressure', 'Adds the explainable native pressure score calculated from bounded recent evidence.'],
        ['Graph estimated crash risk', 'perfUnitShowCrashRisk', 'Adds an estimated browser crash-risk score. This is not an exact browser limit.'],
        ['Graph estimated PC lag risk', 'perfUnitShowLagRisk', 'Adds the combined native system/page lag-risk estimate.'],
        ['Graph browser memory growth', 'perfUnitShowMemoryGrowth', 'Adds the recent native browser RSS trend in MB per minute.'],
        ['Include native data in reports', 'perfUnitIncludeInReports', 'Keep native fields in exported run evidence.'],
        ['Allow priority relief requests', 'perfUnitAllowPriorityActions', 'Still requires companion-side actions to be enabled and an explicit confirmation. Never kills or suspends browser processes.']
      ].forEach(([label, key, tooltip]) => {
        const { row, input } = createSettingsToggleRow({ labelText: label, tooltip, checked: settings[key] === true, fontSize: '10.5px', textColor: colors.text });
        input.onchange = () => { settings[key] = input.checked; saveSettings(); };
        perfUnitBox.appendChild(row);
      });
      const unitStatus = document.createElement('div');
      unitStatus.style.cssText = `padding:7px 8px;border-radius:8px;border:1px solid ${unitState.lastOkTs ? 'rgba(52,211,153,.32)' : 'rgba(148,163,184,.20)'};background:${unitState.lastOkTs ? 'rgba(16,185,129,.08)' : 'rgba(15,23,42,.38)'};color:${unitState.lastOkTs ? '#86efac' : colors.textSecondary};font-size:9.8px;line-height:1.45;`;
      unitStatus.textContent = unitState.lastOkTs ? `Last contact ${unitAgeSec}s ago · ${unitState.source || 'connected'}${unitState.latest?.browserName ? ` · ${unitState.latest.browserName}` : ''}${Number.isFinite(Number(unitState.latest?.nativePressureScore)) ? ` · native pressure ${Number(unitState.latest.nativePressureScore).toFixed(0)}/100 (${unitState.latest.nativeGrade || 'estimated'})` : ''}` : (unitState.lastError || 'Not connected. Start the companion, paste its token, then test the connection.');
      perfUnitBox.appendChild(unitStatus);
      const processRow = document.createElement('label');
      processRow.style.cssText = 'display:grid;grid-template-columns:145px minmax(0,1fr);gap:8px;align-items:center;font-size:10.5px;';
      processRow.innerHTML = `<span style="color:${colors.textSecondary};font-weight:850;">Browser process action</span>`;
      const processSelect = document.createElement('select');
      processSelect.className = 'bypass-select';
      processSelect.style.cssText = 'min-width:0;width:100%;padding:6px 8px;font-size:10px;';
      const updateProcessOptions = rows => {
        const previous = processSelect.value;
        processSelect.replaceChildren();
        if (!Array.isArray(rows) || !rows.length) {
          const option = document.createElement('option');
          option.value = '';
          option.textContent = 'Sync first to list browser processes';
          processSelect.appendChild(option);
          return;
        }
        rows.forEach(process => {
          const option = document.createElement('option');
          option.value = String(process.pid);
          option.textContent = `${process.name} · PID ${process.pid} · ${Number(process.cpuPercent || 0).toFixed(1)}% machine CPU · ${Number(process.rssMB || 0).toFixed(0)} MB`;
          processSelect.appendChild(option);
        });
        if (previous && rows.some(process => String(process.pid) === previous)) processSelect.value = previous;
      };
      updateProcessOptions(unitState.latest?.browserProcesses);
      processRow.appendChild(processSelect);
      perfUnitBox.appendChild(processRow);
      const unitButtons = document.createElement('div');
      unitButtons.style.cssText = 'display:flex;gap:7px;flex-wrap:wrap;';
      const unitButton = (icon, label, color, handler) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'bypass-btn bypass-btn-secondary';
        button.style.cssText = `width:auto;padding:7px 10px;border-radius:8px;border:1px solid ${color}55;background:${color}10;color:${color};font-size:10px;font-weight:900;`;
        button.innerHTML = `<i class="fas ${icon}"></i> ${label}`;
        button.onclick = handler;
        return button;
      };
      unitButtons.appendChild(unitButton('fa-plug-circle-check', 'Test connection', '#34d399', async () => {
        unitStatus.textContent = 'Testing localhost companion…';
        try {
          const result = await fiPerfUnitTestConnection();
          unitStatus.style.color = '#86efac';
          unitStatus.textContent = `Connected · API ${result?.version || '?'} · ${result?.sampler || 'process telemetry'} · actions ${result?.actions_enabled ? 'enabled in companion' : 'off in companion'}`;
          showToast('FI Performance Unit connected.', 'success', 2200);
        } catch (err) {
          unitStatus.style.color = '#fb7185';
          unitStatus.textContent = String(err?.message || err);
          showToast('FI Performance Unit connection failed.', 'error', 2600);
        }
      }));
      unitButtons.appendChild(unitButton('fa-rotate', 'Sync now', '#06b6d4', async () => {
        settings.perfUnitEnabled = true;
        perfUnitEnabledInput.checked = true;
        saveSettings();
        const latest = await fiPerfUnitMaybeSync(fiPerfCollectSample('performance-unit-manual', { drainDomBurst: false }), true);
        if (latest) updateProcessOptions(latest.browserProcesses);
        unitStatus.textContent = latest ? `Synced · browser CPU ${Number(latest.browserCpuPct || 0).toFixed(1)}% · RAM ${Number(latest.browserMemoryMB || 0).toFixed(0)} MB · ${latest.correlationLevel || 'low'} correlation` : (fiPerfUnitState().lastError || 'Sync failed.');
      }));
      const runPriorityAction = async action => {
        try {
          unitStatus.textContent = action === 'lower_browser_priority' ? 'Requesting reversible lower priority…' : 'Requesting priority restore…';
          await fiPerfUnitPriorityAction(action, processSelect.value);
          unitStatus.style.color = '#86efac';
          unitStatus.textContent = action === 'lower_browser_priority' ? `PID ${processSelect.value} lowered to below-normal priority.` : `PID ${processSelect.value} restored to its recorded priority.`;
          showToast('FI Performance Unit action completed.', 'success', 2400);
        } catch (err) {
          unitStatus.style.color = '#fb7185';
          unitStatus.textContent = String(err?.message || err);
          if (!/cancelled/i.test(String(err?.message || err))) showToast('FI Performance Unit action was not applied.', 'error', 2800);
        }
      };
      unitButtons.appendChild(unitButton('fa-gauge-simple-low', 'Lower selected priority', '#fbbf24', () => runPriorityAction('lower_browser_priority')));
      unitButtons.appendChild(unitButton('fa-rotate-left', 'Restore selected priority', '#4ade80', () => runPriorityAction('restore_browser_priority')));
      perfUnitBox.appendChild(unitButtons);
      (fiPerformanceSettingsContent || appearanceSection.content).appendChild(perfUnitBox);

      const dataCenterVisualsBox = document.createElement('div');
      dataCenterVisualsBox.style.cssText = `margin-top:10px;padding:11px;border-radius:10px;border:1px solid ${colors.border};background:${colors.bgSecondary}55;display:grid;gap:9px;`;
      const dataCenterVisualsTitle = document.createElement('div');
